@MainActor
private final class BackgroundTaskCompletion {
    private let task: BGTask
    private var didComplete = false
    private var didClaimCancellationMetric = false

    init(task: BGTask) {
        self.task = task
    }

    func claimCancellationMetric() -> Bool {
        guard !didClaimCancellationMetric else { return false }
        didClaimCancellationMetric = true
        return true
    }

    func complete(success: Bool) {
        guard !didComplete else { return }
        didComplete = true
        task.setTaskCompleted(success: success)
    }
}

import UIKit

@MainActor
final class BackgroundRuntimeContinuation {
    private var identifier: UIBackgroundTaskIdentifier = .invalid
    private var continuedProcessingLease: BackgroundContinuedProcessingLease?
    private var ended = false

    private init(identifier: UIBackgroundTaskIdentifier, continuedProcessingLease: BackgroundContinuedProcessingLease?) {
        self.identifier = identifier
        self.continuedProcessingLease = continuedProcessingLease
    }

    static func begin(name: String, allowsContinuedProcessing: Bool = false) -> BackgroundRuntimeContinuation? {
        let continuedLease = allowsContinuedProcessing
            ? BackgroundContinuedProcessingCoordinator.shared.begin(
                title: "Lumen",
                subtitle: name,
                prefersGPU: true
            )
            : nil

        let runtimeContinuation = BackgroundRuntimeContinuation(identifier: .invalid, continuedProcessingLease: continuedLease)
        let taskID = UIApplication.shared.beginBackgroundTask(withName: name) { [runtimeContinuation] in
            MainActor.assumeIsolated {
                runtimeContinuation.finish(success: false)
            }
        }
        guard taskID != .invalid else {
            continuedLease?.complete(success: false)
            return nil
        }
        runtimeContinuation.identifier = taskID
        return runtimeContinuation
    }

    func end(success: Bool = true) {
        finish(success: success)
    }

    private func finish(success: Bool) {
        guard !ended, identifier != .invalid else { return }
        ended = true
        continuedProcessingLease?.complete(success: success)
        continuedProcessingLease = nil
        UIApplication.shared.endBackgroundTask(identifier)
        identifier = .invalid
    }
}

import Foundation

enum BackgroundTaskKind: String, Sendable {
    case triggerScan
    case memoryConsolidation
    case ragMaintenance
    case modelHousekeeping
    case selfImprovement
}

struct BackgroundTaskPolicyInput: Sendable, Equatable {
    let taskKind: BackgroundTaskKind
    let lowPowerMode: Bool
    let thermalState: DeviceThermalState
    let isForeground: Bool
    let backgroundAgentsEnabled: Bool
    let requiresNetwork: Bool
    let estimatedCost: Int
}

struct BackgroundTaskDecision: Sendable, Equatable {
    let allow: Bool
    let denyReason: String?
    let maxSteps: Int
    let maxTokens: Int
    let allowModelLoading: Bool
    let allowNetwork: Bool
}

enum BackgroundTaskPolicy {
    static func decide(_ input: BackgroundTaskPolicyInput) -> BackgroundTaskDecision {
        guard input.backgroundAgentsEnabled else {
            return .init(allow: false, denyReason: "background agents disabled", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }
        if input.thermalState == .serious || input.thermalState == .critical {
            return .init(allow: false, denyReason: "thermal state disallows background work", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }
        let isLowPowerBackground = input.lowPowerMode && !input.isForeground
        if isLowPowerBackground && input.taskKind != .triggerScan && input.taskKind != .modelHousekeeping {
            return .init(allow: false, denyReason: "low power background mode", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }

        let allowModelLoading = input.taskKind == .selfImprovement ? false : input.isForeground && input.estimatedCost <= 5
        let allowNetwork = input.requiresNetwork && !isLowPowerBackground
        if input.requiresNetwork && !allowNetwork {
            return .init(allow: false, denyReason: "network unavailable for required background task", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }
        let maxSteps: Int
        switch input.taskKind {
        case .triggerScan:
            maxSteps = 2
        case .selfImprovement:
            maxSteps = 3
        case .memoryConsolidation, .ragMaintenance, .modelHousekeeping:
            maxSteps = 1
        }

        let maxTokens = input.taskKind == .selfImprovement ? 0 : 256
        return .init(allow: true, denyReason: nil, maxSteps: maxSteps, maxTokens: maxTokens, allowModelLoading: allowModelLoading, allowNetwork: allowNetwork)
    }
}

