    listeningTimeoutTask?.cancel()
    listeningTimeoutTask = nil
    sessionState = .unavailable
    activateVoiceState(VoiceStateID.unavailable)
    VoiceService.shared.speak(message, voiceID: nil, rate: 0.46) { [weak self] in
