    let rows: [(String, String)] = [
        ("Session", sessionState.rawValue),
        ("Voice", VoiceService.shared.lastError ?? (VoiceService.shared.isListening ? "Listening" : VoiceService.shared.isSpeaking ? "Speaking" : "Ready")),
