@MainActor
enum MemoryConsolidator {
    static func consolidate(
        context: ModelContext,
        metricsStore: RuntimeMetricsStore = .shared,
        promoteQueuedCaptures: Bool = false
    ) async {
        let drain = promoteQueuedCaptures
            ? await MemoryCaptureQueue.drain(context: context, allowPromotion: true)
            : nil
        let all: [MemoryItem]
        do {
            all = try context.fetch(FetchDescriptor<MemoryItem>())
        } catch {
            try? await metricsStore.appendMetric(.init(timestamp: Date(), runtimeName: "memory", taskKind: "consolidation", modelIDHash: nil, policySummary: policySummary(deleted: 0, drain: drain), latencyMs: nil, success: false, errorCode: RuntimeMetricErrorSanitizer.code(for: error), thermalState: .from(processThermalState: ProcessInfo.processInfo.thermalState), lowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled, memoryWarningCount: MemoryPressureMonitor.shared.warningCount))
            return
        }
        var seen = Set<String>()
        var deleted = 0
        for item in all.sorted(by: { $0.createdAt > $1.createdAt }) {
            let key = item.content.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if seen.contains(key), !item.isPinned { context.delete(item); deleted += 1 } else { seen.insert(key) }
        }
        do {
            try context.save()
            try? await metricsStore.appendMetric(.init(timestamp: Date(), runtimeName: "memory", taskKind: "consolidation", modelIDHash: nil, policySummary: policySummary(deleted: deleted, drain: drain), latencyMs: nil, success: true, errorCode: nil, thermalState: .from(processThermalState: ProcessInfo.processInfo.thermalState), lowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled, memoryWarningCount: MemoryPressureMonitor.shared.warningCount))
        } catch {

            try? await metricsStore.appendMetric(.init(timestamp: Date(), runtimeName: "memory", taskKind: "consolidation", modelIDHash: nil, policySummary: policySummary(deleted: deleted, drain: drain), latencyMs: nil, success: false, errorCode: RuntimeMetricErrorSanitizer.code(for: error), thermalState: .from(processThermalState: ProcessInfo.processInfo.thermalState), lowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled, memoryWarningCount: MemoryPressureMonitor.shared.warningCount))
        }
    }

    private static func policySummary(deleted: Int, drain: MemoryCaptureDrainResult?) -> String {
        var parts = ["dedupe deleted=\(deleted)"]
        if let drain {
            if let skippedReason = drain.skippedReason {
                parts.append("queued skipped=\(skippedReason) remaining=\(drain.remainingDescription)")
            } else {
                parts.append("queued attempted=\(drain.attempted) promoted=\(drain.promoted) remaining=\(drain.remainingDescription)")
            }
        }
        return parts.joined(separator: "; ")
    }
}

import Foundation
import SwiftData

struct MemoryContextResult {
    let selected: [MemoryItem]
    let totalChars: Int
    let totalTokens: Int
    let candidateCount: Int
    let reasons: [UUID: String]
    let sourceIDs: [UUID]
    let tierCounts: [String: Int]
    let hierarchyPassApplied: Bool
    let diagnostic: String?

    init(
        selected: [MemoryItem],
        totalChars: Int,
        totalTokens: Int? = nil,
        candidateCount: Int? = nil,
        reasons: [UUID: String],
        sourceIDs: [UUID],
        tierCounts: [String: Int] = [:],
        hierarchyPassApplied: Bool = false,
        diagnostic: String? = nil
    ) {
        self.selected = selected
        self.totalChars = max(0, totalChars)
        self.totalTokens = totalTokens ?? ContextBudgetAllocator.estimateTokens(forCharacterCount: max(0, totalChars))
        self.candidateCount = candidateCount ?? selected.count
        self.reasons = reasons
        self.sourceIDs = sourceIDs
        self.tierCounts = tierCounts
        self.hierarchyPassApplied = hierarchyPassApplied
        self.diagnostic = diagnostic
    }
}

enum MemoryContextBuilder {
    enum Tier: String, CaseIterable {
        case pinned
        case working
        case episodic
        case semantic

        var primaryLimit: Int {
            switch self {
            case .pinned: Int.max
            case .working: 2
            case .episodic: 2
            case .semantic: 4
            }
        }
    }

    @MainActor
    static func build(query: String, budgetChars: Int, context: ModelContext) -> MemoryContextResult {
        let budgetChars = max(0, budgetChars)
        let all: [MemoryItem]
        do {
            all = try context.fetch(FetchDescriptor<MemoryItem>())
        } catch {
            return MemoryContextResult(
                selected: [],
                totalChars: 0,
                candidateCount: 0,
                reasons: [:],
                sourceIDs: [],
                diagnostic: "fetch_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
            )
        }
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let hasQuery = !q.isEmpty
        let terms = queryTerms(q)
        let now = Date()
        let ranked = all
            .filter { !MemoryStore.isExpired($0, now: now) }
            .map { item in

            RankedMemory(item: item, tier: tier(for: item, now: now), score: score(item, q, terms: terms, hasQuery: hasQuery, now: now))
        }
        .sorted(by: rank)

    var picked: [RankedMemory] = []
    var chars = 0
    var tierCounts: [Tier: Int] = [:]
    var pickedIDs = Set<UUID>()

    func canFit(_ ranked: RankedMemory) -> Bool {
        chars + contextChars(for: ranked.item) <= budgetChars
    }

    func pick(_ ranked: RankedMemory) {
        picked.append(ranked)
        chars += contextChars(for: ranked.item)
        tierCounts[ranked.tier, default: 0] += 1
        pickedIDs.insert(ranked.item.id)
    }

    for m in ranked {
        guard canFit(m) else { continue }
        guard tierCounts[m.tier, default: 0] < m.tier.primaryLimit else { continue }
        pick(m)
    }

    if picked.count < ranked.count {
        for m in ranked where !pickedIDs.contains(m.item.id) {
            guard canFit(m) else { continue }
            pick(m)
        }
    }

    let selected = picked.map(\.item)
    var reasons: [UUID: String] = [:]
    for m in picked {
        let queryMatched = queryMatches(m.item, q: q, terms: terms, hasQuery: hasQuery)
        let base = m.item.isPinned ? "pinned" : (queryMatched ? "query-match" : "recency")
        reasons[m.item.id] = "\(m.tier.rawValue):\(base)"
    }

    return .init(
        selected: selected,
        totalChars: chars,
        candidateCount: all.count,
        reasons: reasons,
        sourceIDs: selected.map(\.id),
        tierCounts: Dictionary(uniqueKeysWithValues: Tier.allCases.map { ($0.rawValue, tierCounts[$0, default: 0]) }),
        hierarchyPassApplied: Set(picked.map(\.tier)).count > 1
    )
}

private static func score(_ m: MemoryItem, _ q: String, terms: [String], hasQuery: Bool, now: Date) -> Double {
    var s = 0.0
    if m.isPinned { s += 1.8 }
    if hasQuery && m.content.lowercased().contains(q) { s += 1.0 }
    if hasQuery && m.topic?.lowercased().contains(q) == true { s += 0.7 }
    s += termCoverage(item: m, terms: terms) * 0.9
    switch m.memoryKind {
    case .preference, .person, .project: s += 0.35
    case .conversation: s += 0.15
    case .fact: break

    }
    s += max(0, 0.3 - now.timeIntervalSince(m.createdAt)/(60*60*24*365))
    return s
}

private struct RankedMemory {
    let item: MemoryItem
    let tier: Tier
    let score: Double
}

private static func rank(_ lhs: RankedMemory, _ rhs: RankedMemory) -> Bool {
    if lhs.score != rhs.score { return lhs.score > rhs.score }
    if lhs.tier != rhs.tier { return tierPriority(lhs.tier) > tierPriority(rhs.tier) }
    return lhs.item.createdAt > rhs.item.createdAt
}

private static func tierPriority(_ tier: Tier) -> Int {
    switch tier {
    case .pinned: 4
    case .semantic: 3
    case .episodic: 2
    case .working: 1
    }
}

private static func tier(for item: MemoryItem, now: Date) -> Tier {
    if item.isPinned { return .pinned }
    if item.memoryKind == .conversation {
        return now.timeIntervalSince(item.createdAt) < 60 * 60 * 24 * 2 ? .working : .episodic
    }
    if item.freshnessClass == MemoryFreshnessClass.volatile.rawValue || item.freshnessClass == MemoryFreshnessClass.shortLived.rawValue {
        return .episodic
    }
    return .semantic
}

private static func contextChars(for item: MemoryItem) -> Int {
    min(220, item.content.count)
}

private static func queryMatches(_ item: MemoryItem, q: String, terms: [String], hasQuery: Bool) -> Bool {
    guard hasQuery else { return false }
    if item.content.lowercased().contains(q) || item.topic?.lowercased().contains(q) == true { return true }
    return termCoverage(item: item, terms: terms) > 0
}

private static func termCoverage(item: MemoryItem, terms: [String]) -> Double {
    guard !terms.isEmpty else { return 0 }
    let content = item.content.lowercased()
    let topic = item.topic?.lowercased() ?? ""
    let matches = terms.filter { content.contains($0) || topic.contains($0) }
    return Double(matches.count) / Double(terms.count)
}

private static func queryTerms(_ query: String) -> [String] {
    let stopwords: Set<String> = [
        "about", "after", "again", "avec", "been", "dans", "does", "from", "have", "into",
        "pour", "that", "this", "what", "when", "where", "with", "your",

            "alors", "avoir", "comme", "elle", "fait", "mais", "nous", "plus", "quoi",
            "sans", "sont", "tout", "vous"
        ]
        var seen = Set<String>()
        return query
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { $0.count >= 3 && !stopwords.contains($0) }
            .filter { seen.insert($0).inserted }
    }
}

import Foundation
import SwiftData

@MainActor
final class MemoryEngine {
    struct SearchResult {
        let items: [MemoryItem]
        let mode: String
        let diagnostic: String?
    }

    func search(query: String, limit: Int, context: ModelContext) async -> [MemoryItem] {
        await searchWithDiagnostics(query: query, limit: limit, context: context).items
    }

    func searchWithDiagnostics(query: String, limit: Int, context: ModelContext) async -> SearchResult {
        let result = await MemoryStore.recallWithDiagnostics(query: query, context: context, limit: limit)
        return SearchResult(items: result.items, mode: result.mode, diagnostic: result.diagnostic)
    }

    func buildContext(query: String, budget: Int, context: ModelContext) -> MemoryContextResult {
        MemoryContextBuilder.build(query: query, budgetChars: budget, context: context)
    }

    func extractCandidates(from messages: [ChatMessage], conversationID: UUID?) -> [MemoryCandidate] {
        messages.compactMap { message in
            guard message.messageRole == .user else { return nil }
            let t = message.content.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !t.isEmpty else { return nil }
            let lower = t.lowercased()
            let explicit: MemoryUserExplicitness
            let reason: String
            if lower.contains("remember that") { explicit = .explicitPreference; reason = "remember directive" }
            else if lower.hasPrefix("actually") { explicit = .correction; reason = "user correction" }
            else if lower.contains("i prefer") { explicit = .explicitPreference; reason = "stated preference" }
            else if lower.contains("for lumen") { explicit = .projectFact; reason = "project declaration" }
            else { explicit = .inferred; reason = "pattern match" }
            return MemoryCandidate(text: String(t.prefix(220)), kind: "fact", topics: [], conversationID: conversationID, messageID: message.id, createdAt: message.createdAt, confidence: 0.6, extractionReason: reason, userExplicitness: explicit, sensitivity: .normal)
        }
    }

    func saveCandidateIfAllowed(_ candidate: MemoryCandidate, context: ModelContext) async throws {
        let result = MemoryScorer.score(candidate: candidate)
        guard result.decision == .save else { return }

        try await MemoryStore.remember(candidate.text, kind: .fact, source: "memory-engine", topic: candidate.topics.first, context: context)
    }

    func consolidateDueMemories(context: ModelContext) async {
        await MemoryConsolidator.consolidate(context: context, promoteQueuedCaptures: true)
    }
    func deleteMemory(id: UUID, context: ModelContext) throws {
        var descriptor = FetchDescriptor<MemoryItem>(predicate: #Predicate { $0.id == id })
        descriptor.fetchLimit = 1
        if let item = try context.fetch(descriptor).first {
            context.delete(item)
            try context.save()
        }
    }
    func pinMemory(id: UUID, context: ModelContext) throws {
        var descriptor = FetchDescriptor<MemoryItem>(predicate: #Predicate { $0.id == id })
        descriptor.fetchLimit = 1
        if let item = try context.fetch(descriptor).first {
            item.isPinned = true
            try context.save()
        }
    }
}

