nonisolated private static func rerankedScore(query: String, chunk: RAGChunk, baseScore: Double, now: Date = Date()) -> Double {
    let terms = queryTerms(query)
    guard !terms.isEmpty else { return clamped(baseScore) }

    let content = chunk.content.lowercased()
    let title = chunk.sourceName.lowercased()
    let matchedTerms = terms.filter { content.contains($0) || title.contains($0) }
    let lexicalCoverage = Double(matchedTerms.count) / Double(terms.count)
    let titleCoverage = Double(terms.filter { title.contains($0) }.count) / Double(terms.count)
    let recency = max(0, 0.08 - now.timeIntervalSince(chunk.createdAt) / (60 * 60 * 24 * 365 * 4))

    return clamped((baseScore * 0.70) + (lexicalCoverage * 0.22) + (titleCoverage * 0.08) + recency)
}

nonisolated private static func focusedExcerpt(query: String, content: String, maxLength: Int) -> (text: String, offsetStart: Int?, offsetEnd: Int?) {
    let boundedMax = max(64, maxLength)
    guard content.count > boundedMax else {
        return (content.trimmingCharacters(in: .whitespacesAndNewlines), 0, content.count)
    }

    let lower = content.lowercased()
    let terms = queryTerms(query)
    let firstMatch = terms
        .compactMap { term -> String.Index? in lower.range(of: term)?.lowerBound }
        .min()

    guard let matchIndex = firstMatch else {
        let end = content.index(content.startIndex, offsetBy: boundedMax, limitedBy: content.endIndex) ?? content.endIndex
        return (String(content[..<end]).trimmingCharacters(in: .whitespacesAndNewlines), 0, content.distance(from: content.startIndex, to: end))
    }

    let halfWindow = boundedMax / 2
    let matchOffset = content.distance(from: content.startIndex, to: matchIndex)
    let startOffset = max(0, matchOffset - halfWindow)
    let endOffset = min(content.count, startOffset + boundedMax)
    let start = content.index(content.startIndex, offsetBy: startOffset)
    let end = content.index(content.startIndex, offsetBy: endOffset)

        var excerpt = String(content[start..<end]).trimmingCharacters(in: .whitespacesAndNewlines)
        if startOffset > 0 { excerpt = "... " + excerpt }
        if endOffset < content.count { excerpt += " ..." }
        return (excerpt, startOffset, endOffset)
    }

    nonisolated private static func queryTerms(_ query: String) -> [String] {
        let stopwords: Set<String> = [
            "about", "after", "avec", "dans", "from", "have", "into", "pour", "that", "this", "what", "when", "where", "with"
        ]
        var seen = Set<String>()
        return query.lowercased()
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { $0.count >= 3 && !stopwords.contains($0) }
            .filter { seen.insert($0).inserted }
    }

    nonisolated private static func clamped(_ value: Double) -> Double {
        min(1, max(0, value))
    }
}

import Foundation
import SwiftData

@MainActor
final class RAGIndexer {
    func indexText(source: RAGSource, title: String, text: String, metadata: [String:String], context: ModelContext) async throws -> Int {
        let type = RAGSourceType(rawValue: source.type) ?? .note
        let chunks = ChunkingStrategy.chunk(text, type: .plain)
        var pending: [RAGChunk] = []
        var activeEmbeddingMetadata: RAGEmbeddingIndexMetadata?
        for (i,c) in chunks.enumerated() {
            let embeddingResult: EmbeddingRuntimeResult
            do {
                let embeddingText = SemanticEmbeddingText.document(
                    content: c.text,
                    sourceName: title,
                    sourceType: type.rawValue,
                    chunkIndex: i
                )
                embeddingResult = try await AssistantKernel.runEmbeddingWithIdentity(text: embeddingText)
            } catch is CancellationError {
                throw CancellationError()
            } catch {
                throw RAGIndexingError.embeddingFailed
            }
            let embedding = embeddingResult.vector
            guard !embedding.isEmpty else { throw RAGIndexingError.emptyEmbedding }
            let embeddingMetadata = RAGEmbeddingIndexMetadata(
                formatVersion: SemanticEmbeddingText.formatVersion,
                modelIdentifier: embeddingResult.modelIdentifier,
                dimension: embedding.count
            )
            if let activeEmbeddingMetadata, activeEmbeddingMetadata != embeddingMetadata {
                RAGVectorIndex.shared.invalidate()
                pending.removeAll(keepingCapacity: true)
                throw RAGIndexingError.embeddingIdentityChanged
            }
            if activeEmbeddingMetadata == nil {
                _ = RAGVectorIndex.shared.ensureLoaded(context: context, metadata: embeddingMetadata)
                activeEmbeddingMetadata = embeddingMetadata
            }
            let chunk = RAGChunk(
                content: c.text,
                sourceType: type,
                sourceName: title,
                sourceRef: source.ref,
                chunkIndex: i,
                embedding: embedding,
                embeddingFormatVersion: embeddingMetadata.formatVersion,
                embeddingModelIdentifier: embeddingMetadata.modelIdentifier,

                embeddingDimension: embeddingMetadata.dimension
            )
            pending.append(chunk)
        }
        for chunk in pending {
            context.insert(chunk)
        }
        do {
            try context.save()
        } catch {
            for chunk in pending {
                context.delete(chunk)
            }
            throw error
        }
        var appendedAll = true
        for chunk in pending where !chunk.embedding.isEmpty {
            guard RAGVectorIndex.shared.append(
                id: chunk.persistentModelID,
                bucket: chunk.sourceType,
                vector: chunk.embedding,
                metadata: RAGEmbeddingIndexMetadata(
                    formatVersion: chunk.embeddingFormatVersion,
                    modelIdentifier: chunk.embeddingModelIdentifier,
                    dimension: chunk.embeddingDimension
                )
            ) else {
                appendedAll = false
                break
            }
        }
        if !appendedAll {
            guard let activeEmbeddingMetadata else {
                throw RAGIndexingError.vectorIndexUnavailable
            }
            RAGVectorIndex.shared.invalidate()
            let reload = RAGVectorIndex.shared.ensureLoaded(context: context, metadata: activeEmbeddingMetadata)
            guard reload.mode != "failed" else {
                throw RAGIndexingError.vectorIndexUnavailable
            }
        }
        return pending.count
    }
}

enum RAGIndexingError: Error, Sendable, Equatable {
    case embeddingFailed
    case emptyEmbedding
    case embeddingIdentityChanged
    case vectorIndexUnavailable
}

