private func runAudit() {
    let currentMessages = Array(messages.suffix(200))
    DispatchQueue.global(qos: .userInitiated).async {
        let loadResult = auditor.loadManifestFromStoreBundleOrRuntimeFallback()
        let auditReport = auditor.audit(manifest: loadResult.manifest)
        let scenarios = scenarioRunner.validateStaticScenarios(manifest: loadResult.manifest)
        DispatchQueue.main.async {
            let modelReport = behaviorAuditor.audit(manifest: loadResult.manifest, messages: currentMessages)
            report = auditReport
            behaviorReport = modelReport
            scenarioResults = scenarios
            manifestSource = loadResult.source
            usedRuntimeFallback = loadResult.usedRuntimeFallback
            errorMessage = nil
        }
    }
}

private func runLiveTraceSmokeTest() {
    cancelLiveTraceSmokeTestForSceneTransition()

    let runID = UUID()
    isRunningLiveTraceSmokeTest = true
    liveTraceSmokeRunID = runID
    lastLiveTraceSmokeSummary = AgentKernelBridgeSmokeTestExpectation.startingSummary
    errorMessage = nil

    let task = Task.detached(priority: .utility) {
        defer {
            Task { @MainActor in
                finishLiveTraceSmokeTask(runID: runID)
            }
        }

        let traceReadLimit = 500
        guard !Task.isCancelled else { return }
        let startedAt = Date()
        let beforeLastTraceID = await AgentBehaviorTraceRecorder.recentAsync(limit: 1).last?.id
        guard !Task.isCancelled else { return }

        let req = AgentRequest(
            systemPrompt: "You are Lumen. Answer concisely and do not expose hidden reasoning.",
            history: [],
            userMessage: "\(AgentKernelBridgeSmokeTestExpectation.promptPrefix): explain in one sentence why a sharp chisel is safer than a dull one.",
            temperature: 0.1,
            topP: 0.7,
            repetitionPenalty: 1.05,
            maxTokens: 160,

    maxSteps: 1,
    availableTools: ToolRegistry.all,
    relevantMemories: []
)

var finalText = ""
#if DEBUG
let events = await AssistantKernel.shared.runLegacyAgentBridge(
    req,
    options: .init(
        modelContext: nil,
        conversationID: req.conversationID,
        turnID: req.turnID,
        groundingMode: .rolePipeline,
        allowDegradedGrounding: true,
        preventDoubleGrounding: true,
        diagnosticsEnabled: false
    )
)
for await event in events {
    guard !Task.isCancelled else { return }

    switch event {
    case .token(let chunk), .finalDelta(let chunk):
        finalText += chunk
    case .final(let text):
        if !text.isEmpty { finalText = text }
    case .done(let text, _):
        if !text.isEmpty { finalText = text }
    case .error(let message):
        await MainActor.run {
            guard liveTraceSmokeRunID == runID else { return }
            errorMessage = message
        }
    case .step, .stepDelta, .toolInvocation, .toolResult, .diagnostic:
        break
    }
}
#else
await MainActor.run {
    guard liveTraceSmokeRunID == runID else { return }
    errorMessage = "Kernel migration smoke test is DEBUG-only."
}
#endif

guard !Task.isCancelled else { return }

let recentTraces = await AgentBehaviorTraceRecorder.recentAsync(limit: traceReadLimit)
guard !Task.isCancelled else { return }

let recordedTraceCount = recentTraces.filter { trace in
    trace.createdAt >= startedAt
}.count
let tailChanged = recentTraces.last?.id != beforeLastTraceID
let summary = AgentKernelBridgeSmokeTestExpectation.completedSummary(
    recordedTraceCount: recordedTraceCount,
    tailChanged: tailChanged,
    producedOutput: !finalText.isEmpty
)
await MainActor.run {

            guard liveTraceSmokeRunID == runID else { return }
            lastLiveTraceSmokeSummary = summary
        }
    }

    liveTraceSmokeTask = task
    liveTraceCancellationID = AppCancellationBus.shared.register(task, category: .diagnostics)
}

private func cancelLiveTraceSmokeTestForSceneTransition() {
    let task = liveTraceSmokeTask
    let cancellationID = liveTraceCancellationID
    liveTraceSmokeTask = nil
    liveTraceCancellationID = nil
    liveTraceSmokeRunID = nil
    isRunningLiveTraceSmokeTest = false
    task?.cancel()
    if let cancellationID {
        AppCancellationBus.shared.unregister(cancellationID, category: .diagnostics)
    }
}

private func finishLiveTraceSmokeTask(runID: UUID) {
    guard liveTraceSmokeRunID == runID else { return }
    if let liveTraceCancellationID {
        AppCancellationBus.shared.unregister(liveTraceCancellationID, category: .diagnostics)
    }
    liveTraceCancellationID = nil
    liveTraceSmokeTask = nil
    liveTraceSmokeRunID = nil
    isRunningLiveTraceSmokeTest = false
}

