private func strictToolExecutableTurn(_ turn: AgentTurn) -> AgentTurn {
    guard turn.hadNoise, turn.action != nil else { return turn }
    return AgentTurn(
        thought: nil,
        action: nil,
        final: nil,
        parseError: .noisyOutput,
        hadNoise: true
    )
}

