nonisolated struct RelativeDuration: Sendable, Equatable {
    enum Unit: Sendable, Equatable {
        case seconds
        case minutes
        case hours
        case days
    }

    let value: Int
    let unit: Unit

    var seconds: Int {
        switch unit {
        case .seconds: return Self.clamped(value, min: 1, max: 24 * 60 * 60)
        case .minutes: return Self.scaledSeconds(value, multiplier: 60, min: 60, max: 24 * 60 * 60)
        case .hours: return Self.scaledSeconds(value, multiplier: 60 * 60, min: 60 * 60, max: 24 * 60 * 60)
        case .days: return Self.scaledSeconds(value, multiplier: 24 * 60 * 60, min: 24 * 60 * 60, max: 7 * 24 * 60 * 60)
        }
    }

    var minutesCeiled: Int {
        max(1, min(7 * 24 * 60, Int(ceil(Double(seconds) / 60.0))))
    }

    static func parse(from text: String) -> RelativeDuration? {
        let normalizedText = text.lowercased()
        guard let regex = try? NSRegularExpression(
            pattern: #"(?i)\b(?:in|for|after)\s+(\d+)\s*(seconds?|secs?|sec|minutes?|mins?|min|hours?|hrs?|hr|days?)\b"#
        ) else { return nil }
        let ns = normalizedText as NSString
        guard let match = regex.firstMatch(in: normalizedText, range: NSRange(location: 0, length: ns.length)),
              match.numberOfRanges > 2,
              let value = Int(ns.substring(with: match.range(at: 1))) else {
            return nil
        }
        let rawUnit = ns.substring(with: match.range(at: 2))
        let unit: Unit
        if rawUnit.hasPrefix("sec") || rawUnit.hasPrefix("second") {
            unit = .seconds
        } else if rawUnit.hasPrefix("min") || rawUnit.hasPrefix("minute") {
            unit = .minutes
        } else if rawUnit.hasPrefix("hr") || rawUnit.hasPrefix("hour") {
            unit = .hours
        } else if rawUnit.hasPrefix("day") {
            unit = .days
        } else {
            return nil
        }
        return RelativeDuration(value: max(1, value), unit: unit)
    }

    static func containsExplicitRelativeSyntax(_ text: String) -> Bool {
        normalized(text).range(

            of: #"(?i)\b(?:in|for|after)\s+\S+\s+(seconds?|secs?|sec|minutes?|mins?|min|hours?|hrs?|hr|days?)\b"#,
            options: .regularExpression
        ) != nil
    }

    private static func clamped(_ value: Int, min minimum: Int, max maximum: Int) -> Int {
        Swift.max(minimum, Swift.min(maximum, value))
    }

    private static func scaledSeconds(_ value: Int, multiplier: Int, min minimum: Int, max maximum: Int) -> Int {
        guard value <= maximum / multiplier else { return maximum }
        return clamped(value * multiplier, min: minimum, max: maximum)
    }

    private static func normalized(_ text: String) -> String {
        text.lowercased()
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

nonisolated enum AlarmCommandClassifier {
    static func classifyAlarmCommandKind(_ normalizedText: String) -> AlarmCommandKind {
        let text = normalized(normalizedText)
        guard !text.isEmpty else { return .unknown }

        if containsAny(text, ["auth status", "authorization status", "permission status", "alarm permission status", "alarm auth status"]) {
            return .authorizationStatus
        }
        if containsAny(text, ["request alarm authorization", "request authorization", "request permission", "ask for alarm authorization", "ask for authorization", "ask for permission"]) {
            return .requestAuthorization
        }
        if containsAny(text, ["list active alarms", "show active alarms", "list alarms", "show alarms", "active alarms", "all alarms", "list alarm"]) {
            return .list
        }
        if containsAny(text, ["pause alarm", "pause the alarm"]) || text.hasPrefix("pause ") { return .pause }
        if containsAny(text, ["resume alarm", "resume the alarm"]) || text.hasPrefix("resume ") { return .resume }
        if containsAny(text, ["stop alarm", "stop the alarm"]) || text.hasPrefix("stop ") { return .stop }
        if containsAny(text, ["snooze alarm", "snooze the alarm"]) || text.hasPrefix("snooze ") { return .snooze }
        if containsAny(text, ["cancel alarm", "cancel the alarm", "delete alarm", "delete the alarm", "remove alarm", "remove the alarm"]) || text.hasPrefix("cancel ") {
            return .cancel
        }

    if containsAny(text, ["countdown", "timer", "start a timer", "start timer"]) {
        return .countdown
    }
    if containsAny(text, ["schedule alarm", "schedule an alarm", "set alarm", "set an alarm", "create alarm", "create an alarm", "add alarm", "add an alarm", "wake me", "wake us"]) {
        return .schedule
    }
    if text == "alarm" || text == "alarms" || text == "set alarm" || text == "set an alarm" {
        return .unknown
    }
    return .unknown
}

static func firstUUID(in text: String) -> String? {
    firstCapture(in: text, pattern: #"(\b[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\b)"#)
}

static func hasTimeOrDate(_ text: String) -> Bool {
    if RelativeDuration.parse(from: text) != nil { return true }
    return normalized(text).range(
        of: #"(?i)\b(\d{1,2}(:\d{2})?\s*(am|pm)?|noon|midnight|morning|afternoon|evening|tonight|tomorrow|today)\b"#,
        options: .regularExpression
    ) != nil
}

static func hasDuration(_ text: String) -> Bool {
    RelativeDuration.parse(from: text) != nil
}

static func hasMutationTarget(_ text: String) -> Bool {
    if firstUUID(in: text) != nil { return true }
    let value = normalized(text)
    if firstCapture(in: value, pattern: #"(?i)\b(?:named|called)\s+([^.!?\n]+)"#) != nil { return true }
    let stripped = value
        .replacingOccurrences(of: #"(?i)\b(cancel|delete|remove|pause|resume|stop|snooze)\b"#, with: " ", options: .regularExpression)
        .replacingOccurrences(of: #"(?i)\b(the|an|a|my|alarm|timer|please)\b"#, with: " ", options: .regularExpression)
        .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
        .trimmingCharacters(in: .whitespacesAndNewlines)
    return stripped.split(separator: " ").contains { token in
        token.count >= 2 && token.rangeOfCharacter(from: .decimalDigits) == nil
    }
}

static func clarificationPrompt(for kind: AlarmCommandKind, text: String) -> String? {
    switch kind {
    case .authorizationStatus, .requestAuthorization, .list:
        return nil
    case .schedule:
        return hasTimeOrDate(text) ? nil : "What time should I use for the alarm?"
    case .countdown:

            return hasDuration(text) ? nil : "What duration should I use for the timer?"
        case .cancel, .pause, .resume, .stop, .snooze:
            return hasMutationTarget(text) ? nil : "Which alarm should I \(mutationVerb(for: kind))?"
        case .unknown:
            return "What time or duration should I use?"
        }
    }

    private static func mutationVerb(for kind: AlarmCommandKind) -> String {
        switch kind {
        case .cancel: return "cancel"
        case .pause: return "pause"
        case .resume: return "resume"
        case .stop: return "stop"
        case .snooze: return "snooze"
        default: return "update"
        }
    }

    private static func normalized(_ text: String) -> String {
        text.lowercased()
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines.union(.punctuationCharacters))
    }

    private static func containsAny(_ text: String, _ needles: [String]) -> Bool {
        needles.contains { text.contains($0) }
    }

    private static func firstCapture(in text: String, pattern: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
        let ns = text as NSString
        guard let match = regex.firstMatch(in: text, range: NSRange(location: 0, length: ns.length)),
              match.numberOfRanges > 1 else { return nil }
        return ns.substring(with: match.range(at: 1))
    }
}

import SwiftUI
import UIKit
import Combine

/// Observes the device battery level, charging state, and Low Power Mode.
///
/// Usage:
/// ```swift
/// @State private var battery = BatteryService.shared
/// // or in a View:
/// Text("\(Int(battery.level * 100))%")
/// ```
@MainActor
@Observable
final class BatteryService {
    static let shared = BatteryService()

    enum ChargingState: String, Sendable {
        case unknown
        case unplugged
        case charging
        case full
    }

    /// Battery level in 0...1. `-1` means the value is unavailable (e.g. simulator).
    private(set) var level: Float = -1
    private(set) var state: ChargingState = .unknown
    private(set) var isLowPowerModeEnabled: Bool = false

    private var observers: [NSObjectProtocol] = []
    private var isStarted = false

    private init() {}

    /// Initializes battery monitoring and registers observers for state changes.
    ///
    /// Enables battery level monitoring and immediately refreshes all observed properties with the current system state. Registers observers that update properties when battery level, charging state, or low power mode changes. Subsequent calls are ignored.
    func start() {
        guard !isStarted else { return }
        isStarted = true

        let device = UIDevice.current
        device.isBatteryMonitoringEnabled = true
        refresh()

        let center = NotificationCenter.default
        observers.append(center.addObserver(
            forName: UIDevice.batteryLevelDidChangeNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor [weak self] in self?.refresh() }
        })
        observers.append(center.addObserver(
            forName: UIDevice.batteryStateDidChangeNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor [weak self] in self?.refresh() }
        })
        observers.append(center.addObserver(
            forName: Notification.Name.NSProcessInfoPowerStateDidChange,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor [weak self] in self?.refresh() }
        })
    }

    func stop() {
        for token in observers {
            NotificationCenter.default.removeObserver(token)
        }
        observers.removeAll()

        UIDevice.current.isBatteryMonitoringEnabled = false
        isStarted = false
    }

    func refresh() {
        let device = UIDevice.current
        level = device.batteryLevel
        state = Self.mapState(device.batteryState)
        isLowPowerModeEnabled = ProcessInfo.processInfo.isLowPowerModeEnabled
    }

    /// Convenience: percentage 0...100, or `nil` if unavailable.
    var percentage: Int? {
        guard level >= 0 else { return nil }
        return Int((level * 100).rounded())
    }

    var isCharging: Bool {
        state == .charging || state == .full
    }

    private static func mapState(_ state: UIDevice.BatteryState) -> ChargingState {
        switch state {
        case .unknown: return .unknown
        case .unplugged: return .unplugged
        case .charging: return .charging
        case .full: return .full
        @unknown default: return .unknown
        }
    }

}

import Foundation
import AVFoundation
import UIKit

@MainActor
final class CameraCaptureController: NSObject {
    static let shared = CameraCaptureController()

    private var session: AVCaptureSession?
    private var photoOutput: AVCapturePhotoOutput?
    private var continuation: CheckedContinuation<String, Never>?

    func capture() async -> String {
        #if targetEnvironment(simulator)
        return "Camera unavailable in simulator."
        #else
        return await withCheckedContinuation { (cont: CheckedContinuation<String, Never>) in
            self.continuation = cont
            Task { [weak self] in
                await self?.performCapture()
            }
        }
        #endif
    }

    private func performCapture() async {
        let session = AVCaptureSession()
        session.sessionPreset = .photo

        guard let device = AVCaptureDevice.default(.builtInWideAngleCamera, for: .video, position: .back)
                ?? AVCaptureDevice.default(for: .video),
              let input = try? AVCaptureDeviceInput(device: device) else {
            finish("No camera input available.")
            return
        }

        session.beginConfiguration()
        if session.canAddInput(input) { session.addInput(input) }
        let output = AVCapturePhotoOutput()
        if session.canAddOutput(output) { session.addOutput(output) }
        session.commitConfiguration()

        self.session = session
        self.photoOutput = output

        session.startRunning()
        try? await Task.sleep(for: .milliseconds(600))

        let settings = AVCapturePhotoSettings()
        output.capturePhoto(with: settings, delegate: PhotoDelegate(owner: self))
    }

    fileprivate func didCapture(data: Data?, error: Error?) {
        session?.stopRunning()
        session = nil
        photoOutput = nil

        if let error {
            finish("Camera error: \(error.localizedDescription)")
            return
        }
        guard let data, let image = UIImage(data: data) else {
            finish("Couldn't read captured image.")
            return
        }
        let size = image.size
        let bytes = data.count
        let kb = Double(bytes) / 1024.0
        finish(String(format: "Captured image (%.0f×%.0f, %.0f KB).", size.width, size.height, kb))
    }

    private func finish(_ result: String) {

        MainActor.preconditionIsolated()
        continuation?.resume(returning: result)
        continuation = nil
    }
}

@MainActor
final class PhotoDelegate: NSObject, AVCapturePhotoCaptureDelegate {
    /// Concurrency contract: delegate callbacks may arrive on arbitrary queues; this type
    /// immediately hops to MainActor before mutating capture controller state.
    private let owner: CameraCaptureController
    init(owner: CameraCaptureController) { self.owner = owner }

    nonisolated func photoOutput(_ output: AVCapturePhotoOutput, didFinishProcessingPhoto photo: AVCapturePhoto, error: Error?) {
        let data = photo.fileDataRepresentation()
        Task { @MainActor [owner] in
            MainActor.preconditionIsolated()
            owner.didCapture(data: data, error: error)
        }
    }
}

import Foundation
import UIKit
import MessageUI

@MainActor
final class ComposeController: NSObject {
    static let shared = ComposeController()

    private var messageContinuation: CheckedContinuation<String, Never>?
    private var mailContinuation: CheckedContinuation<String, Never>?
    private var presentedController: UIViewController?

    func composeMessage(to recipients: [String], body: String) async -> String {
        if MFMessageComposeViewController.canSendText() {
            return await withCheckedContinuation { cont in
                self.messageContinuation = cont
                let vc = MFMessageComposeViewController()
                vc.messageComposeDelegate = self
                vc.recipients = recipients.filter { !$0.isEmpty }
                vc.body = body
                self.present(vc)
            }
        }
        return await fallbackSMS(recipients: recipients, body: body)
    }

    func composeMail(to recipients: [String], subject: String, body: String) async -> String {
        if MFMailComposeViewController.canSendMail() {
            return await withCheckedContinuation { cont in
                self.mailContinuation = cont
                let vc = MFMailComposeViewController()
                vc.mailComposeDelegate = self
                vc.setToRecipients(recipients.filter { !$0.isEmpty })
                vc.setSubject(subject)
                vc.setMessageBody(body, isHTML: false)
                self.present(vc)
            }
        }
        return await fallbackMailto(recipients: recipients, subject: subject, body: body)
    }

    private func present(_ vc: UIViewController) {
        guard let scene = UIApplication.shared.connectedScenes.first(where: { $0.activationState == .foregroundActive }) as? UIWindowScene,
              let root = scene.keyWindow?.rootViewController ?? scene.windows.first?.rootViewController else {
            finishMessage(with: "No window available to present composer.")
            finishMail(with: "No window available to present composer.")
            return
        }
        var top = root
        while let presented = top.presentedViewController { top = presented }
        self.presentedController = vc
        top.present(vc, animated: true)
    }

    private func dismiss() {
        presentedController?.dismiss(animated: true)
        presentedController = nil
    }

    fileprivate func finishMessage(with result: String) {
        let cont = messageContinuation
        messageContinuation = nil
        cont?.resume(returning: result)
    }

    fileprivate func finishMail(with result: String) {
        let cont = mailContinuation
        mailContinuation = nil
        cont?.resume(returning: result)
    }

    private func fallbackSMS(recipients: [String], body: String) async -> String {
        let to = recipients
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: ",")

        var components = URLComponents()
        components.scheme = "sms"
        components.path = to

        if !body.isEmpty {
            components.queryItems = [URLQueryItem(name: "body", value: body)]
        }

        guard let url = components.url ?? URL(string: "sms:\(to)") else {
            return "This device can't send messages."
        }
        let opened = await UIApplication.shared.open(url)
        return opened ? "Opened Messages with draft to \(to.isEmpty ? "recipient" : to)." : "Couldn't open Messages."
    }

    private func fallbackMailto(recipients: [String], subject: String, body: String) async -> String {
        let to = recipients.joined(separator: ",")
        var comps = URLComponents(string: "mailto:\(to)")
        var items: [URLQueryItem] = []
        if !subject.isEmpty { items.append(URLQueryItem(name: "subject", value: subject)) }
        if !body.isEmpty { items.append(URLQueryItem(name: "body", value: body)) }
        if !items.isEmpty { comps?.queryItems = items }
        guard let url = comps?.url else { return "Couldn't build mail URL." }
        let opened = await UIApplication.shared.open(url)
        return opened ? "Opened Mail with draft\(to.isEmpty ? "" : " to \(to)")." : "Couldn't open Mail — no accounts configured."
    }
}

extension ComposeController: MFMessageComposeViewControllerDelegate {
    nonisolated func messageComposeViewController(_ controller: MFMessageComposeViewController, didFinishWith result: MessageComposeResult) {
        let outcome: String
        switch result {
        case .sent: outcome = "Message sent."
        case .cancelled: outcome = "Message cancelled."
        case .failed: outcome = "Message failed to send."
        @unknown default: outcome = "Message composer closed."
        }

        Task { @MainActor in
            self.dismiss()
            self.finishMessage(with: outcome)
        }
    }
}

extension ComposeController: MFMailComposeViewControllerDelegate {
    nonisolated func mailComposeController(_ controller: MFMailComposeViewController, didFinishWith result: MFMailComposeResult, error: Error?) {
        let outcome: String
        switch result {
        case .sent: outcome = "Email sent."
        case .saved: outcome = "Email saved to Drafts."
        case .cancelled: outcome = "Email cancelled."
        case .failed: outcome = "Email failed: \(error?.localizedDescription ?? "unknown error")"
        @unknown default: outcome = "Mail composer closed."
        }
        Task { @MainActor in
            self.dismiss()
            self.finishMail(with: outcome)
        }
    }
}

