    if lowerFinal.contains("<think") || lowerFinal.contains("</think>")
        || lowerFinal.contains("<analysis") || lowerFinal.contains("</analysis>")
        || lowerFinal.contains("<reasoning") || lowerFinal.contains("</reasoning>")
