nonisolated struct FinalIntentValidationOutcome: Sendable, Equatable {
    let text: String
    let acceptedCandidate: Bool
    let replacementSource: String
    let rejectionReason: String?
}

nonisolated enum FinalIntentValidator {
    static func validate(_ text: String, routing: IntentRoutingDecision, fallback: String?) -> String {
        validateWithOutcome(text, routing: routing, fallback: fallback).text
    }

    static func validateWithOutcome(_ text: String, routing: IntentRoutingDecision, fallback: String?) -> FinalIntentValidationOutcome {
        let clean = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let lower = clean.lowercased()

        if isValid(clean, lower: lower, for: routing) || isSafeToolObservation(clean, lower: lower, for: routing) {
            return FinalIntentValidationOutcome(
                text: clean,
                acceptedCandidate: true,
                replacementSource: "candidate",
                rejectionReason: nil
            )
        }

        let rejectionReason = replacementReason(for: clean, lower: lower, routing: routing)
        if let fallback {
            let fallbackClean = fallback.trimmingCharacters(in: .whitespacesAndNewlines)
            let fallbackLower = fallbackClean.lowercased()
            if isValid(fallbackClean, lower: fallbackLower, for: routing) || isSafeToolObservation(fallbackClean, lower: fallbackLower, for: routing) {
                emitReplacementDiagnostic(intent: routing.intent, candidateLength: clean.count, replacementSource: "fallback", reason: rejectionReason)
                return FinalIntentValidationOutcome(
                    text: fallbackClean,
                    acceptedCandidate: false,
                    replacementSource: "fallback",
                    rejectionReason: rejectionReason
                )
            }
        }

        let safe = safeMessage(for: routing)
        emitReplacementDiagnostic(intent: routing.intent, candidateLength: clean.count, replacementSource: "safeMessage", reason: rejectionReason)
        return FinalIntentValidationOutcome(
            text: safe,
            acceptedCandidate: false,
            replacementSource: "safeMessage",
            rejectionReason: rejectionReason
        )
    }

    /// Determines whether the candidate text is valid for the given intent routing.
    ///

/// The text is considered valid if it is non-empty, passes all leak filters, and contains intent-specific keywords or patterns indicating compatibility with the routed intent.
///
/// - Parameters:
///   - text: The candidate text to validate.
///   - lower: The lowercased version of the candidate text.
///   - routing: The intent routing decision that determines which validation rules apply.
/// - Returns: `true` if the text meets all validation criteria for the intent, `false` otherwise.
private static func isValid(_ text: String, lower: String, for routing: IntentRoutingDecision) -> Bool {
    guard !text.isEmpty else { return false }
    guard passesLeakFilters(text: text, lower: lower, routing: routing) else { return false }

    if routing.requiresClarification,
       let clarification = routing.clarificationPrompt?.trimmingCharacters(in: .whitespacesAndNewlines),
       !clarification.isEmpty,
       text == clarification {
        return true
    }

    switch routing.intent {
    case .weather:
        return containsAny(lower, ["weather", "temperature", "humidity", "wind", "feels like", "°c", "rain", "snow", "cloud", "gps", "location access", "network", "timeout", "unreachable", "open-meteo", "service unavailable"])
    case .webSearch:
        return containsAny(lower, ["web", "search", "result", "http", "source", "found", "not available", "no direct answer", "try a different phrasing"])
    case .emailDraft:
        if lower.contains("i will be in touch soon") { return false }
        return !looksLikeCalendarLeak(lower, unless: false) && !looksLikeWeatherLeak(lower, unless: false)
    case .messageDraft:
        return !looksLikeCalendarLeak(lower, unless: false) && !looksLikeWeatherLeak(lower, unless: false) && !looksLikeWebSearchLeak(lower, unless: false)
    case .phoneCall:
        return containsAny(lower, ["call", "phone", "contact", "contact found", "contact search results", "requires", "unavailable", "couldn’t", "couldn't"])
    case .contactSearch:
        return containsAny(lower, ["contact", "contact found", "contact search results", "phone", "email", "found", "unavailable", "couldn’t", "couldn't"])
    case .calendar:

    return containsAny(lower, ["calendar", "event", "schedule", "meeting", "appointment", "requires explicit user approval", "did not create"])
case .reminder:
    return containsAny(lower, ["reminder", "todo", "to-do", "requires explicit user approval", "did not create"])
case .maps:
    return containsAny(lower, ["map", "maps", "direction", "route", "near", "nearby", "location", "current location", "coordinates", "latitude", "longitude", "place", "unavailable", "couldn’t", "couldn't"])
case .photos:
    return containsAny(lower, ["photo", "photos", "picture", "image", "library", "unavailable", "couldn’t", "couldn't"])
case .camera:
    return containsAny(lower, ["camera", "photo", "picture", "capture", "unavailable", "couldn’t", "couldn't"])
case .health:
    return containsAny(lower, ["health", "steps", "sleep", "heart", "energy", "walking", "unavailable", "couldn’t", "couldn't"])
case .motion:
    return containsAny(lower, ["motion", "activity", "walking", "running", "stationary", "unavailable", "couldn’t", "couldn't"])
case .files:
    return containsAny(lower, ["file", "document", "read", "local", "unavailable", "couldn’t", "couldn't"])
case .memory:
    return containsAny(lower, ["memory", "remember", "recall", "saved", "user's name", "no matching memories", "unavailable", "couldn’t", "couldn't"])
case .rag:
    let hasRagTopic = containsAny(lower, ["search", "index", "indexed", "files", "photos", "local"])
    let hasGrounding = containsAny(lower, ["[1]", "[2]", "snippet", "source", "retrieved", "file", "pdf", "note", "module", "modules"])
    let hasIndexCompletion = containsAny(lower, ["index updated", "indexed", "reindexed"])
    let explicitUnavailable = containsAny(lower, ["unavailable", "couldn’t", "couldn't", "no relevant", "no matching"]) 
    return (hasRagTopic && hasGrounding) || hasIndexCompletion || explicitUnavailable
case .trigger:
    return containsAny(lower, ["trigger", "scheduled", "agent", "background", "cancel", "unavailable", "couldn’t", "couldn't"])
case .alarm:
    return containsAny(lower, ["alarm", "timer", "countdown", "snooze", "pause", "resume", "stop", "authorization", "unavailable", "couldn’t", "couldn't"])

            "authentication expired", "authorization expired", "oauth expired", "oauth sign in",
            "not connected", "no messages", "outlook attachments:", "outlook folders:", "outlook search results:", "outlook status:"
        ])
    case .phoneCall, .contactSearch, .emailDraft, .messageDraft:
        return containsAny(lower, ["contact found:", "contact search results:"])
    default:
        return false
    }
}

private static func passesLeakFilters(text: String, lower: String, routing: IntentRoutingDecision) -> Bool {
    guard !AssistantOutputSanitizer.isLeakedToolJSONArtifact(text) else { return false }
    guard !looksLikeCredentialLeak(lower) else { return false }
    guard !looksLikeCalendarLeak(lower, unless: routing.intent == .calendar) else { return false }
    guard !looksLikeWeatherLeak(lower, unless: routing.intent == .weather) else { return false }
    guard !looksLikeEmailLeak(lower, unless: routing.intent == .emailDraft || routing.intent == .outlook) else { return false }
    guard !looksLikeWebSearchLeak(lower, unless: routing.intent == .webSearch) else { return false }
    return true
}

private static func replacementReason(for text: String, lower: String, routing: IntentRoutingDecision) -> String {
    if text.isEmpty { return "empty-candidate" }
    if AssistantOutputSanitizer.isLeakedToolJSONArtifact(text) { return "tool-json-leak" }
    if looksLikeCredentialLeak(lower) { return "credential-leak" }
    if looksLikeCalendarLeak(lower, unless: routing.intent == .calendar) { return "calendar-leak" }
    if looksLikeWeatherLeak(lower, unless: routing.intent == .weather) { return "weather-leak" }
    if looksLikeEmailLeak(lower, unless: routing.intent == .emailDraft || routing.intent == .outlook) { return "email-leak" }
    if looksLikeWebSearchLeak(lower, unless: routing.intent == .webSearch) { return "web-leak" }
    return "intent-validation-failed"
}

private static func emitReplacementDiagnostic(intent: UserIntent, candidateLength: Int, replacementSource: String, reason: String) {
    PersistentRuntimeDiagnosticsObserver.shared.emit(.init(kind: .finalIntentCandidateReplaced, values: [
        "intent": intent.rawValue,
        "candidateLength": String(candidateLength),

        "replacementSource": replacementSource,
        "reason": reason
    ]))
    RuntimeFallbackLogger.record(
        source: "final-intent-validator",
        primaryBehavior: "use model candidate as final user-visible response",
        fallbackBehavior: "replace candidate with validated fallback response",
        reason: reason,
        consequence: "primary model final text was not safe or intent-compatible",
        values: [
            "intent": intent.rawValue,
            "candidateLength": String(candidateLength),
            "replacementSource": replacementSource
        ]
    )
}

private static func looksLikeCredentialLeak(_ lower: String) -> Bool {
    let secretTerminator = #"(?![a-z0-9._~+/=-])"#
    if lower.range(
        of: ##"(?i)(?:^|[\s{"',])"?(?:access_token|refresh_token|id_token|client_secret|api_key)"?\s*[:=]\s*"?[a-z0-9._~+/=-]{8,}"?"## + secretTerminator,
        options: .regularExpression
    ) != nil {
        return true
    }
    if lower.range(
        of: #"(?i)\bauthorization\s*:\s*bearer\s+[a-z0-9._~+/=-]{16,}"# + secretTerminator,
        options: .regularExpression
    ) != nil {
        return true
    }
    if lower.range(
        of: #"(?i)\bbearer\s+[a-z0-9._~+/=-]{16,}"# + secretTerminator,
        options: .regularExpression
    ) != nil {
        return true
    }
    return lower.range(
        of: #"(?i)\beyj[a-z0-9_-]{8,}\.[a-z0-9_-]{10,}\.[a-z0-9_-]{10,}"# + secretTerminator,
        options: .regularExpression
    ) != nil
}

private static func looksLikeCalendarLeak(_ lower: String, unless allowed: Bool) -> Bool {
    !allowed && containsAny(lower, ["created a new event", "successfully created", "calendar event", "will start in", "starts in 5 minutes"])
}

private static func looksLikeWeatherLeak(_ lower: String, unless allowed: Bool) -> Bool {
    !allowed && containsAny(lower, ["weather for", "weather at", "temperature", "humidity", "feels like", "wind ", "clear sky"])
}

/// Identifies whether the text appears to contain an email draft.
/// - Parameters:
///   - lower: The lowercase text to examine.

    ///   - allowed: If `true`, bypasses the check and returns `false`; used when email content is expected for the current intent.
    /// - Returns: `true` if the text resembles an email draft and the check is enabled, `false` otherwise.
    private static func looksLikeEmailLeak(_ lower: String, unless allowed: Bool) -> Bool {
        !allowed && containsAny(lower, ["dear ", "subject:", "best regards", "sincerely", "i will be in touch soon"])
    }

    /// Determines whether text appears to contain web search results or URLs.
    /// - Parameters:
    ///   - lower: A lowercased string to check.
    ///   - allowed: When `true`, the function returns `false`.
    /// - Returns: `true` if the text contains web search leak patterns and is not explicitly allowed, `false` otherwise.
    private static func looksLikeWebSearchLeak(_ lower: String, unless allowed: Bool) -> Bool {
        !allowed && containsAny(lower, ["web search", "web result", "web results", "http://", "https://"])
    }

    /// Determines whether the string contains any of the provided substrings.
    /// - Parameters:
    ///   - value: The string to search within.
    ///   - needles: The substrings to search for.
    /// - Returns: `true` if the string contains any of the provided substrings, `false` otherwise.
    private static func containsAny(_ value: String, _ needles: [String]) -> Bool {
        needles.contains { value.contains($0) }
    }
}

import Foundation

nonisolated struct SanitizedFinalOutput: Sendable, Equatable {
    let text: String
    let removedArtifacts: [FinalOutputArtifact]
    let hadUnsafeLeakage: Bool
    let artifactAudit: FinalOutputArtifactAudit
}

nonisolated struct FinalOutputArtifactAudit: Sendable, Equatable {
    let rawPrefix: String
    let sanitizedPrefix: String
    let hadUnsafeLeakage: Bool
    let removedArtifacts: Bool
    let removedArtifactTypes: [FinalOutputArtifact]
}

nonisolated enum FinalOutputArtifact: String, Codable, Sendable, Equatable {
    case thinkBlock
    case malformedThinkPrefix
    case lumenWebPayload
    case rawToolPayload
    case injectedFallbackPrefix
    case emptyAfterSanitization
}

private final class FinalOutputSanitizerRecoveryCache: @unchecked Sendable {
    private let lock = NSLock()
    private var recoveredBySanitizedText: [String: SanitizedFinalOutput] = [:]

    func remember(_ output: SanitizedFinalOutput, forSanitizedText sanitizedText: String) {
        guard output.hadUnsafeLeakage else { return }
        lock.lock()
        recoveredBySanitizedText[sanitizedText] = output
        if recoveredBySanitizedText.count > 64 {
            recoveredBySanitizedText.remove(at: recoveredBySanitizedText.startIndex)
        }
        lock.unlock()
    }

    func consumeRecovery(forSanitizedText sanitizedText: String) -> SanitizedFinalOutput? {
        lock.lock()
        defer { lock.unlock() }
        return recoveredBySanitizedText.removeValue(forKey: sanitizedText)
    }
}

nonisolated struct StreamingFinalOutputSanitizer: Sendable {
    nonisolated enum Finalization: Sendable {
        case append(final: SanitizedFinalOutput, remainingDelta: String)
        case replace(final: SanitizedFinalOutput)
    }

    private var rawBuffer = ""
    private var emittedSanitized = ""
    private var sawSanitizerGeneratedFallbackDuringStream = false
    private let holdbackCharacters = 192

    mutating func ingest(_ chunk: String) -> String {
        guard !chunk.isEmpty else { return "" }
        rawBuffer += chunk

        let cutoff = safeRawCutoffIndex(in: rawBuffer)
        guard cutoff > 0 else { return "" }

        let safeRawPrefix = String(rawBuffer.prefix(cutoff))
        guard !safeRawPrefix.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return ""
        }

    let sanitized = FinalOutputSanitizer.sanitizeUserVisibleText(safeRawPrefix)

    // A partial stream can have an empty/unsafe safe prefix while the holdback window
    // waits for split markers such as <think> or <lumen_web_payload>. The global
    // fallback is valid only after finalization proves the complete output is
    // unusable; emitting it here leaks a fake error prefix into otherwise valid
    // answers. Track this provenance so finish() can clean a later fallback prefix
    // only when the stream itself proved sanitizer-generated fallback ancestry.
    if sanitized.text == FinalOutputSanitizer.fallback {
        let rawPrefixWasFallback = safeRawPrefix
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .hasPrefix(FinalOutputSanitizer.fallback.lowercased())
        if sanitized.hadUnsafeLeakage || !rawPrefixWasFallback {
            sawSanitizerGeneratedFallbackDuringStream = true
        }
        return ""
    }

    let sanitizedPrefix = sanitized.text
    guard sanitizedPrefix.count > emittedSanitized.count else { return "" }

    let delta = String(sanitizedPrefix.dropFirst(emittedSanitized.count))
    emittedSanitized = sanitizedPrefix
    return delta
}

mutating func finish() -> Finalization {
    let final = FinalOutputSanitizer.sanitizeUserVisibleText(
        rawBuffer,
        isInjectedProvenance: sawSanitizerGeneratedFallbackDuringStream
    )
    if final.text.hasPrefix(emittedSanitized) {
        let remainingDelta = String(final.text.dropFirst(emittedSanitized.count))
        emittedSanitized = final.text
        return .append(final: final, remainingDelta: remainingDelta)
    }
    emittedSanitized = final.text
    return .replace(final: final)
}

private func safeRawCutoffIndex(in raw: String) -> Int {
    let lower = raw.lowercased()
    let holdbackStart = max(0, raw.count - holdbackCharacters)
    var unsafeStart = raw.count

    if let hiddenOpen = firstUnclosedHiddenMarkerStart(in: lower) {
        unsafeStart = min(unsafeStart, hiddenOpen)
    }

    if let payloadOpen = lower.range(of: "<lumen_web_payload")?.lowerBound,

           lower.range(of: "</lumen_web_payload>", range: payloadOpen..<lower.endIndex) == nil {
            unsafeStart = min(unsafeStart, lower.distance(from: lower.startIndex, to: payloadOpen))
        }

        if let rawJSONStart = rawToolPayloadUnclosedObjectStart(lower: lower) {
            unsafeStart = min(unsafeStart, rawJSONStart)
        }

        return max(0, min(unsafeStart, holdbackStart))
    }

    private func rawToolPayloadUnclosedObjectStart(lower: String) -> Int? {
        let markers = ["\"kind\":\"searchresults\"", "\"kind\" : \"searchresults\"", "\"mediakind\":\"page\"", "\"mediakind\" : \"page\"", "\"sourcepageurl\""]
        guard let markerRange = markers.compactMap({ lower.range(of: $0) }).min(by: { $0.lowerBound < $1.lowerBound }) else { return nil }
        let markerIndex = lower.distance(from: lower.startIndex, to: markerRange.lowerBound)
        let prefix = lower.prefix(markerIndex)
        guard let bracePos = prefix.lastIndex(of: "{") else { return nil }
        let braceIndex = lower.distance(from: lower.startIndex, to: bracePos)
        let suffix = String(lower[lower.index(lower.startIndex, offsetBy: braceIndex)...])
        var depth = 0
        var inString = false
        var escaped = false
        for ch in suffix {
            if inString {
                if escaped { escaped = false; continue }
                if ch == "\\" { escaped = true; continue }
                if ch == "\"" { inString = false }
                continue
            }
            if ch == "\"" { inString = true; continue }
            if ch == "{" { depth += 1 }
            else if ch == "}" { depth -= 1; if depth == 0 { return nil } }
        }
        return braceIndex
    }

    private func firstUnclosedHiddenMarkerStart(in lower: String) -> Int? {
        let tagNames = ["think", "thinkresponse", "think_response", "thinking", "reasoning", "analysis", "chain_of_thought"]
        return tagNames.compactMap { tag -> Int? in
            guard let open = lower.range(of: "<\(tag)")?.lowerBound else { return nil }
            if lower.range(of: "</\(tag)>", range: open..<lower.endIndex) != nil { return nil }
            return lower.distance(from: lower.startIndex, to: open)
        }.min()
    }
}

nonisolated enum FinalOutputSanitizer {
    static let fallback = "I'm ready. Please ask again or tell me what you'd like to do next."

private static let recoveryCache = FinalOutputSanitizerRecoveryCache()
private static let rawToolPayloadPattern = #"(?is)\{[^{}]{0,24000}(?:"kind"\s*:\s*"searchresults"|"mediakind"\s*:\s*"page"|"sourcepageurl"|"kind":"searchresults")[^{}]{0,24000}\}"#
private static let cachedRawToolPayloadRegex: Result<NSRegularExpression, Error> = {
    do {
        return .success(try NSRegularExpression(pattern: rawToolPayloadPattern, options: []))
    } catch {
        return .failure(error)
    }
}()

static func sanitizeUserVisibleText(_ raw: String, isInjectedProvenance: Bool = false) -> SanitizedFinalOutput {
    var text = raw
    var removed: [FinalOutputArtifact] = []

    func mark(_ artifact: FinalOutputArtifact) {
        if !removed.contains(artifact) {
            removed.append(artifact)
        }
    }

    let originalLower = raw.lowercased()
    if containsHiddenReasoningMarker(originalLower) {
        mark(.thinkBlock)
    }
    if originalLower.contains("<lumen_web_payload") || originalLower.contains("</lumen_web_payload>") {
        mark(.lumenWebPayload)
    }
    if containsRawToolPayloadMarker(originalLower) {
        mark(.rawToolPayload)
    }

    let hiddenRemoval = removingHiddenReasoningBlocks(from: text)
    if hiddenRemoval.removedAny {
        text = hiddenRemoval.text
        mark(.thinkBlock)
    }
    let malformedHiddenRemoval = removingMalformedHiddenReasoningLines(from: text)
    if malformedHiddenRemoval.removedAny {
        text = malformedHiddenRemoval.text
        mark(.malformedThinkPrefix)
    }
    if beginsWithHiddenReasoningMarker(text) {
        text = ""
        mark(.malformedThinkPrefix)
    }
    text = text.replacingOccurrences(of: "(?is)<lumen_web_payload>.*?</lumen_web_payload>", with: " ", options: .regularExpression)
    text = text.replacingOccurrences(of: "(?is)<lumen_web_payload[^>]*>.*$", with: " ", options: .regularExpression)
    text = text.replacingOccurrences(of: "(?is)</lumen_web_payload>", with: " ", options: .regularExpression)

    let rawPayloadRemoval = removingRawToolPayloadObjects(from: text)
    if rawPayloadRemoval.removedAny {
        text = rawPayloadRemoval.text
        mark(.rawToolPayload)
    }

    let loosePayloadRemoval = removingRawToolPayloadFragments(from: text)
    if loosePayloadRemoval.removedAny {
        text = loosePayloadRemoval.text
        mark(.rawToolPayload)
    }

    let markerLineRemoval = removingRawToolPayloadMarkerLines(from: text)
    if markerLineRemoval.removedAny {
        text = markerLineRemoval.text
        mark(.rawToolPayload)
    }

    if containsRawToolPayloadMarker(text.lowercased()) {
        let trailingRemoval = removingTrailingRawToolPayload(from: text)
        if trailingRemoval.removedAny {
            text = trailingRemoval.text
            mark(.rawToolPayload)
        }
    }

    text = normalizeWhitespace(text)

    let fallbackRemoval = removingInjectedFallbackPrefix(
        from: text,
        allowSemanticRecovery: isInjectedProvenance
    )
    if fallbackRemoval.removedAny {
        text = fallbackRemoval.text
        mark(.injectedFallbackPrefix)
    }

    if text.isEmpty {
        mark(.emptyAfterSanitization)
        text = fallback
        RuntimeFallbackLogger.record(
            source: "final-output-sanitizer",
            primaryBehavior: "sanitize model output into non-empty user-visible response",
            fallbackBehavior: "emit sanitizer fallback response",
            reason: "empty-after-sanitization",
            consequence: "primary model text was fully removed by safety/output filters",
            values: [
                "rawChars": String(raw.count),
                "removedArtifacts": removed.map(\.rawValue).joined(separator: ",")
            ]
        )
    }

    let hadUnsafeLeakage = !removed.isEmpty
    let output = SanitizedFinalOutput(
        text: text,
        removedArtifacts: removed,
        hadUnsafeLeakage: hadUnsafeLeakage,
        artifactAudit: FinalOutputArtifactAudit(
            rawPrefix: String(raw.prefix(220)),
            sanitizedPrefix: String(text.prefix(220)),
            hadUnsafeLeakage: hadUnsafeLeakage,
            removedArtifacts: !removed.isEmpty,
            removedArtifactTypes: removed
        )
    )
    recoveryCache.remember(output, forSanitizedText: text)
    return output
}

static func consumeRecoveredUnsafeOutput(forSanitizedText text: String) -> SanitizedFinalOutput? {
    if let direct = recoveryCache.consumeRecovery(forSanitizedText: text) {
        return direct
    }

    let sanitizedKey = sanitizedRecoveryKey(for: text)
    guard sanitizedKey != text else { return nil }
    return recoveryCache.consumeRecovery(forSanitizedText: sanitizedKey)
}

private static func sanitizedRecoveryKey(for raw: String) -> String {
    var text = raw
    text = removingHiddenReasoningBlocks(from: text).text
    text = removingMalformedHiddenReasoningLines(from: text).text
    if beginsWithHiddenReasoningMarker(text) {
        text = ""
    }
    text = text.replacingOccurrences(of: "(?is)<lumen_web_payload>.*?</lumen_web_payload>", with: " ", options: .regularExpression)
    text = text.replacingOccurrences(of: "(?is)<lumen_web_payload[^>]*>.*$", with: " ", options: .regularExpression)
    text = text.replacingOccurrences(of: "(?is)</lumen_web_payload>", with: " ", options: .regularExpression)
    text = removingRawToolPayloadObjects(from: text).text
    text = normalizeWhitespace(text)
    return text.isEmpty ? fallback : text
}

private static let hiddenReasoningTagPattern = "(?:think[\\w_-]*|thinking|reasoning|analysis|chain_of_thought)"

private static func containsHiddenReasoningMarker(_ lowercasedText: String) -> Bool {
    ["<think", "</think", "<thinking", "</thinking", "<reasoning", "</reasoning", "<analysis", "</analysis", "<chain_of_thought", "</chain_of_thought"].contains {
        lowercasedText.contains($0)
    }
}

private static func beginsWithHiddenReasoningMarker(_ text: String) -> Bool {
    text.trimmingCharacters(in: .whitespacesAndNewlines).range(
        of: "^<\\s*\(hiddenReasoningTagPattern)\\b",
        options: [.regularExpression, .caseInsensitive]
    ) != nil
}

private static func removingHiddenReasoningBlocks(from source: String) -> (text: String, removedAny: Bool) {
    let pattern = "(?is)<\\s*(\(hiddenReasoningTagPattern))\\b[^>]*>.*?</\\s*\\1\\s*>"
    let redacted = source.replacingOccurrences(of: pattern, with: " ", options: .regularExpression)
    return (redacted, redacted != source)
}

private static func removingMalformedHiddenReasoningLines(from source: String) -> (text: String, removedAny: Bool) {
    let pattern = "(?im)^\\s*<\\s*\(hiddenReasoningTagPattern)\\b[^\\n]*(?:\\n|$)"
    let redacted = source.replacingOccurrences(of: pattern, with: " ", options: .regularExpression)
    return (redacted, redacted != source)
}

private static func normalizeWhitespace(_ text: String) -> String {
    text
        .replacingOccurrences(of: "[ \\t]+", with: " ", options: .regularExpression)
        .replacingOccurrences(of: " *\\n *", with: "\n", options: .regularExpression)
        .replacingOccurrences(of: "\\n{3,}", with: "\n\n", options: .regularExpression)
        .trimmingCharacters(in: .whitespacesAndNewlines)
}

private static func removingInjectedFallbackPrefix(
    from source: String,
    allowSemanticRecovery: Bool
) -> (text: String, removedAny: Bool) {
    let trimmed = source.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.count > fallback.count else { return (source, false) }
    guard trimmed.lowercased().hasPrefix(fallback.lowercased()) else { return (source, false) }
    let separators = CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: ".:;-—–*"))
    let remainderStart = trimmed[trimmed.index(trimmed.startIndex, offsetBy: fallback.count)...]
        .drop(while: { character in
            character.unicodeScalars.allSatisfy { separators.contains($0) }
        })
    let remainder = String(remainderStart)
    guard !remainder.isEmpty else { return (source, false) }
    guard allowSemanticRecovery || looksLikeRecoverableAnswerSuffix(remainder) else {
        return (source, false)
    }
    return (remainder, true)
}

private static func looksLikeRecoverableAnswerSuffix(_ source: String) -> Bool {
    let text = source.trimmingCharacters(in: .whitespacesAndNewlines)
    let lower = text.lowercased()
    guard text.count >= 12 else { return false }
    if lower.hasPrefix("i remember that ") { return true }
    if lower.hasPrefix("weather update:") || lower.hasPrefix("the weather ") { return true }
    if lower.hasPrefix("summary:") || lower.hasPrefix("summary\n") { return true }
    if lower.hasPrefix("web results found:") { return true }

    if lower.hasPrefix("i searched your local files") { return true }
    if lower.hasPrefix("i found ") && lower.contains(" from ") { return true }
    return false
}

private static func containsRawToolPayloadMarker(_ lowercasedText: String) -> Bool {
    lowercasedText.contains("{\"kind\":\"searchresults\"")
        || lowercasedText.contains("\"kind\" : \"searchresults\"")
        || lowercasedText.contains("\"mediakind\":\"page\"")
        || lowercasedText.contains("\"mediakind\" : \"page\"")
        || lowercasedText.contains("\"sourcepageurl\"")
}

private static func removingRawToolPayloadFragments(from source: String) -> (text: String, removedAny: Bool) {
    guard case let .success(regex) = cachedRawToolPayloadRegex else {
        return (source, false)
    }

    let range = NSRange(source.startIndex..<source.endIndex, in: source)
    if regex.firstMatch(in: source, options: [], range: range) == nil {
        return (source, false)
    }
    let redacted = regex.stringByReplacingMatches(in: source, options: [], range: range, withTemplate: " ")
    return (redacted, redacted != source)
}

private static func removingRawToolPayloadMarkerLines(from source: String) -> (text: String, removedAny: Bool) {
    let pattern = #"(?im)^.*("kind"\s*:\s*"searchresults"|"mediakind"\s*:\s*"page"|"sourcepageurl").*(?:\n|$)"#
    guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else {
        return (source, false)
    }
    let range = NSRange(source.startIndex..<source.endIndex, in: source)
    if regex.firstMatch(in: source, options: [], range: range) == nil {
        return (source, false)
    }
    let redacted = regex.stringByReplacingMatches(in: source, options: [], range: range, withTemplate: " ")
    return (redacted, redacted != source)
}

private static func removingTrailingRawToolPayload(from source: String) -> (text: String, removedAny: Bool) {
    let lower = source.lowercased()
    let markers = ["\"kind\":\"searchresults\"", "\"kind\" : \"searchresults\"", "\"mediakind\":\"page\"", "\"mediakind\" : \"page\"", "\"sourcepageurl\""]
    guard let markerIndex = markers.compactMap({ lower.range(of: $0)?.lowerBound }).min() else {
        return (source, false)
    }

        let lineStart = source[..<markerIndex].lastIndex(of: "\n").map { source.index(after: $0) } ?? source.startIndex
        let redacted = String(source[..<lineStart]) + " "
        return (redacted, true)
    }

    private static func removingRawToolPayloadObjects(from source: String) -> (text: String, removedAny: Bool) {
        var output = ""
        var index = source.startIndex
        var removedAny = false

        while index < source.endIndex {
            guard source[index] == "{" else {
                output.append(source[index])
                index = source.index(after: index)
                continue
            }

            guard let objectEnd = balancedJSONObjectEnd(in: source, from: index) else {
                output.append(source[index])
                index = source.index(after: index)
                continue
            }

            let nextIndex = source.index(after: objectEnd)
            let candidate = String(source[index..<nextIndex])
            if containsRawToolPayloadMarker(candidate.lowercased()) {
                output.append(" ")
                removedAny = true
            } else {
                output.append(candidate)
            }
            index = nextIndex
        }

        return (output, removedAny)
    }

    private static func balancedJSONObjectEnd(in source: String, from start: String.Index) -> String.Index? {
        var index = start
        var depth = 0
        var isInsideString = false
        var isEscaped = false

        while index < source.endIndex {
            let character = source[index]

            if isInsideString {
                if isEscaped {
                    isEscaped = false
                } else if character == "\\" {
                    isEscaped = true
                } else if character == "\"" {
                    isInsideString = false
                }
            } else {
                if character == "\"" {
                    isInsideString = true
                } else if character == "{" {
                    depth += 1
                } else if character == "}" {
                    depth -= 1
                    if depth == 0 {
                        return index
                    }
                }
            }

            index = source.index(after: index)
        }

        return nil
    }
}

