struct FleetRuntimeCleanupResult: Sendable, Equatable {
    let unloadedSlots: [LumenModelSlot]

    var unloadedSlotSummary: String {
        guard !unloadedSlots.isEmpty else { return "none" }
        return unloadedSlots.map(\.rawValue).sorted().joined(separator: ",")
    }
}

@MainActor
enum FleetRuntimeCleanup {
    private static let optionalChatSlots: [LumenModelSlot] = [.rem, .mimicry]
    private static let nonCoreChatSlots: [LumenModelSlot] = [.rem, .mimicry, .executor, .mouth]

    @discardableResult
    static func unloadOptionalChatSlotsNow() async -> FleetRuntimeCleanupResult {
        await unloadChatSlots(optionalChatSlots)
    }

    static func unloadOptionalChatSlots() {
        Task {
            _ = await unloadOptionalChatSlotsNow()
        }
    }

    @discardableResult
    static func unloadNonCoreChatSlotsNow() async -> FleetRuntimeCleanupResult {
        await unloadChatSlots(nonCoreChatSlots)
    }

    static func unloadNonCoreChatSlots() {
        Task {
            _ = await unloadNonCoreChatSlotsNow()
        }
    }

    private static func unloadChatSlots(_ slots: [LumenModelSlot]) async -> FleetRuntimeCleanupResult {
        let loaded = await AppLlamaService.shared.loadedChatPathsBySlot
        var unloadedSlots: [LumenModelSlot] = []
        for slot in slots where loaded[slot] != nil {
            await AppLlamaService.shared.unloadChat(for: slot)
            unloadedSlots.append(slot)
        }
        return FleetRuntimeCleanupResult(unloadedSlots: unloadedSlots)
    }
}

import Foundation

@MainActor
final class GenerationTaskController<Key: Hashable> {
    private var tasks: [Key: Task<Void, Never>] = [:]
    private var activeRequestIDs: [Key: UUID] = [:]
    private var startedKeys: Set<Key> = []

    func startupIfNeeded(for key: Key, _ action: @escaping () -> Void) {
        guard !startedKeys.contains(key) else { return }
        startedKeys.insert(key)
        action()
    }

    func begin(for key: Key, task: Task<Void, Never>, requestID: UUID = UUID()) -> UUID {
        tasks[key]?.cancel()
        activeRequestIDs[key] = requestID
        tasks[key] = task
        assertSingleActiveGeneration(for: key)
        return requestID
    }

    func cancel(for key: Key) {
        tasks[key]?.cancel()
        tasks[key] = nil
        activeRequestIDs[key] = nil
    }

    func isCurrent(_ requestID: UUID, for key: Key) -> Bool {
        activeRequestIDs[key] == requestID
    }

    func clearIfCurrent(_ requestID: UUID, for key: Key) {
        guard activeRequestIDs[key] == requestID else { return }
        tasks[key] = nil
        activeRequestIDs[key] = nil
    }

    func hasActiveGeneration(for key: Key) -> Bool {
        tasks[key] != nil && activeRequestIDs[key] != nil
    }

    /// Audit assertion: every conversation key must map to at most one active
    /// generation task and request ID at any time.
    func assertSingleActiveGeneration(for key: Key) {
        let taskExists = tasks[key] != nil
        let requestExists = activeRequestIDs[key] != nil
        assert(taskExists == requestExists, "GenerationTaskController invariant violation: task/request mismatch for key \(String(describing: key)).")
    }
}

import CoreML
import Foundation
import NaturalLanguage
import OSLog

actor BundledIntentClassifier {
    static let shared = BundledIntentClassifier()

    private nonisolated static let logger = Logger(subsystem: "ai.lumen.app", category: "intent-classifier")

    private var cachedNLModel: NLModel?
    private var cachedCoreMLModel: MLModel?
    private var attemptedSourceModelCompilation = false
    private var predictionMainThreadViolationCount = 0

    private init() {}

    func classify(_ text: String) async -> IntentClassificationResult? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        if let nlModel = loadNLModel(),
           let label = predictedLabel(model: nlModel, text: trimmed),
           let intent = normalizeIntentLabel(label) {
            let probs = predictedLabelHypotheses(model: nlModel, text: trimmed, maximumCount: 5)
            let alternatives = probs.compactMap { pair -> IntentAlternative? in
                guard let intent = normalizeIntentLabel(pair.key) else { return nil }
                return IntentAlternative(intent: intent, confidence: pair.value)
            }
            .sorted { $0.confidence > $1.confidence }
            return IntentClassificationResult(intent: intent, confidence: probs[label] ?? 0.0, alternatives: alternatives, requiresClarification: false, clarificationPrompt: nil, source: .bundledModel, diagnostics: "nlmodel")
        }

        if let model = loadCoreMLModel(), let inferred = inferWithCoreML(model: model, text: trimmed) {
            return inferred
        }

        return nil
    }

    func resetPredictionMainThreadViolationCountForTesting() {
        predictionMainThreadViolationCount = 0
    }

    func predictionMainThreadViolationCountForTesting() -> Int {
        predictionMainThreadViolationCount
    }

    private func loadNLModel() -> NLModel? {
        if let cachedNLModel { return cachedNLModel }
        guard let url = Bundle.main.url(forResource: "IntentClassifier", withExtension: "nlmodel") else { return nil }
        let model = try? NLModel(contentsOf: url)
        cachedNLModel = model
        return model
    }

    private func loadCoreMLModel() -> MLModel? {
        if let cachedCoreMLModel { return cachedCoreMLModel }

    if let compiledURL = Bundle.main.url(forResource: "IntentClassifier", withExtension: "mlmodelc") {
        let model = try? MLModel(contentsOf: compiledURL)
        cachedCoreMLModel = model
        return model
    }

    guard !attemptedSourceModelCompilation else {
        Self.logger.debug("Skipping source IntentClassifier.mlmodel compilation because a previous actor-serialized attempt already ran.")
        return nil
    }
    attemptedSourceModelCompilation = true

    guard let sourceURL = Bundle.main.url(forResource: "IntentClassifier", withExtension: "mlmodel") else {
        Self.logger.debug("Skipping source IntentClassifier.mlmodel compilation because only compiled IntentClassifier.mlmodelc is expected in production.")
        return nil
    }

    Self.logger.warning("Compiled IntentClassifier.mlmodelc was not bundled; compiling source IntentClassifier.mlmodel once inside the classifier actor.")
    guard let compiled = try? MLModel.compileModel(at: sourceURL) else { return nil }
    let model = try? MLModel(contentsOf: compiled)
    cachedCoreMLModel = model
    return model
}

private func inferWithCoreML(model: MLModel, text: String) -> IntentClassificationResult? {
    guard let inputName = model.modelDescription.inputDescriptionsByName.keys.first else { return nil }
    let provider = try? MLDictionaryFeatureProvider(dictionary: [inputName: text])
    guard let provider else { return nil }
    noteIfPredictionIsOnMainThread()
    guard let output = try? model.prediction(from: provider) else { return nil }

    let label = (output.featureValue(for: "classLabel")?.stringValue) ?? (output.featureValue(for: "label")?.stringValue)
    guard let label, let intent = normalizeIntentLabel(label) else { return nil }

    let candidates = ["classProbability", "labelProbabilities", "probabilities"]
    var probs: [String: Double] = [:]
    for key in candidates {
        if let dict = stringDoubleDictionary(from: output.featureValue(for: key)?.dictionaryValue) {
            probs = dict
            break
        }
    }
    let alternatives = probs.compactMap { pair -> IntentAlternative? in
        guard let intent = normalizeIntentLabel(pair.key) else { return nil }

            return IntentAlternative(intent: intent, confidence: pair.value)
        }
        .sorted { $0.confidence > $1.confidence }
        let confidence = probs[label] ?? alternatives.first(where: { $0.intent == intent })?.confidence ?? 0.0
        return IntentClassificationResult(intent: intent, confidence: confidence, alternatives: alternatives, requiresClarification: false, clarificationPrompt: nil, source: .bundledModel, diagnostics: "coreml")
    }

    private func predictedLabel(model: NLModel, text: String) -> String? {
        noteIfPredictionIsOnMainThread()
        return model.predictedLabel(for: text)
    }

    private func predictedLabelHypotheses(model: NLModel, text: String, maximumCount: Int) -> [String: Double] {
        noteIfPredictionIsOnMainThread()
        return model.predictedLabelHypotheses(for: text, maximumCount: maximumCount)
    }

    private func noteIfPredictionIsOnMainThread() {
        if Thread.isMainThread {
            predictionMainThreadViolationCount += 1
            Self.logger.fault("Bundled intent model prediction executed on the main thread.")
        }
    }

    private func normalizeIntentLabel(_ raw: String) -> UserIntent? {
        let canonical = raw
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: "_", with: "")
            .lowercased()
        if let exact = UserIntent(rawValue: raw) { return exact }
        return UserIntent.allCases.first { $0.rawValue.lowercased() == canonical }
    }

    private func stringDoubleDictionary(from raw: [AnyHashable: Any]?) -> [String: Double]? {
        guard let raw else { return nil }
        var out: [String: Double] = [:]
        out.reserveCapacity(raw.count)
        for (key, value) in raw {
            guard let stringKey = key as? String else { continue }
            if let number = value as? NSNumber {
                out[stringKey] = number.doubleValue
            } else if let doubleValue = value as? Double {
                out[stringKey] = doubleValue
            } else if let floatValue = value as? Float {
                out[stringKey] = Double(floatValue)
            } else if let intValue = value as? Int {
                out[stringKey] = Double(intValue)
            }
        }
        return out.isEmpty ? nil : out
    }
}

import Foundation

nonisolated enum DeterministicIntentFallback {
    static func classify(_ text: String) -> IntentClassificationResult {
        if let clarification = ambiguityClarification(text) {
            return clarification
        }

        let decision = IntentRouter.classify(text)
        let confidence: Double
        switch decision.intent {
        case .chat: confidence = 0.75
        case .unknown: confidence = 0.50
        default: confidence = decision.allowedToolIDs.isEmpty ? 0.50 : 0.90
        }
        return IntentClassificationResult(
            intent: decision.intent,
            confidence: confidence,
            alternatives: [IntentAlternative(intent: decision.intent, confidence: confidence)],
            requiresClarification: decision.requiresClarification,
            clarificationPrompt: decision.clarificationPrompt,
            source: .deterministicFallback,
            diagnostics: "deterministic"
        )
    }

    static func ambiguityClarification(_ text: String) -> IntentClassificationResult? {
        let value = normalized(text)
        guard !value.isEmpty else { return nil }

        if isAmbiguousMeetingLookup(value) {
            return clarification(
                prompt: "Do you mean a calendar event or a nearby meeting location?",
                alternatives: [.calendar, .maps]
            )
        }

        if isAmbiguousReferenceAction(value) {
            return clarification(
                prompt: "What would you like me to act on?",
                alternatives: [.unknown]
            )
        }

        return nil
    }

    private static func clarification(prompt: String, alternatives: [UserIntent]) -> IntentClassificationResult {
        let primary = alternatives.first ?? .unknown
        return IntentClassificationResult(
            intent: primary,
            confidence: 0.45,
            alternatives: alternatives.map { IntentAlternative(intent: $0, confidence: $0 == primary ? 0.45 : 0.40) },
            requiresClarification: true,
            clarificationPrompt: prompt,
            source: .deterministicFallback,
            diagnostics: "deterministic_ambiguity_clarification"
        )
    }

    private static func isAmbiguousMeetingLookup(_ text: String) -> Bool {

        let hasLookupVerb = containsAny(text, ["find", "show", "search", "check", "open", "where is", "where are"])
        let hasPersonalMeeting = containsAny(text, ["my meeting", "my appointment", "my event"])
        let lacksCalendarScope = !containsAny(text, ["calendar", "schedule", "event details"])
        let lacksLocalScope = !containsAny(text, ["near me", "nearby", "closest", "nearest", "directions", "address"])
        return hasLookupVerb && hasPersonalMeeting && lacksCalendarScope && lacksLocalScope
    }

    private static func isAmbiguousReferenceAction(_ text: String) -> Bool {
        let exact = [
            "book that", "book it", "schedule that", "schedule it",
            "cancel that", "cancel it", "send it", "send that",
            "do it", "do that", "that one", "this one"
        ]
        if exact.contains(text) { return true }

        let referenceTargets = [" it", " that", " this", " them"]
        let actionVerbs = ["book", "schedule", "cancel", "send", "move", "delete", "open", "call"]
        return actionVerbs.contains { verb in text.hasPrefix("\(verb) ") }
            && referenceTargets.contains { target in text.contains(target) }
            && !text.contains("http")
    }

    private static func normalized(_ text: String) -> String {
        text.lowercased()
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func containsAny(_ value: String, _ needles: [String]) -> Bool {
        needles.contains { value.contains($0) }
    }
}

import Foundation

nonisolated struct IntentAlternative: Sendable, Codable, Hashable {
    let intent: UserIntent
    let confidence: Double
}

nonisolated struct IntentClassificationResult: Sendable, Codable {
    enum Source: String, Sendable, Codable {
        case bundledModel
        case deterministicFallback
        case policyMerged
        case unavailable
    }

    let intent: UserIntent
    let confidence: Double
    let alternatives: [IntentAlternative]
    let requiresClarification: Bool
    let clarificationPrompt: String?
    let source: Source
    let diagnostics: String?

    func withAllowedAlternatives(maxCount: Int = 5) -> IntentClassificationResult {
        let normalized = alternatives
            .filter { $0.confidence.isFinite && $0.confidence >= 0 }
            .sorted { $0.confidence > $1.confidence }
        let deduped = normalized.reduce(into: [IntentAlternative]()) { acc, item in
            if !acc.contains(where: { $0.intent == item.intent }) {
                acc.append(item)
            }
        }
        return IntentClassificationResult(
            intent: intent,
            confidence: confidence,
            alternatives: Array(deduped.prefix(maxCount)),
            requiresClarification: requiresClarification,
            clarificationPrompt: clarificationPrompt,
            source: source,
            diagnostics: diagnostics
        )
    }

    func asRoutingDecision() -> IntentRoutingDecision {
        IntentRoutingDecision(
            intent: intent,
            allowedToolIDs: IntentToolMapping.allowedToolIDs(for: intent),
            requiresClarification: requiresClarification,
            clarificationPrompt: clarificationPrompt
        )
    }
}

nonisolated enum IntentToolMapping {
    private static let mapping: [UserIntent: Set<String>] = Dictionary(uniqueKeysWithValues: UserIntent.allCases.map { ($0, IntentRouter.allowedToolIDs(for: $0)) })

    static func allowedToolIDs(for intent: UserIntent) -> Set<String> {
        mapping[intent] ?? []
    }
}

import Foundation

nonisolated enum IntentClassifierPolicy {
    static func resolve(modelResult: IntentClassificationResult?, deterministic fallback: IntentClassificationResult) -> IntentClassificationResult {
        guard let modelResult else { return sanitized(fallback, source: .deterministicFallback) }
        if modelResult.requiresClarification {
            return sanitized(modelResult, source: .bundledModel)
        }
        if modelResult.intent != fallback.intent,
           isApprovalSensitive(fallback.intent),
           fallback.confidence >= 0.85 {
            return sanitized(fallback, source: .policyMerged)
        }
        if let clarification = clarificationForAmbiguousModelResult(modelResult, fallback: fallback) {
            return sanitized(clarification, source: .policyMerged)
        }
        if modelResult.confidence >= 0.72 {
            return sanitized(modelResult, source: .bundledModel)
        }
        if modelResult.confidence >= 0.50 {
            return resolveMediumConfidence(modelResult: modelResult, fallback: fallback)
        }
        return sanitized(fallback, source: .deterministicFallback)
    }

    private static func resolveMediumConfidence(modelResult: IntentClassificationResult, fallback: IntentClassificationResult) -> IntentClassificationResult {
        if modelResult.intent == fallback.intent {
            return sanitized(IntentClassificationResult(intent: modelResult.intent, confidence: min(0.99, modelResult.confidence + 0.05), alternatives: modelResult.alternatives, requiresClarification: modelResult.requiresClarification || fallback.requiresClarification, clarificationPrompt: modelResult.clarificationPrompt ?? fallback.clarificationPrompt, source: .policyMerged, diagnostics: "merged:agree"), source: .policyMerged)
        }
        if isApprovalSensitive(fallback.intent) {
            return sanitized(fallback, source: .policyMerged)
        }
        if isSemanticNonDestructive(modelResult.intent), modelResult.confidence >= 0.65 {
            return sanitized(IntentClassificationResult(intent: modelResult.intent, confidence: modelResult.confidence, alternatives: modelResult.alternatives, requiresClarification: modelResult.requiresClarification, clarificationPrompt: modelResult.clarificationPrompt, source: .policyMerged, diagnostics: "merged:model_preferred"), source: .policyMerged)
        }

    return sanitized(fallback, source: .policyMerged)
}

private static func clarificationForAmbiguousModelResult(_ modelResult: IntentClassificationResult, fallback: IntentClassificationResult) -> IntentClassificationResult? {
    let ranked = rankedAlternatives(for: modelResult, fallback: fallback)
    guard ranked.count >= 2 else { return nil }
    let first = ranked[0]
    let second = ranked[1]
    let gap = first.confidence - second.confidence
    let closeEnough = modelResult.confidence >= 0.50 && gap <= 0.12
    let highConfidenceButClose = modelResult.confidence >= 0.72 && gap <= 0.08
    guard closeEnough || highConfidenceButClose else { return nil }
    guard first.intent != second.intent else { return nil }
    guard shouldClarifyBetween(first.intent, second.intent) else { return nil }

    return IntentClassificationResult(
        intent: first.intent,
        confidence: first.confidence,
        alternatives: ranked,
        requiresClarification: true,
        clarificationPrompt: clarificationPrompt(primary: first.intent, secondary: second.intent),
        source: .policyMerged,
        diagnostics: "merged:ambiguous_intent"
    )
}

private static func rankedAlternatives(for modelResult: IntentClassificationResult, fallback: IntentClassificationResult) -> [IntentAlternative] {
    let primary = IntentAlternative(intent: modelResult.intent, confidence: min(max(modelResult.confidence, 0.0), 1.0))
    let fallbackAlternative = IntentAlternative(intent: fallback.intent, confidence: min(max(fallback.confidence, 0.0), 1.0))
    return (modelResult.alternatives + [primary, fallbackAlternative])
        .filter { $0.confidence.isFinite && $0.confidence >= 0 }
        .sorted { $0.confidence > $1.confidence }
        .reduce(into: [IntentAlternative]()) { acc, item in
            if !acc.contains(where: { $0.intent == item.intent }) {
                acc.append(item)
            }
        }
}

private static func shouldClarifyBetween(_ first: UserIntent, _ second: UserIntent) -> Bool {
    if first == .chat || first == .unknown || second == .chat || second == .unknown {
        return false
    }

    return IntentToolMapping.allowedToolIDs(for: first) != IntentToolMapping.allowedToolIDs(for: second)
}

private static func clarificationPrompt(primary: UserIntent, secondary: UserIntent) -> String {
    "Do you mean \(clarificationLabel(for: primary)) or \(clarificationLabel(for: secondary))?"
}

private static func clarificationLabel(for intent: UserIntent) -> String {
    switch intent {
    case .weather: return "weather information"
    case .webSearch: return "a web search"
    case .emailDraft: return "an email draft"
    case .messageDraft: return "a message draft"
    case .phoneCall: return "a phone call"
    case .contactSearch: return "a contact lookup"
    case .calendar: return "a calendar event"
    case .reminder: return "a reminder"
    case .maps: return "a nearby place or directions"
    case .photos: return "photo-library search"
    case .camera: return "camera capture"
    case .health: return "health data"
