    }
}

import Foundation

struct RemoteModelAccessPolicy: Sendable, Codable, Equatable {
    let allowsRemoteModels: Bool
    let allowsBackgroundRemoteModels: Bool

    static let localOnly = RemoteModelAccessPolicy(
        allowsRemoteModels: false,
        allowsBackgroundRemoteModels: false
    )

    static let userApprovedForeground = RemoteModelAccessPolicy(
        allowsRemoteModels: true,
        allowsBackgroundRemoteModels: false
    )

    init(
        allowsRemoteModels: Bool,
        allowsBackgroundRemoteModels: Bool = false
    ) {
        self.allowsRemoteModels = allowsRemoteModels
        self.allowsBackgroundRemoteModels = allowsBackgroundRemoteModels
    }
}

actor DeviceModelPolicy {
    private let provider: any DeviceCapabilityProviding
    private let remoteModelAccessPolicy: RemoteModelAccessPolicy
    private let allowMockModels: Bool

    init(
        provider: any DeviceCapabilityProviding = SystemDeviceCapabilityProvider(),
        remoteModelAccessPolicy: RemoteModelAccessPolicy = .localOnly,
        allowMockModels: Bool = false
    ) {
        self.provider = provider
        self.remoteModelAccessPolicy = remoteModelAccessPolicy
        self.allowMockModels = allowMockModels
    }

    func evaluate(
        model: LocalLLMModel,
        requestedProfile: InferenceProfile,
        requestedBudget: InferenceBudget,
        appIsForeground: Bool
    ) async -> ModelFitDecision {
        let snapshot = await provider.currentSnapshot(appIsForeground: appIsForeground)
        var selectedProfile = requestedProfile
        var selectedBudget = requestedBudget
        var reasons: [ModelFitReason] = []

        switch model.backend {
        case .tinyIntent:
            add(.tinyIntentAlwaysAllowed, to: &reasons)
            let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
            return .allowed(report(
                model: model,
                snapshot: snapshot,
                requestedProfile: requestedProfile,
                selectedProfile: selectedProfile,
                requestedBudget: requestedBudget,
                selectedBudget: selectedBudget,
                memoryEstimate: estimate,
                reasons: reasons
            ))
        case .mock:
            guard allowMockModels else {
                add(.mockBackendNotAllowed, to: &reasons)

        let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
        return .rejected(report(
            model: model,
            snapshot: snapshot,
            requestedProfile: requestedProfile,
            selectedProfile: selectedProfile,
            requestedBudget: requestedBudget,
            selectedBudget: selectedBudget,
            memoryEstimate: estimate,
            reasons: reasons
        ))
    }
    add(.modelFitsMemoryBudget, to: &reasons)
    let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
    return .allowed(report(
        model: model,
        snapshot: snapshot,
        requestedProfile: requestedProfile,
        selectedProfile: selectedProfile,
        requestedBudget: requestedBudget,
        selectedBudget: selectedBudget,
        memoryEstimate: estimate,
        reasons: reasons
    ))
case .remote:
    guard remoteModelAccessPolicy.allowsRemoteModels else {
        add(.remoteModelEscalationNotAllowed, to: &reasons)
        let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
        return .rejected(report(
            model: model,
            snapshot: snapshot,
            requestedProfile: requestedProfile,
            selectedProfile: selectedProfile,
            requestedBudget: requestedBudget,
            selectedBudget: selectedBudget,
            memoryEstimate: estimate,
            reasons: reasons
        ))
    }

    guard appIsForeground || remoteModelAccessPolicy.allowsBackgroundRemoteModels else {
        add(.remoteModelBackgroundBlocked, to: &reasons)
        let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
        return .rejected(report(
            model: model,
            snapshot: snapshot,
            requestedProfile: requestedProfile,
            selectedProfile: selectedProfile,

            requestedBudget: requestedBudget,
            selectedBudget: selectedBudget,
            memoryEstimate: estimate,
            reasons: reasons
        ))
    }

    add(.remoteModelEscalationAllowed, to: &reasons)
    add(.remoteDoesNotNeedLocalModelMemory, to: &reasons)
    let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
    return .allowed(report(
        model: model,
        snapshot: snapshot,
        requestedProfile: requestedProfile,
        selectedProfile: selectedProfile,
        requestedBudget: requestedBudget,
        selectedBudget: selectedBudget,
        memoryEstimate: estimate,
        reasons: reasons
    ))
case .gguf, .coreML:
    break
}

if snapshot.isSimulator {
    applySimulatorDowngrade(profile: &selectedProfile, budget: &selectedBudget, reasons: &reasons)
}

if !snapshot.hasMetalSupport {
    applyMetalUnavailableDowngrade(profile: &selectedProfile, budget: &selectedBudget, reasons: &reasons)
}

if !appIsForeground && !selectedBudget.allowBackgroundExecution && requiresHeavyGPU(profile: selectedProfile, budget: selectedBudget) {
    add(.backgroundExecutionBlocked, to: &reasons)
    let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
    return .rejected(report(
        model: model,
        snapshot: snapshot,
        requestedProfile: requestedProfile,
        selectedProfile: selectedProfile,
        requestedBudget: requestedBudget,
        selectedBudget: selectedBudget,
        memoryEstimate: estimate,
        reasons: reasons
    ))
}

if snapshot.powerState.thermalPressure == .critical {
    add(.thermalPressureTooHigh, to: &reasons)
    let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
    return .rejected(report(
        model: model,
        snapshot: snapshot,
        requestedProfile: requestedProfile,

        selectedProfile: selectedProfile,
        requestedBudget: requestedBudget,
        selectedBudget: selectedBudget,
        memoryEstimate: estimate,
        reasons: reasons
    ))
}

if snapshot.powerState.thermalPressure == .serious {
    applySeriousThermalDowngrade(profile: &selectedProfile, budget: &selectedBudget, reasons: &reasons)
}

if snapshot.powerState.isLowPowerModeEnabled {
    applyLowPowerDowngrade(profile: &selectedProfile, budget: &selectedBudget, reasons: &reasons)
}

if let parameters = model.parameterCountBillion, parameters > snapshot.performanceTier.defaultMaximumModelParametersBillion {
    add(.modelExceedsDeviceTier, to: &reasons)
    let tierLimit = snapshot.performanceTier.defaultMaximumModelParametersBillion
    if parameters > tierLimit * 1.25 {
        let estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
        return .rejected(report(
            model: model,
            snapshot: snapshot,
            requestedProfile: requestedProfile,
            selectedProfile: selectedProfile,
            requestedBudget: requestedBudget,
            selectedBudget: selectedBudget,
            memoryEstimate: estimate,
            reasons: reasons
        ))
    }
    applyTierOverageDowngrade(profile: &selectedProfile, budget: &selectedBudget, reasons: &reasons)
}

var estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)
if estimate.confidence == .low {
    add(.unknownModelSize, to: &reasons)
}

let memoryCeiling = effectiveMemoryCeiling(snapshot: snapshot, budget: selectedBudget)
if estimate.estimatedTotalMB > memoryCeiling {
    add(.modelExceedsMemoryBudget, to: &reasons)
    if estimate.estimatedTotalMB > Int(Double(memoryCeiling) * 1.25) {
        return .rejected(report(
            model: model,
            snapshot: snapshot,
            requestedProfile: requestedProfile,
            selectedProfile: selectedProfile,

                requestedBudget: requestedBudget,
                selectedBudget: selectedBudget,
                memoryEstimate: estimate,
                reasons: reasons
            ))
        }

        applyMemoryDowngrade(profile: &selectedProfile, budget: &selectedBudget, reasons: &reasons)
        estimate = ModelMemoryEstimator.estimate(model: model, profile: selectedProfile, budget: selectedBudget)

        if estimate.estimatedTotalMB > effectiveMemoryCeiling(snapshot: snapshot, budget: selectedBudget) {
            return .rejected(report(
                model: model,
                snapshot: snapshot,
                requestedProfile: requestedProfile,
                selectedProfile: selectedProfile,
                requestedBudget: requestedBudget,
                selectedBudget: selectedBudget,
                memoryEstimate: estimate,
                reasons: reasons
            ))
        }
    } else {
        add(.modelFitsMemoryBudget, to: &reasons)
    }

    let finalReport = report(
        model: model,
        snapshot: snapshot,
        requestedProfile: requestedProfile,
        selectedProfile: selectedProfile,
        requestedBudget: requestedBudget,
        selectedBudget: selectedBudget,
        memoryEstimate: estimate,
        reasons: reasons
    )

    if selectedProfile != requestedProfile || selectedBudget != requestedBudget || reasons.containsDowngradeReason {
        return .downgraded(finalReport)
    }
    return .allowed(finalReport)
}

private func applySimulatorDowngrade(
    profile: inout InferenceProfile,
    budget: inout InferenceBudget,
    reasons: inout [ModelFitReason]
) {
    let newContext = min(profile.contextTokens, 2_048)
    let newPrompt = min(budget.maxPromptTokens, 2_048)
    let newCompletion = min(budget.maxCompletionTokens, 512)

    if profile.useMetal || profile.gpuLayerCount > 0 || budget.allowGPU {
        add(.simulatorDisablesMetal, to: &reasons)
        add(.gpuDisabled, to: &reasons)
    }
    if newContext < profile.contextTokens || newPrompt < budget.maxPromptTokens {
        add(.contextReduced, to: &reasons)
    }
    if newCompletion < budget.maxCompletionTokens {

        add(.completionBudgetReduced, to: &reasons)
    }

    profile = profile.adjusted(
        contextTokens: newContext,
        batchSize: min(profile.batchSize, 128),
        threadCount: min(profile.threadCount, 2),
        gpuLayerCount: 0,
        useMetal: false,
        lowPowerMode: true
    )
    budget = budget.adjusted(
        maxPromptTokens: newPrompt,
        maxCompletionTokens: newCompletion,
        allowGPU: false,
        allowBackgroundExecution: false
    )
}

private func applyMetalUnavailableDowngrade(
    profile: inout InferenceProfile,
    budget: inout InferenceBudget,
    reasons: inout [ModelFitReason]
) {
    guard profile.useMetal || profile.gpuLayerCount > 0 || budget.allowGPU else { return }
    add(.metalUnavailable, to: &reasons)
    add(.gpuDisabled, to: &reasons)
    profile = profile.adjusted(gpuLayerCount: 0, useMetal: false)
    budget = budget.adjusted(allowGPU: false)
}

private func applySeriousThermalDowngrade(
    profile: inout InferenceProfile,
    budget: inout InferenceBudget,
    reasons: inout [ModelFitReason]
) {
    add(.thermalPressureTooHigh, to: &reasons)
    let newContext = min(profile.contextTokens, 2_048)
    let newPrompt = min(budget.maxPromptTokens, 2_048)
    let newCompletion = min(budget.maxCompletionTokens, 512)
    if newContext < profile.contextTokens || newPrompt < budget.maxPromptTokens {
        add(.contextReduced, to: &reasons)
    }
    if newCompletion < budget.maxCompletionTokens {
        add(.completionBudgetReduced, to: &reasons)
    }
    profile = profile.adjusted(
        contextTokens: newContext,
        batchSize: min(profile.batchSize, 128),
        threadCount: min(profile.threadCount, 4),
        lowPowerMode: true
    )
    budget = budget.adjusted(maxPromptTokens: newPrompt, maxCompletionTokens: newCompletion)
}

private func applyLowPowerDowngrade(
    profile: inout InferenceProfile,
    budget: inout InferenceBudget,
    reasons: inout [ModelFitReason]
) {
    add(.lowPowerModeDowngrade, to: &reasons)
    let newContext = min(profile.contextTokens, 4_096)
    let newPrompt = min(budget.maxPromptTokens, 4_096)

    let newCompletion = min(budget.maxCompletionTokens, 512)
    if newContext < profile.contextTokens || newPrompt < budget.maxPromptTokens {
        add(.contextReduced, to: &reasons)
    }
    if newCompletion < budget.maxCompletionTokens {
        add(.completionBudgetReduced, to: &reasons)
    }
    profile = profile.adjusted(
        contextTokens: newContext,
        batchSize: min(profile.batchSize, 256),
        threadCount: min(profile.threadCount, 4),
        lowPowerMode: true
    )
    budget = budget.adjusted(maxPromptTokens: newPrompt, maxCompletionTokens: newCompletion)
}

private func applyTierOverageDowngrade(
    profile: inout InferenceProfile,
    budget: inout InferenceBudget,
    reasons: inout [ModelFitReason]
) {
    let newContext = min(profile.contextTokens, 4_096)
    let newCompletion = min(budget.maxCompletionTokens, 768)
    if newContext < profile.contextTokens {
        add(.contextReduced, to: &reasons)
    }
    if newCompletion < budget.maxCompletionTokens {
        add(.completionBudgetReduced, to: &reasons)
    }
    profile = profile.adjusted(contextTokens: newContext, batchSize: min(profile.batchSize, 256))
    budget = budget.adjusted(maxPromptTokens: min(budget.maxPromptTokens, 4_096), maxCompletionTokens: newCompletion)
}

private func applyMemoryDowngrade(
    profile: inout InferenceProfile,
    budget: inout InferenceBudget,
    reasons: inout [ModelFitReason]
) {
    let newContext = min(profile.contextTokens, 2_048)
    let newCompletion = min(budget.maxCompletionTokens, 512)
    if newContext < profile.contextTokens || budget.maxPromptTokens > 2_048 {
        add(.contextReduced, to: &reasons)
    }
    if newCompletion < budget.maxCompletionTokens {
        add(.completionBudgetReduced, to: &reasons)
    }
    if profile.useMetal || profile.gpuLayerCount > 0 || budget.allowGPU {
        add(.gpuDisabled, to: &reasons)
    }
    profile = profile.adjusted(
        contextTokens: newContext,
        batchSize: min(profile.batchSize, 128),
        gpuLayerCount: 0,
        useMetal: false,
        lowPowerMode: true
    )
    budget = budget.adjusted(

            maxPromptTokens: min(budget.maxPromptTokens, 2_048),
            maxCompletionTokens: newCompletion,
            allowGPU: false
        )
    }

    private func requiresHeavyGPU(profile: InferenceProfile, budget: InferenceBudget) -> Bool {
        profile.useMetal || profile.gpuLayerCount > 0 || budget.allowGPU
    }

    private func effectiveMemoryCeiling(snapshot: DeviceCapabilitySnapshot, budget: InferenceBudget) -> Int {
        min(snapshot.recommendedLLMMemoryCeilingMB, budget.maxMemoryMB ?? snapshot.recommendedLLMMemoryCeilingMB)
    }

    private func report(
        model: LocalLLMModel,
        snapshot: DeviceCapabilitySnapshot,
        requestedProfile: InferenceProfile,
        selectedProfile: InferenceProfile,
        requestedBudget: InferenceBudget,
        selectedBudget: InferenceBudget,
        memoryEstimate: ModelMemoryEstimate,
        reasons: [ModelFitReason]
    ) -> ModelFitReport {
        ModelFitReport(
            model: model,
            snapshot: snapshot,
            requestedProfile: requestedProfile,
            selectedProfile: selectedProfile,
            requestedBudget: requestedBudget,
            selectedBudget: selectedBudget,
            memoryEstimate: memoryEstimate,
            reasons: reasons
        )
    }

    private func add(_ reason: ModelFitReason, to reasons: inout [ModelFitReason]) {
        guard !reasons.contains(reason) else { return }
        reasons.append(reason)
    }
}

private extension Array where Element == ModelFitReason {
    var containsDowngradeReason: Bool {
        contains(.simulatorDisablesMetal)
            || contains(.metalUnavailable)
            || contains(.thermalPressureTooHigh)
            || contains(.lowPowerModeDowngrade)
            || contains(.contextReduced)
            || contains(.completionBudgetReduced)
            || contains(.gpuDisabled)
            || contains(.modelExceedsDeviceTier)
            || contains(.modelExceedsMemoryBudget)
    }
}

import Foundation

enum ModelFitDecision: Sendable, Codable, Equatable {
    case allowed(ModelFitReport)
    case downgraded(ModelFitReport)
    case rejected(ModelFitReport)

    var isAllowed: Bool {
        switch self {
        case .allowed, .downgraded:
            return true
        case .rejected:
            return false
        }
    }

    var isRejected: Bool {
        if case .rejected = self {
            return true
        }
        return false
    }

    var report: ModelFitReport {
        switch self {
        case .allowed(let report), .downgraded(let report), .rejected(let report):
            return report
        }
    }
}

struct ModelFitReport: Sendable, Codable, Equatable {
    let model: LocalLLMModel
    let snapshot: DeviceCapabilitySnapshot
    let requestedProfile: InferenceProfile
    let selectedProfile: InferenceProfile
    let requestedBudget: InferenceBudget
    let selectedBudget: InferenceBudget
    let memoryEstimate: ModelMemoryEstimate
    let reasons: [ModelFitReason]
}

enum ModelFitReason: String, Sendable, Codable, Equatable, CaseIterable {
    case modelFitsMemoryBudget
    case modelExceedsMemoryBudget
    case modelExceedsDeviceTier
    case simulatorDisablesMetal
    case metalUnavailable
    case thermalPressureTooHigh
    case lowPowerModeDowngrade
    case backgroundExecutionBlocked
    case contextReduced
    case completionBudgetReduced
    case gpuDisabled
    case tinyIntentAlwaysAllowed
    case remoteDoesNotNeedLocalModelMemory
    case remoteModelEscalationAllowed
    case remoteModelEscalationNotAllowed
    case remoteModelBackgroundBlocked
    case mockBackendNotAllowed
    case unknownModelSize
}

        notes.append("Used conservative backend fallback because model size metadata is incomplete.")
    }

    let kvCache = kvCacheEstimateMB(model: model, profile: profile, budget: budget)
    let overhead = runtimeOverheadMB(backend: model.backend, useMetal: profile.useMetal && budget.allowGPU)

    return ModelMemoryEstimate(
        modelID: model.id,
        estimatedModelMemoryMB: modelMemory,
        estimatedKVCacheMB: kvCache,
        estimatedRuntimeOverheadMB: overhead,
        confidence: confidence,
        notes: notes
    )
}

private static func bitsPerWeight(for quantization: String) -> Double {
    let normalized = quantization
        .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
        .uppercased()

    if normalized.contains("IQ2_XXS") { return 2.1 }
    if normalized.contains("Q2_K") { return 2.6 }
    if normalized.contains("Q3_K_M") { return 3.3 }
    if normalized.contains("IQ4_XS") { return 4.25 }
    if normalized.contains("Q4_K_S") { return 4.4 }
    if normalized.contains("Q4_K_M") { return 4.5 }
    if normalized.contains("Q5_K_S") { return 5.0 }
    if normalized.contains("Q5_K_M") { return 5.1 }
    if normalized.contains("Q6_K") { return 6.0 }
    if normalized.contains("Q8_0") { return 8.0 }
    return 4.8
}

private static func kvCacheEstimateMB(
    model: LocalLLMModel,
    profile: InferenceProfile,
    budget: InferenceBudget
) -> Int {
    switch model.backend {
    case .tinyIntent, .mock:
        return 16
    case .remote:
        return 16
    case .gguf, .coreML:
        let effectiveContextTokens = max(
            1,
            min(profile.contextTokens, min(model.contextLength, budget.maxPromptTokens))
        )
        if let parameterCountBillion = model.parameterCountBillion, parameterCountBillion > 0 {
            let contextScale = Double(effectiveContextTokens) / 4_096.0
            let modelScale = max(128.0, parameterCountBillion * 256.0)
            return max(64, Int(ceil(contextScale * modelScale)))
        }
        return max(128, Int(ceil(Double(effectiveContextTokens) / 16.0)))
    }
}

    private static func runtimeOverheadMB(backend: LLMBackendKind, useMetal: Bool) -> Int {
        let base: Int
        switch backend {
        case .tinyIntent, .mock:
            base = 32
        case .remote:
            base = 64
        case .coreML:
            base = 256
        case .gguf:
            base = 384
        }
        return base + (useMetal ? 256 : 0)
    }

    private static func fallbackModelMemoryMB(for backend: LLMBackendKind) -> Int {
        switch backend {
        case .gguf:
            return 2_048
        case .coreML:
            return 1_024
        case .tinyIntent, .mock:
            return 64
        case .remote:
            return 128
        }
    }

    private static func megabytesRoundedUp(bytes: UInt64) -> Int {
        Int((bytes + 1_048_575) / 1_048_576)
    }

    private static func megabytesRoundedUp(bytes: Double) -> Int {
        max(1, Int(ceil(bytes / 1_048_576.0)))
    }
}

import Foundation

struct RuntimePowerState: Sendable, Codable, Equatable {
    let isLowPowerModeEnabled: Bool
    let thermalPressure: ThermalPressureLevel
    let isExternalPowerConnected: Bool?
    let appIsForeground: Bool

    init(
        isLowPowerModeEnabled: Bool,
        thermalPressure: ThermalPressureLevel,
        isExternalPowerConnected: Bool? = nil,
        appIsForeground: Bool
    ) {
        self.isLowPowerModeEnabled = isLowPowerModeEnabled
        self.thermalPressure = thermalPressure
        self.isExternalPowerConnected = isExternalPowerConnected
        self.appIsForeground = appIsForeground
    }

    var allowsHeavyForegroundInference: Bool {
        appIsForeground && thermalPressure != .critical
    }

    var allowsBackgroundInference: Bool {
        false
    }
}

import Foundation

enum ThermalPressureLevel: String, Sendable, Codable, Equatable, CaseIterable {
    case nominal
    case fair
    case serious
    case critical
    case unknown

    var allowsDeepThink: Bool {
        self == .nominal || self == .fair
    }

    var allowsMaximumForeground: Bool {
        self == .nominal || self == .fair
    }
}

