nonisolated struct MemoryCascadeResult: Sendable {
    let ephemeral: [MemoryContextItem]
    let vectorized: [MemoryContextItem]
    let condensed: [MemoryContextItem]
    let diagnostics: [String]

    var promptFragments: [MemoryContextItem] {
        var fragments: [MemoryContextItem] = []
        if !ephemeral.isEmpty { fragments.append(contentsOf: ephemeral) }
        if !vectorized.isEmpty { fragments.append(contentsOf: vectorized) }
        if !condensed.isEmpty { fragments.append(contentsOf: condensed) }
        return fragments
    }
}

@MainActor
enum MemoryCascade {
    static func recall(
        query: String,
        history: [(role: MessageRole, content: String)],
        context: ModelContext
    ) async -> MemoryCascadeResult {
        let tier1 = history
            .suffix(12)
            .compactMap { item -> MemoryContextItem? in
                let compact = compactAndTrim(item.content, maxLength: 260)
                guard !compact.isEmpty else { return nil }
                return MemoryContextItem(content: compact, scope: .currentTurn, authority: .referenceOnly, createdAt: nil, expiresAt: nil, source: "tier1-ephemeral", topic: nil)
            }

        var diagnostics: [String] = []
        let vectorRecall = await MemoryStore.recallWithDiagnostics(query: query, context: context, limit: 8)
        if let diagnostic = vectorRecall.diagnostic {
            diagnostics.append("vectorized:\(diagnostic)")
        }
        let tier2 = vectorRecall.items
            .filter { $0.source != "rem-condensed" }
            .compactMap { item -> MemoryContextItem? in
                let compact = compactAndTrim(item.content, maxLength: 260)
                guard !compact.isEmpty else { return nil }
                return MemoryContextItem(content: compact, scope: .conversation, authority: .referenceOnly, createdAt: item.createdAt, expiresAt: MemoryStore.inferredExpiresAt(for: item), source: item.source, topic: item.topic)
            }

        let queryTokens = tokenSet(query)
        let condensedDescriptor = FetchDescriptor<MemoryItem>(
            predicate: #Predicate<MemoryItem> { $0.source == "rem-condensed" }
        )
        let condensedItems: [MemoryItem]
        do {
            condensedItems = try context.fetch(condensedDescriptor).filter { item in
                !MemoryStore.isExpired(item)

        }
    } catch {
        diagnostics.append("condensed_fetch_failed:\(RuntimeMetricErrorSanitizer.code(for: error))")
        condensedItems = []
    }

    let rankedTier3 = condensedItems
        .map { item in
            (
                item: item,
                overlap: overlapScore(tokens: queryTokens, content: item.content)
            )
        }
        .sorted { lhs, rhs in
            if lhs.overlap != rhs.overlap { return lhs.overlap > rhs.overlap }
            return lhs.item.createdAt > rhs.item.createdAt
        }
        .prefix(8)
        .compactMap { pair -> MemoryContextItem? in
            let compact = compactAndTrim(pair.item.content, maxLength: 260)
            guard !compact.isEmpty else { return nil }
            return MemoryContextItem(content: compact, scope: .remCondensed, authority: .backgroundOnly, createdAt: pair.item.createdAt, expiresAt: MemoryStore.inferredExpiresAt(for: pair.item), source: pair.item.source, topic: pair.item.topic)
        }

    return MemoryCascadeResult(
        ephemeral: tier1,
        vectorized: tier2,
        condensed: Array(rankedTier3),
        diagnostics: diagnostics
    )
}


static func condenseIfNeeded(context: ModelContext, minimumCount: Int = 24) async throws {
    let descriptor = FetchDescriptor<MemoryItem>(
        sortBy: [SortDescriptor(\.createdAt, order: .forward)]
    )
    let allItems = try context.fetch(descriptor)

    let candidates = allItems.filter { item in
        guard item.source != "rem-condensed" else { return false }
        guard item.isPinned == false else { return false }
        guard !MemoryStore.isExpired(item) else { return false }
        return !item.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    guard candidates.count >= minimumCount else { return }

    let grouped = Dictionary(grouping: candidates) { item -> String in
        let topic = item.topic?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !topic.isEmpty {
            return topic
        }
        return "kind:\(item.kind)"
    }

    for groupKey in grouped.keys.sorted() {

        guard let groupItems = grouped[groupKey], groupItems.count >= 6 else { continue }

        let sortedItems = groupItems.sorted { lhs, rhs in
            if lhs.createdAt != rhs.createdAt { return lhs.createdAt < rhs.createdAt }
            if lhs.content != rhs.content { return lhs.content < rhs.content }
            return lhs.id.uuidString < rhs.id.uuidString
        }
        let newestItems = Array(sortedItems.suffix(12))
        let newestSourceDate = newestItems.last?.createdAt ?? .distantPast
        let cascadeTopic = "cascade:\(groupKey)"

        let existingDescriptor = FetchDescriptor<MemoryItem>(
            predicate: #Predicate<MemoryItem> {
                $0.source == "rem-condensed" && $0.topic == cascadeTopic
            },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        if let newestCondensed = try context.fetch(existingDescriptor).first,
           newestCondensed.createdAt > newestSourceDate {
            continue
        }

        var seenLines: Set<String> = []
        let extracts = newestItems.compactMap { item -> String? in
            let compact = compactAndTrim(item.content, maxLength: 140)
            guard !compact.isEmpty else { return nil }
            let dedupeKey = compact.lowercased()
            guard !seenLines.contains(dedupeKey) else { return nil }
            seenLines.insert(dedupeKey)
            return compact
        }

        guard !extracts.isEmpty else { continue }
        let summaryBody = extracts.enumerated().map { index, line in
            "\(index + 1). \(line)"
        }.joined(separator: " ")
        let summary = "Background (low-authority) condensed \(groupKey): \(summaryBody)"

        try await MemoryStore.remember(
            summary,
            kind: .conversation,
            source: "rem-condensed",
            topic: cascadeTopic,
            context: context
        )

        let saved = try context.fetch(existingDescriptor)
        _ = saved.first
    }

    try context.save()
}

private static func compactAndTrim(_ text: String, maxLength: Int) -> String {
    let normalized = text
        .replacingOccurrences(of: "\n", with: " ")

            .split(whereSeparator: { $0.isWhitespace })
            .joined(separator: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        guard !normalized.isEmpty else { return "" }
        if normalized.count <= maxLength { return normalized }
        let end = normalized.index(normalized.startIndex, offsetBy: maxLength)
        return String(normalized[..<end]).trimmingCharacters(in: .whitespacesAndNewlines) + "…"
    }

    private static func tokenSet(_ text: String) -> Set<String> {
        let lower = text.lowercased()
        var tokens: Set<String> = []
        var current = ""

        for scalar in lower.unicodeScalars {
            if CharacterSet.alphanumerics.contains(scalar) {
                current.unicodeScalars.append(scalar)
            } else if !current.isEmpty {
                if current.count >= 2 {
                    tokens.insert(current)
                }
                current.removeAll(keepingCapacity: true)
            }
        }

        if current.count >= 2 {
            tokens.insert(current)
        }

        return tokens
    }

    private static func overlapScore(tokens queryTokens: Set<String>, content: String) -> Int {
        guard !queryTokens.isEmpty else { return 0 }
        let memoryTokens = tokenSet(content)
        return queryTokens.intersection(memoryTokens).count
    }
}

import Foundation

nonisolated struct MemoryCommandPlan: Sendable, Hashable {
    enum Kind: Sendable, Hashable {
        case saveThenRecall
    }

    let kind: Kind
    let saveContent: String
    let recallQuery: String

    static func saveThenRecall(from prompt: String) -> MemoryCommandPlan? {
        let text = normalized(prompt)
        guard containsAny(text, ["remember", "save", "note", "keep this in mind", "keep in mind"]),
              containsAny(text, ["tell me what", "what you remembered", "what did you remember", "repeat it back", "then tell", "then recall", "and tell me"]) else {
            return nil
        }
        let fact = extractMemoryFact(from: prompt)
        guard !fact.isEmpty else { return nil }
        return MemoryCommandPlan(kind: .saveThenRecall, saveContent: fact, recallQuery: extractMemoryRecallQuery(fromFact: fact, fallback: prompt))
    }

    static func extractMemoryFact(from prompt: String) -> String {
        let trimmed = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        if let name = firstCapture(in: trimmed, pattern: #"(?i)\b(?:can you\s+)?(?:please\s+)?(?:remember|save|note)\s+(?:that\s+)?my name is\s+(.+?)(?:,?\s+then\b|\s+and\s+(?:tell|recall|repeat|confirm)\b|[.!?\n]?$)"#)
            ?? firstCapture(in: trimmed, pattern: #"(?i)\bmy name is\s+([^.!?\n]+)"#) {
            return "User's name is \(cleanCapturedValue(name))"
        }
        if let name = firstCapture(in: trimmed, pattern: #"(?i)\bcall me\s+([^.!?\n]+)"#) {
            return "User prefers to be called \(cleanCapturedValue(name))"
        }
        if let fact = firstCapture(in: trimmed, pattern: #"(?i)\bremember that\s+(.+?)(?:,?\s+then\b|\s+and\s+(?:tell|recall|repeat|confirm)\b|[.!?\n]?$)"#)
            ?? firstCapture(in: trimmed, pattern: #"(?i)\bsave this fact:?\s+(.+?)(?:,?\s+then\b|\s+and\s+(?:tell|recall|repeat|confirm)\b|[.!?\n]?$)"#)
            ?? firstCapture(in: trimmed, pattern: #"(?i)\bkeep this in mind:?\s+(.+?)(?:,?\s+then\b|\s+and\s+(?:tell|recall|repeat|confirm)\b|[.!?\n]?$)"#) {
            return normalizeFactSentence(fact)
        }
        return normalizeFactSentence(trimmed)
    }

    static func extractMemoryRecallQuery(from prompt: String) -> String {
        extractMemoryRecallQuery(fromFact: extractMemoryFact(from: prompt), fallback: prompt)
    }

    private static func extractMemoryRecallQuery(fromFact fact: String, fallback: String) -> String {
        let cleaned = fact
            .replacingOccurrences(of: "User's name is ", with: "", options: [.caseInsensitive])
            .replacingOccurrences(of: "User prefers to be called ", with: "", options: [.caseInsensitive])
            .replacingOccurrences(of: #"(?i)^\s*(?:i\s+am\s+|i'm\s+|i\s+|my\s+)"#, with: "", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if !cleaned.isEmpty { return cleaned }
        return fallback.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func normalized(_ text: String) -> String {
        text.lowercased()
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func containsAny(_ text: String, _ needles: [String]) -> Bool {
        needles.contains { text.contains($0) }
    }

    private static func firstCapture(in text: String, pattern: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
        let ns = text as NSString
        guard let match = regex.firstMatch(in: text, range: NSRange(location: 0, length: ns.length)),
              match.numberOfRanges > 1 else { return nil }
        return ns.substring(with: match.range(at: 1))
    }

    private static func cleanCapturedValue(_ value: String) -> String {
        value.trimmingCharacters(in: CharacterSet(charactersIn: " \t\n\r\"'.,!?"))
    }

    private static func normalizeFactSentence(_ value: String) -> String {
        let cleaned = cleanCapturedValue(value)
        guard !cleaned.isEmpty else { return value.trimmingCharacters(in: .whitespacesAndNewlines) }
        return cleaned
    }
}

