static func exportJSONThrowing(context: ModelContext) throws -> String {
    let all = try context.fetch(FetchDescriptor<MemoryItem>())
    return try exportJSON(items: all)
}

private static func exportJSON(items all: [MemoryItem]) throws -> String {
    struct Export: Codable { let content: String; let kind: String; let topic: String?; let pinned: Bool; let createdAt: Date }
    let items = all.map { Export(content: $0.content, kind: $0.kind, topic: $0.topic, pinned: $0.isPinned, createdAt: $0.createdAt) }
    let enc = JSONEncoder()
    enc.outputFormatting = [.prettyPrinted, .sortedKeys]
    enc.dateEncodingStrategy = .iso8601
    let data = try enc.encode(items)
    return String(decoding: data, as: UTF8.self)
}

// MARK: - Fact extraction (lightweight, rule-based)

nonisolated struct Extracted {
    let content: String
    let kind: MemoryKind
    let topic: String?
}

nonisolated static func extractFacts(from text: String) -> [Extracted] {
    var results: [Extracted] = []
    let sentences = text
        .replacingOccurrences(of: "\n", with: " ")

    .components(separatedBy: CharacterSet(charactersIn: ".!?"))
    .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    .filter { !$0.isEmpty }

let prefLove = ["i love", "i like", "i enjoy", "i prefer", "my favorite", "i'm a fan of", "i am a fan of"]
let durableAllowlist = ["prefer", "favorite", "i am", "i'm", "my name is", "i live", "i work", "working on", "building", "my project", "my app", "my startup"]
let volatileDenylist = ["weather", "temperature", "forecast", "current location", "located", "search result", "live result", "breaking", "reminder", "alarm", "calendar", "busy", "free", "availability", "tomorrow", "today"]
let prefHate = ["i hate", "i dislike", "i don't like", "i do not like", "i can't stand"]
let factSelf = ["i am", "i'm", "i live", "i work", "my name is", "i was born", "i have", "my birthday"]
let projectMarkers = ["working on", "building", "my project", "my app", "my startup"]
let personMarkers: [(String, String)] = [
    (#"my (wife|husband|partner|boyfriend|girlfriend|mom|mother|dad|father|brother|sister|son|daughter|friend|boss|manager|teammate|colleague|neighbor|dog|cat) (?:is |named |'s name is |'s )?([A-Z][a-z]+)"#, "relation")
]

var seen: Set<String> = []
func push(_ e: Extracted) {
    let key = e.content.lowercased()
    if seen.contains(key) { return }
    seen.insert(key)
    results.append(e)
}
for s in sentences {
    let lower = s.lowercased()
    guard durableAllowlist.contains(where: { lower.contains($0) }) else { continue }
    if volatileDenylist.contains(where: { lower.contains($0) }) { continue }
    if prefLove.contains(where: { lower.contains($0) }) {
        push(Extracted(content: "User preference: \(cleaned(s))", kind: .preference, topic: nil))
        continue
    }
    if prefHate.contains(where: { lower.contains($0) }) {
        push(Extracted(content: "User dislike: \(cleaned(s))", kind: .preference, topic: nil))
        continue
    }
    if projectMarkers.contains(where: { lower.contains($0) }) {
        push(Extracted(content: "Project: \(cleaned(s))", kind: .project, topic: "projects"))
        continue
    }

        if factSelf.contains(where: { lower.hasPrefix($0) || lower.contains(" \($0) ") }) {
            push(Extracted(content: cleaned(s), kind: .fact, topic: nil))
            continue
        }
        for (pattern, _) in personMarkers {
            if let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]),
               let match = regex.firstMatch(in: s, range: NSRange(s.startIndex..., in: s)),
               match.numberOfRanges >= 3,
               let rRel = Range(match.range(at: 1), in: s),
               let rName = Range(match.range(at: 2), in: s) {
                let rel = String(s[rRel])
                let name = String(s[rName])
                push(Extracted(content: "\(rel.capitalized): \(name)", kind: .person, topic: "people"))
                break
            }
        }
    }
    return Array(results.prefix(8))
}


nonisolated private static func durableAssistantText(_ assistantText: String, transientTexts: [String]) -> String {
    let base = assistantText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !base.isEmpty else { return "" }
    var filtered = base
    for transient in transientTexts where !transient.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        filtered = filtered.replacingOccurrences(of: transient, with: "", options: [.caseInsensitive])
    }
    let blockedMarkers = ["tool", "observation", "search results", "temporary status"]
    let lines = filtered
        .components(separatedBy: .newlines)
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { line in !line.isEmpty && !blockedMarkers.contains(where: { line.lowercased().contains($0) }) }
    return lines.joined(separator: " ")
}

nonisolated private static func cleaned(_ s: String) -> String {
    var out = s
    if out.count > 140 { out = String(out.prefix(140)) + "…" }
    return out
}

static func migrateExpiryIfNeeded(for item: MemoryItem) {
    // Persisted expiry columns were added after early TestFlight builds. On some upgraded
    // stores, touching those generated SwiftData accessors from the hot chat path can trap

        // before Swift can throw an error. Treat the TTL as computed policy instead of eagerly
        // reading or mutating the optional persisted cache fields during recall.
        _ = item
    }

    static func inferredExpiresAt(for item: MemoryItem) -> Date? {
        ttlPolicy(kind: item.memoryKind, source: item.source).ttl.map { item.createdAt.addingTimeInterval($0) }
    }

    static func isExpired(_ item: MemoryItem, now: Date = Date()) -> Bool {
        guard let expiresAt = inferredExpiresAt(for: item) else { return false }
        return expiresAt <= now
    }

    nonisolated static func ttlPolicy(kind: MemoryKind, source: String) -> TTLPolicy {
        let lowerSource = source.lowercased()

        if lowerSource.contains("tool") || lowerSource.contains("ephemeral") || lowerSource.contains("observation") {
            return TTLPolicy(freshness: .volatile, ttl: 45 * 60)
        }

        if lowerSource == "rem-condensed" {
            return TTLPolicy(freshness: .durable, ttl: nil)
        }

        if kind == .conversation || lowerSource.contains("crumb") || lowerSource.contains("chat") {
            return TTLPolicy(freshness: .shortLived, ttl: 6 * 60 * 60)
        }

        if kind == .preference || kind == .project || kind == .person {
            return TTLPolicy(freshness: .timeless, ttl: nil)
        }

        return TTLPolicy(freshness: .durable, ttl: 30 * 24 * 60 * 60)
    }
}

import Foundation
import Observation
import OSLog
import UIKit
#if canImport(MSAL)
import MSAL
#endif

@MainActor
@Observable
final class MicrosoftGraphAuthManager {
    private let logger = Logger(subsystem: "ai.lumen.microsoftgraph", category: "auth")
    private let nativeOAuth = NativeMicrosoftOAuthClient()
    private(set) var account: MicrosoftGraphAccountSnapshot?
    private(set) var token: MicrosoftGraphTokenSnapshot?
    private(set) var tokensByScopeSet: [String: MicrosoftGraphTokenSnapshot] = [:]
    private(set) var accounts: [MicrosoftGraphAccountSnapshot] = []
    private(set) var isAuthenticating = false
    private(set) var lastError: Error?
    private let cachedForceNativeOAuth: Bool

    var isSignedIn: Bool { account != nil }
    private var shouldUseNativeOAuth: Bool {
        cachedForceNativeOAuth
    }
    var canUseMSAL: Bool {
        guard !shouldUseNativeOAuth else { return false }
        #if canImport(MSAL)
        return true
        #else
        return false
        #endif
    }
    var authProviderDescription: String { canUseMSAL ? "MSAL" : "Native OAuth PKCE" }
    var authProviderPath: String { canUseMSAL ? "MSAL" : "Native fallback (ASWebAuthenticationSession + PKCE)" }
    var activeClientID: String {
        (try? MicrosoftGraphConfiguration.load().clientID) ?? "Unavailable"
    }
    var activeRedirectURI: String {
        if let configured = try? MicrosoftGraphConfiguration.load().redirectURI {
            return configured
        }
        return "msauth.\(Bundle.main.bundleIdentifier ?? "com.27pm.lumenclone")://auth"
    }
    var bundleIdentifier: String {
        Bundle.main.bundleIdentifier ?? "Unavailable"
    }

    init() {
        cachedForceNativeOAuth = (try? MicrosoftGraphConfiguration.load().forceNativeOAuth) ?? false
    }

    func bootstrap() async {
        lastError = nil
        await reloadCachedAccounts()
        guard lastError == nil else { return }
        guard let first = accounts.first else { return }
        do {
            _ = try await acquireToken(scopes: MicrosoftGraphScope.inboxRead, preferredAccountID: first.id, forceRefresh: false)
            lastError = nil
        } catch {
            lastError = error
            logger.info("Silent Microsoft token bootstrap failed: \(String(describing: error), privacy: .private)")
        }
    }

    func reloadCachedAccounts() async {

    if canUseMSAL {
        #if canImport(MSAL)
        do {
            let application = try makeMSALApplication()
            let cached = try application.allAccounts()
            let previousAccountID = account?.id
            accounts = cached.map(Self.snapshot(from:))
            if let previousAccountID {
                account = accounts.first(where: { $0.id == previousAccountID }) ?? accounts.first
            } else {
                account = accounts.first
            }
        } catch {
            lastError = error
        }
        #endif
    } else {
        let previousAccountID = account?.id
        accounts = nativeOAuth.cachedAccounts()
        if let previousAccountID {
            account = accounts.first(where: { $0.id == previousAccountID }) ?? accounts.first
        } else {
            account = accounts.first
        }
        if let session = nativeOAuth.loadCachedSession() {
            let restored = Self.tokenSnapshot(from: session.token, scopes: MicrosoftGraphScope.inboxRead)
            token = restored
            tokensByScopeSet[Self.scopeCacheKey(for: MicrosoftGraphScope.inboxRead)] = restored
            lastError = nil
        }
    }
}

func signIn(scopes: [String] = MicrosoftGraphScope.inboxRead, presentationViewController: UIViewController) async throws {
    isAuthenticating = true
    defer { isAuthenticating = false }
    do {
        let result = try await interactiveToken(scopes: scopes, presentationViewController: presentationViewController)
        token = result.token
        tokensByScopeSet[Self.scopeCacheKey(for: scopes)] = result.token
        account = result.account
        await reloadCachedAccounts()
    } catch {
        let normalizedError = normalize(error)
        lastError = normalizedError
        throw normalizedError
    }
}

func acquireToken(scopes: [String], preferredAccountID: String? = nil, forceRefresh: Bool = false) async throws -> String {
    #if canImport(MSAL)
    if canUseMSAL {
        let application = try makeMSALApplication()
        let cachedAccounts = try application.allAccounts()

        let selected = cachedAccounts.first { Self.snapshot(from: $0).id == preferredAccountID } ?? cachedAccounts.first
        guard let selected else { throw MicrosoftGraphAuthError.noAccount }

        do {
            let result = try await application.acquireTokenSilentAsync(scopes: scopes, account: selected, forceRefresh: forceRefresh)
            let mapped = Self.tokenSnapshot(from: result, scopes: scopes)
            token = mapped
            tokensByScopeSet[Self.scopeCacheKey(for: scopes)] = mapped
            account = Self.snapshot(from: result.account)
            lastError = nil
            return mapped.accessToken
        } catch let error as NSError where Self.isInteractionRequired(error) {
            token = nil
            tokensByScopeSet = [:]
            lastError = MicrosoftGraphAuthError.interactionRequired
            throw MicrosoftGraphAuthError.interactionRequired
        } catch {
            lastError = error
            throw error
        }
    }
    #endif

    do {
        let nativeToken = try await nativeOAuth.acquireToken(scopes: scopes, forceRefresh: forceRefresh)
        let mapped = Self.tokenSnapshot(from: nativeToken, scopes: scopes)
        token = mapped
        tokensByScopeSet[Self.scopeCacheKey(for: scopes)] = mapped
        if let session = nativeOAuth.loadCachedSession() {
            account = session.account
            accounts = [session.account]
        }
        lastError = nil
        return mapped.accessToken
    } catch {
        lastError = error
        throw error
    }
}
func cachedToken(for scopes: [String]) -> MicrosoftGraphTokenSnapshot? {
    tokensByScopeSet[Self.scopeCacheKey(for: scopes)]
}

func registerExternalError(_ error: Error) {
    lastError = normalize(error)
}

func signOutCurrentAccount() async {
    if canUseMSAL {
        #if canImport(MSAL)
        do {
            let application = try makeMSALApplication()
            let cached = try application.allAccounts()
            if let currentID = account?.id, let match = cached.first(where: { Self.snapshot(from: $0).id == currentID }) {
                try application.remove(match)
            }
        } catch {

            lastError = error
        }
        token = nil
        tokensByScopeSet = [:]
        account = nil
        await reloadCachedAccounts()
        MicrosoftGraphMailCacheStore.shared.clearAll()
        #endif
    } else {
        nativeOAuth.signOut()
        token = nil
        tokensByScopeSet = [:]
        account = nil
        accounts = []
        MicrosoftGraphMailCacheStore.shared.clearAll()
    }
}

