        if folders.isEmpty { return .validEmpty("No Outlook mail folders found.") }
        return .success(folders.map { folder in
            "- \(folder.displayName) — id: \(folder.id), unread: \(folder.unreadItemCount ?? 0), total: \(folder.totalItemCount ?? 0)"
