@discardableResult
static func ensureFleetChatLoaded(appState: AppState, stored: [StoredModel], intent: ModelLoadIntent = .userChat) async -> Bool {
    await ensureFleetChatLoaded(snapshot: ModelLoadSnapshot(appState: appState, stored: stored), appState: appState, intent: intent)
}

@discardableResult
private static func ensureFleetChatLoaded(snapshot: ModelLoadSnapshot, appState: AppState?, intent: ModelLoadIntent) async -> Bool {
    await Task.yield()
    _ = await configureFleetRuntime(snapshot: snapshot)
    if await hasLoadedChatRuntime(snapshot: snapshot) { return true }
    guard canStartModelLoad(intent: intent) else { return false }
    if let chatLoadTask {
        let result = await finishChatLoad(chatLoadTask)
        _ = await configureFleetRuntime(snapshot: snapshot)
        if let selectedChatModelID = result.selectedChatModelID {

            appState?.activeChatModelID = selectedChatModelID
        }
        return result.loaded
    }
    let pending = PendingChatModelLoad(task: Task.detached(priority: .userInitiated) {
        await performEnsureFleetChatLoaded(snapshot: snapshot, intent: intent)
    })
    chatLoadTask = pending
    let result = await finishChatLoad(pending)
    _ = await configureFleetRuntime(snapshot: snapshot)
    if let selectedChatModelID = result.selectedChatModelID {
        appState?.activeChatModelID = selectedChatModelID
    }
    return result.loaded
}

@discardableResult
nonisolated private static func configureFleetRuntime(snapshot loadSnapshot: ModelLoadSnapshot) async -> LumenModelFleetSnapshot {
    let snapshot = LumenModelFleetResolver.resolveV1(snapshot: loadSnapshot)
    await SlotModelRuntimeCoordinator.shared.configure(
        assignments: snapshot.assignments,
        contextSize: loadSnapshot.contextSize,
        preferExclusiveChatRuntime: true
    )
    return snapshot
}

@discardableResult
nonisolated private static func performEnsureFleetChatLoaded(snapshot loadSnapshot: ModelLoadSnapshot, intent: ModelLoadIntent) async -> ChatLoadResult {
    guard !Task.isCancelled, await MainActor.run(body: { canStartModelLoad(intent: intent) }) else { return ChatLoadResult(loaded: false, selectedChatModelID: nil) }
    await Task.yield()
    let snapshot = await configureFleetRuntime(snapshot: loadSnapshot)

    let runnableSlots = [LumenModelSlot.cortex, .executor, .mouth, .mimicry, .rem]
        .filter { snapshot.assignment(for: $0) != nil }
    guard !runnableSlots.isEmpty else {
        return await ensurePrimaryChatLoaded(snapshot: loadSnapshot)
    }

    // Keep one chat runtime warm for non-agent/plain chat. Slot-agent turns load
    // each role-baked GGUF lazily, one slot at a time, through the coordinator.
    await Task.yield()
    let primaryReady = await SlotModelRuntimeCoordinator.shared.ensurePrimaryReady(preferredSlots: [.mouth, .cortex])
    guard !Task.isCancelled else { return ChatLoadResult(loaded: false, selectedChatModelID: nil) }
    return ChatLoadResult(loaded: primaryReady || !runnableSlots.isEmpty, selectedChatModelID: nil)
}

private static func finishChatLoad(_ pending: PendingChatModelLoad) async -> ChatLoadResult {
    let result = await pending.task.value
    if chatLoadTask?.id == pending.id {
        chatLoadTask = nil
    }
    return result
}

nonisolated private static func hasLoadedChatRuntime(snapshot: ModelLoadSnapshot) async -> Bool {
    let preferredID = snapshot.activeChatModelID
    if let preferredID,
       let preferred = snapshot.storedModels.first(where: { $0.id.uuidString == preferredID && $0.modelRole == .chat }) {
        return await AppLlamaService.shared.loadedChatPath == preferred.resolvedPath
    }
    return await AppLlamaService.shared.isChatLoaded
}

@discardableResult
nonisolated private static func ensurePrimaryChatLoaded(snapshot: ModelLoadSnapshot) async -> ChatLoadResult {
    let preferredID = snapshot.activeChatModelID
    if let preferredID,
       let preferred = snapshot.storedModels.first(where: { $0.id.uuidString == preferredID && $0.modelRole == .chat }) {
        guard FileManager.default.fileExists(atPath: preferred.resolvedPath) else { return ChatLoadResult(loaded: false, selectedChatModelID: nil) }
        if await AppLlamaService.shared.isChatLoaded,
           await AppLlamaService.shared.loadedChatPath == preferred.resolvedPath {
            return ChatLoadResult(loaded: true, selectedChatModelID: nil)
        }
    } else if await AppLlamaService.shared.isChatLoaded {
        return ChatLoadResult(loaded: true, selectedChatModelID: nil)
    }
    let candidates = snapshot.storedModels.filter { $0.modelRole == .chat }
    await SlotModelRuntimeCoordinator.shared.configure(
        assignments: [:],
        contextSize: snapshot.contextSize,
        preferExclusiveChatRuntime: true
    )
    await Task.yield()
    let selectedChatModelID = await SlotModelRuntimeCoordinator.shared.ensureChatModelSelection(
        candidates: candidates,
        preferredID: preferredID
    )
    return ChatLoadResult(loaded: selectedChatModelID != nil, selectedChatModelID: selectedChatModelID)
}

@discardableResult
static func ensureEmbedLoaded(appState: AppState, stored: [StoredModel], intent: ModelLoadIntent = .userChat) async -> Bool {

    if await hasLoadedEmbeddingRuntime(appState: appState, stored: stored) { return true }
    guard canStartModelLoad(intent: intent) else { return false }
    if let embedLoadTask { return await finishEmbedLoad(embedLoadTask) }
    let pending = PendingModelLoad(task: Task { @MainActor in
        await performEnsureEmbedLoaded(appState: appState, stored: stored, intent: intent)
    })
    embedLoadTask = pending
    return await finishEmbedLoad(pending)
}

private static func finishEmbedLoad(_ pending: PendingModelLoad) async -> Bool {
    let result = await pending.task.value
    if embedLoadTask?.id == pending.id {
        embedLoadTask = nil
    }
    return result
}

private static func hasLoadedEmbeddingRuntime(appState: AppState, stored: [StoredModel]) async -> Bool {
    let snapshot = ModelLoadSnapshot(appState: appState, stored: stored)
    return await hasLoadedEmbeddingRuntime(snapshot: snapshot)
}

nonisolated private static func hasLoadedEmbeddingRuntime(snapshot: ModelLoadSnapshot) async -> Bool {
    let preferredID = snapshot.activeEmbeddingModelID
    if let preferredID,
       let preferred = snapshot.storedModels.first(where: { $0.id.uuidString == preferredID && $0.modelRole == .embedding }) {
        return await AppLlamaService.shared.loadedEmbedPath == preferred.resolvedPath
    }
    return await AppLlamaService.shared.hasSemanticEmbeddingRuntime
}

private static func performEnsureEmbedLoaded(appState: AppState, stored: [StoredModel], intent: ModelLoadIntent) async -> Bool {
    guard !Task.isCancelled, canStartModelLoad(intent: intent) else { return false }
    let preferredID = appState.activeEmbeddingModelID
    if let preferredID,
       let preferred = stored.first(where: { $0.id.uuidString == preferredID && $0.modelRole == .embedding }) {
        let resolvedPath = ModelStorage.resolvedModelURL(from: preferred.localPath, fileName: preferred.fileName).path
        if await AppLlamaService.shared.isEmbedLoaded,
           await AppLlamaService.shared.loadedEmbedPath == resolvedPath {
            return true
        }
    } else if await AppLlamaService.shared.isEmbedLoaded {
        return true
    }

        let candidates = stored.filter { $0.modelRole == .embedding }
        await SlotModelRuntimeCoordinator.shared.configure(
            assignments: await SlotModelRuntimeCoordinator.shared.configuredAssignments,
            contextSize: appState.contextSize,
            preferExclusiveChatRuntime: true
        )
        guard !Task.isCancelled else { return false }
        return await SlotModelRuntimeCoordinator.shared.ensureEmbeddingModel(
            appState: appState,
            candidates: candidates,
            preferredID: preferredID
        )
    }
}

import Foundation

nonisolated enum ModelOutputSanitizer {
    private static let hiddenReasoningTagPattern = "(?:think[\\w_-]*|thinking|reasoning|analysis|chain_of_thought)"

    static func stripHiddenBlocks(_ text: String) -> String {
        var output = text
        output = output.replacingOccurrences(
            of: "(?is)<\\s*(\(hiddenReasoningTagPattern))\\b[^>]*>.*?</\\s*\\1\\s*>",
            with: "",
            options: .regularExpression
        )
        output = output.replacingOccurrences(
            of: "(?im)^\\s*<\\s*\(hiddenReasoningTagPattern)\\b[^\\n]*(?:\\n|$)",
            with: "",
            options: .regularExpression
        )
        return output.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func stripHiddenBlocksPreservingPayloadMarkers(_ text: String) -> String {
        let payloads = WebRichContentPayload.decodeAll(from: text)
        var clean = stripHiddenBlocks(WebRichContentPayload.removingMarkers(from: text))
        let existingKeys = Set(WebRichContentPayload.decodeAll(from: clean).map(payloadKey))
        var seen = existingKeys
        for payload in payloads {
            let key = payloadKey(payload)
            guard seen.insert(key).inserted else { continue }
            clean += payload.encodedMarker()
        }
        return clean.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func boundedPrefix(_ text: String, limit: Int = 1200) -> String {
        String(stripHiddenBlocks(text).prefix(max(0, limit)))
    }

    private static func payloadKey(_ payload: WebRichContentPayload) -> String {
        switch payload.kind {
        case .searchResults:
            return "search:\(payload.query ?? ""):\(payload.results.map { $0.url ?? $0.title }.joined(separator: "|"))"
        case .fetchedPage:
            return "page:\(payload.page?.url ?? "")"
        }
    }
}

import Foundation
import SwiftData

@MainActor
final class ModelRuntimeController {
    private var didStart = false
    private var refreshRequestID: UUID?

    func startupIfNeeded(refresh: @escaping () async -> Void) {
        guard !didStart else { return }
        didStart = true
        Task { await refresh() }
    }

    func refreshLoadedPaths() async -> Set<String>? {
        let requestID = UUID()
        refreshRequestID = requestID

        var set: Set<String> = []
        if let sharedPath = await AppLlamaService.shared.loadedChatPath,
           FileManager.default.fileExists(atPath: sharedPath) {
            let fileName = URL(fileURLWithPath: sharedPath).lastPathComponent
            set.insert(ModelStorage.resolvedModelURL(from: sharedPath, fileName: fileName).path)
        }
        let chatPaths = await AppLlamaService.shared.loadedChatPathsBySlot
        for path in chatPaths.values where FileManager.default.fileExists(atPath: path) {
            let fileName = URL(fileURLWithPath: path).lastPathComponent
            set.insert(ModelStorage.resolvedModelURL(from: path, fileName: fileName).path)
        }
        if let p = await AppLlamaService.shared.loadedEmbedPath,
           await AppLlamaService.shared.hasSemanticEmbeddingRuntime,
           FileManager.default.fileExists(atPath: p) {
            let fileName = URL(fileURLWithPath: p).lastPathComponent
            set.insert(ModelStorage.resolvedModelURL(from: p, fileName: fileName).path)
        }

        guard refreshRequestID == requestID else { return nil }
        return set
    }

    func load(_ sm: StoredModel, appState: AppState, storedModels: [StoredModel]) async throws {
        if sm.modelRole == .chat || sm.modelRole == .roleAdapter {
            await ModelLoader.ensureFleetChatLoaded(appState: appState, stored: storedModels, intent: .userChat)
        } else {
            guard ModelLoader.canStartModelLoad(intent: .userChat) else { return }
            let resolvedPath = ModelStorage.resolvedModelURL(from: sm.localPath, fileName: sm.fileName).path
            try await AppLlamaService.shared.loadEmbeddingModel(path: resolvedPath)
        }
    }

    func unload(_ sm: StoredModel, adapterSlot: (StoredModel) -> LumenModelSlot?) async {
        if sm.modelRole == .chat {

            let resolvedPath = ModelStorage.resolvedModelURL(from: sm.localPath, fileName: sm.fileName).path
            if await AppLlamaService.shared.loadedChatPath == resolvedPath {
                await AppLlamaService.shared.unloadAllChat()
                return
            }
            let slots = await AppLlamaService.shared.loadedChatPathsBySlot.filter { $0.value == resolvedPath }.map(\.key)
            for slot in slots { await AppLlamaService.shared.unloadChat(for: slot) }
        } else if sm.modelRole == .roleAdapter {
            if let slot = adapterSlot(sm) { await AppLlamaService.shared.unloadRoleAdapter(slot: slot) }
        } else {
            await AppLlamaService.shared.unloadEmbed()
        }
    }

    func reload(_ sm: StoredModel, appState: AppState, storedModels: [StoredModel]) async throws {
        if sm.modelRole == .chat || sm.modelRole == .roleAdapter {
            await ModelLoader.ensureFleetChatLoaded(appState: appState, stored: storedModels, intent: .userChat)
        } else {
            guard ModelLoader.canStartModelLoad(intent: .userChat) else { return }
            try await AppLlamaService.shared.reloadEmbed()
        }
    }
}

import Foundation

nonisolated enum ModelStorage {
    struct ModelFilesResult {
        let directory: URL?
        let files: [URL]
        let mode: String
        let diagnostic: String?
    }

    enum StorageError: LocalizedError, Equatable {
        case documentDirectoryUnavailable
        case persistentDirectoryUnavailable
        case directoryCreationFailed(String)
        case contentsUnavailable(String)

        var errorDescription: String? {
            switch self {
            case .documentDirectoryUnavailable:
                return "The documents directory is unavailable."
            case .persistentDirectoryUnavailable:
                return "No persistent app data directory is available."
            case .directoryCreationFailed(let path):
                return "Could not create the model directory at \(path)."
            case .contentsUnavailable:
                return "Could not list model files."
            }
        }
    }

    static func modelsDirectoryURL(fileManager: FileManager = .default) -> URL {
        guard let directory = try? modelsDirectoryURLOrThrow(fileManager: fileManager) else {
            return unavailableModelsDirectoryURL(fileManager: fileManager)
        }
        return directory
    }

    static func modelsDirectoryURLOrThrow(fileManager: FileManager = .default) throws -> URL {
        let base = try persistentBaseDirectoryURL(fileManager: fileManager)
        return try modelsDirectoryURL(base: base, fileManager: fileManager)
    }

    static func modelFilesWithDiagnostics(fileManager fm: FileManager = .default) -> ModelFilesResult {
        modelFilesWithDiagnostics(
            modelsDirectory: { try modelsDirectoryURLOrThrow(fileManager: fm) },
            contents: { directory in
                try fm.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil, options: [.skipsHiddenFiles])
            }
        )
    }

    static func modelFilesWithDiagnosticsForTests(
        modelsDirectory: () throws -> URL,
        contents: (URL) throws -> [URL]
    ) -> ModelFilesResult {
        modelFilesWithDiagnostics(modelsDirectory: modelsDirectory, contents: contents)
    }

    static func modelsDirectoryURLOrThrow(
        documentDirectories: [URL],
        applicationSupportDirectories: [URL],
        fileManager: FileManager = .default
    ) throws -> URL {

    let base = try persistentBaseDirectoryURL(
        documentDirectories: documentDirectories,
        applicationSupportDirectories: applicationSupportDirectories
    )
    return try modelsDirectoryURL(base: base, fileManager: fileManager)
}

private static func modelsDirectoryURL(base: URL, fileManager: FileManager) throws -> URL {
    let directory = base.appendingPathComponent("Models", isDirectory: true)
    do {
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
    } catch {
        throw StorageError.directoryCreationFailed(directory.path)
    }
    return directory
}

private static func modelFilesWithDiagnostics(
    modelsDirectory: () throws -> URL,
    contents: (URL) throws -> [URL]
) -> ModelFilesResult {
    let directory: URL
    do {
        directory = try modelsDirectory()
    } catch {
        return ModelFilesResult(
            directory: nil,
            files: [],
            mode: "failed",
            diagnostic: "models_directory_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
        )
    }
    do {
        let files = try contents(directory)
        return ModelFilesResult(
            directory: directory,
            files: files,
            mode: "loaded",
            diagnostic: files.isEmpty ? "empty_models_directory" : nil
        )
    } catch {
        return ModelFilesResult(
            directory: directory,
            files: [],
            mode: "failed",
            diagnostic: "models_list_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
        )
    }
}

static func persistentBaseDirectoryURL(fileManager: FileManager = .default) throws -> URL {
    try persistentBaseDirectoryURL(
        documentDirectories: fileManager.urls(for: .documentDirectory, in: .userDomainMask),
        applicationSupportDirectories: fileManager.urls(for: .applicationSupportDirectory, in: .userDomainMask)
    )
}

static func persistentBaseDirectoryURL(documentDirectories: [URL], applicationSupportDirectories: [URL]) throws -> URL {
    if let documents = documentDirectories.first { return documents }

    if let appSupport = applicationSupportDirectories.first { return appSupport }
    throw StorageError.persistentDirectoryUnavailable
}

static func documentsDirectoryURL(fileManager: FileManager = .default) throws -> URL {
    try documentsDirectoryURL(candidateDirectories: fileManager.urls(for: .documentDirectory, in: .userDomainMask))
}

static func documentsDirectoryURL(candidateDirectories: [URL]) throws -> URL {
    guard let base = candidateDirectories.first else {
        throw StorageError.documentDirectoryUnavailable
    }
    return base
}

static func resumeDirectoryURL(fileManager: FileManager = .default) -> URL {
    guard let directory = try? resumeDirectoryURLOrThrow(fileManager: fileManager) else {
        return unavailableModelsDirectoryURL(fileManager: fileManager)
            .appendingPathComponent(".resume", isDirectory: true)
    }
    return directory
}

static func resumeDirectoryURLOrThrow(fileManager: FileManager = .default) throws -> URL {
    let directory = try modelsDirectoryURLOrThrow(fileManager: fileManager)
        .appendingPathComponent(".resume", isDirectory: true)
    do {
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
    } catch {
        throw StorageError.directoryCreationFailed(directory.path)
    }
    return directory
}

static func resolvedModelURL(from storedPath: String, fileName: String, fileManager: FileManager = .default) -> URL {
    let storedURL = URL(fileURLWithPath: storedPath)
    if fileManager.fileExists(atPath: storedURL.path) {
        return storedURL
    }

    let preferred = modelsDirectoryURL(fileManager: fileManager).appendingPathComponent(fileName)
    if fileManager.fileExists(atPath: preferred.path) {
        return preferred
    }

    guard let base = try? documentsDirectoryURL(fileManager: fileManager) else {
        return storedURL
    }
    let previousNested = base
        .appendingPathComponent("Hybrid Coder", isDirectory: true)
        .appendingPathComponent("Models", isDirectory: true)
        .appendingPathComponent(fileName)
    if fileManager.fileExists(atPath: previousNested.path) {
        return previousNested
    }

        return storedURL
    }

    private static func unavailableModelsDirectoryURL(fileManager: FileManager) -> URL {
        fileManager.temporaryDirectory
            .appendingPathComponent("LumenPersistentDirectoryUnavailable", isDirectory: true)
            .appendingPathComponent("Models", isDirectory: true)
    }
}

