    case .restricted: return .restricted
    case .authorizedWhenInUse, .authorizedAlways: return .granted
    @unknown default: return .notDetermined
    }
}

private func mapMicStatus(_ status: AVAudioApplication.recordPermission) -> PermissionState {
    switch status {
    case .undetermined: return .notDetermined
    case .denied: return .denied
    case .granted: return .granted

        @unknown default: return .notDetermined
        }
    }

    private func mapSpeechStatus(_ status: SFSpeechRecognizerAuthorizationStatus) -> PermissionState {
        switch status {
        case .notDetermined: return .notDetermined
        case .denied: return .denied
        case .restricted: return .restricted
        case .authorized: return .granted
        @unknown default: return .notDetermined
        }
    }

    private func mapCameraStatus(_ status: AVAuthorizationStatus) -> PermissionState {
        switch status {
        case .notDetermined: return .notDetermined
        case .denied: return .denied
        case .restricted: return .restricted
        case .authorized: return .granted
        @unknown default: return .notDetermined
        }
    }

    private func mapPhotosStatus(_ status: PHAuthorizationStatus) -> PermissionState {
        switch status {
        case .notDetermined: return .notDetermined
        case .denied: return .denied
        case .restricted: return .restricted
        case .authorized: return .granted
        case .limited: return .limited
        @unknown default: return .notDetermined
        }
    }

    private func mapMotionStatus(_ status: CMAuthorizationStatus) -> PermissionState {
        switch status {
        case .notDetermined: return .notDetermined
        case .denied: return .denied
        case .restricted: return .restricted
        case .authorized: return .granted
        @unknown default: return .notDetermined
        }
    }

    private func currentAlarmState() -> PermissionState {
        guard Self.alarmUsageDescriptionPresent() else {
            return .unavailable
        }
#if canImport(AlarmKit)
        if #available(iOS 26.0, *) {
            switch AlarmManager.shared.authorizationState {
            case .notDetermined: return .notDetermined
            case .authorized: return .granted
            case .denied: return .denied
            @unknown default: return .unavailable
            }
        }
#endif
        return .unavailable
    }
}

@MainActor
final class LocationAuthWaiter: NSObject, CLLocationManagerDelegate {
    /// Concurrency contract: all state mutation and callback dispatch are confined to MainActor.
    var onChange: (() -> Void)?
    private var done = false

    func finishOnce() {
        MainActor.preconditionIsolated()
        if done { return }

        done = true
        let cb = onChange
        onChange = nil
        cb?()
    }

    nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        Task { @MainActor in
            if manager.authorizationStatus != .notDetermined {
                self.finishOnce()
            }
        }
    }
}

import Foundation

/// Coarse token ≈ char conversion factor used for llama.cpp-style prompt budgeting.
/// SentencePiece/BPE tokenizers average ~3.5–4.2 chars/token on English text; we pick
/// a conservative value so budgets err on the side of fitting, not overflowing.
nonisolated enum PromptBudgetConstants {
    static let approxCharsPerToken: Double = 3.8
    static let safetyTokens: Int = 256
    static let hardAttachmentCeiling: Int = 80_000
    static let hardMemoriesCeiling: Int = 4_000
    static let minUserCharCap: Int = 4_000
    static let attachmentShareFraction: Double = 0.55
    static let memoriesShareFraction: Double = 0.20
    static let minHistoryChars: Int = 512
    static let minPerAttachmentChars: Int = 800
    static let fastInteractiveTotalChars: Int = 2_200
    static let fastInteractiveSystemChars: Int = 900
    static let fastInteractiveHistoryChars: Int = 420
    static let fastInteractiveMemoriesChars: Int = 220
    static let fastInteractiveMaxUserChars: Int = 280
    static let fastInteractiveUserMessageChars: Int = 160
    static let agentJSONTotalChars: Int = 3_800
    static let agentJSONSystemChars: Int = 2_200
    static let agentJSONHistoryChars: Int = 420
    static let agentJSONUserChars: Int = 900
    static let agentJSONSafetyTokens: Int = 160
}

nonisolated enum PromptLatencyClass: String, Sendable {
    case fastInteractive
    case normalInteractive
    case documentGrounded
    case developerTrace
}

nonisolated struct PromptLatencySelection: Sendable, Equatable {
    let latencyClass: PromptLatencyClass
    let reason: String
}

nonisolated enum PromptLatencyClassifier {
    static func classify(
        userMessage: String,
        attachments: [ChatAttachment],
        developerTraceModeEnabled: Bool,
        reasoningCaptureEnabled: Bool,
        modelName: String
    ) -> PromptLatencySelection {
        if developerTraceModeEnabled || reasoningCaptureEnabled {
            return PromptLatencySelection(latencyClass: .developerTrace, reason: "developer-trace")
        }
        if !attachments.isEmpty {
            return PromptLatencySelection(latencyClass: .documentGrounded, reason: "attachments")
        }
        let trimmed = userMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        let lower = trimmed.lowercased()
        if modelName.lowercased().contains("json") {

            return PromptLatencySelection(latencyClass: .normalInteractive, reason: "agent-json")
        }
        if trimmed.count <= PromptBudgetConstants.fastInteractiveUserMessageChars, !looksDocumentOrToolHeavy(lower) {
            return PromptLatencySelection(latencyClass: .fastInteractive, reason: "short-simple-user-turn")
        }
        return PromptLatencySelection(latencyClass: .normalInteractive, reason: "standard-turn")
    }

    private static func looksDocumentOrToolHeavy(_ lowercasedMessage: String) -> Bool {
        let signals = [
            "file", "document", "attachment", "pdf", "rag", "search", "web", "url",
            "summarize", "analyse this", "analyze this", "read ", "browse", "tool", "codebase"
        ]
        return signals.contains { lowercasedMessage.contains($0) }
    }
}

/// Total per-section character budget for a single generation request.
/// Attachments get the largest dedicated share because they are typically the
/// biggest non-mandatory block. The user message and system prompt are always
/// fit in full (bounded by a generous cap to avoid pathological inputs).
nonisolated struct PromptBudget: Sendable {
    let totalChars: Int
    let attachmentsShare: Int
    let memoriesShare: Int
    let historyShare: Int
    let maxUserChars: Int?
    let maxSystemPromptChars: Int?

    init(totalChars: Int, attachmentsShare: Int, memoriesShare: Int, historyShare: Int, maxUserChars: Int? = nil, maxSystemPromptChars: Int? = nil) {
        self.totalChars = totalChars
        self.attachmentsShare = attachmentsShare
        self.memoriesShare = memoriesShare
        self.historyShare = historyShare
        self.maxUserChars = maxUserChars
        self.maxSystemPromptChars = maxSystemPromptChars
    }

    static func make(
        contextSize: Int,
        maxTokens: Int,
        systemPromptChars: Int,
        userMessageChars: Int,
        hasAttachments: Bool,
        hasMemories: Bool
    ) -> PromptBudget {
        let tokenBudget = max(512, contextSize - maxTokens - PromptBudgetConstants.safetyTokens)
        let totalChars = max(2048, Int(Double(tokenBudget) * PromptBudgetConstants.approxCharsPerToken))

        // Fixed cost: system prompt + a reasonable cap on user text + chat template overhead.
        let boundedUser = min(userMessageChars, max(PromptBudgetConstants.minUserCharCap, totalChars / 4))

    let templateOverhead = 512
    let fixed = min(systemPromptChars + boundedUser + templateOverhead, totalChars - 512)
    var remaining = max(1024, totalChars - fixed)

    let attachmentsShare: Int
    if hasAttachments {
        attachmentsShare = min(
            Int(Double(remaining) * PromptBudgetConstants.attachmentShareFraction),
            PromptBudgetConstants.hardAttachmentCeiling
        )
    } else {
        attachmentsShare = 0
    }
    remaining -= attachmentsShare

    let memoriesShare: Int
    if hasMemories {
        memoriesShare = min(
            Int(Double(remaining) * PromptBudgetConstants.memoriesShareFraction),
            PromptBudgetConstants.hardMemoriesCeiling
        )
    } else {
        memoriesShare = 0
    }
    remaining -= memoriesShare

    let historyShare = max(PromptBudgetConstants.minHistoryChars, remaining)

    return PromptBudget(
        totalChars: totalChars,
        attachmentsShare: attachmentsShare,
        memoriesShare: memoriesShare,
        historyShare: historyShare,
        maxUserChars: nil,
        maxSystemPromptChars: nil
    )
}

static func fastInteractive() -> PromptBudget {
    PromptBudget(
        totalChars: PromptBudgetConstants.fastInteractiveTotalChars,
        attachmentsShare: 0,
        memoriesShare: PromptBudgetConstants.fastInteractiveMemoriesChars,
        historyShare: PromptBudgetConstants.fastInteractiveHistoryChars,
        maxUserChars: PromptBudgetConstants.fastInteractiveMaxUserChars,
        maxSystemPromptChars: PromptBudgetConstants.fastInteractiveSystemChars
    )
}

static func agentJSON(contextSize: Int, maxTokens: Int) -> PromptBudget {
    let promptTokenBudget = max(
        256,
        contextSize - maxTokens - PromptBudgetConstants.agentJSONSafetyTokens
    )
    let contextBoundChars = Int(Double(promptTokenBudget) * 3.2)
    let totalChars = min(
        PromptBudgetConstants.agentJSONTotalChars,
        max(1_800, contextBoundChars)
    )
    return PromptBudget(
        totalChars: totalChars,
        attachmentsShare: 0,
        memoriesShare: 0,

            historyShare: min(PromptBudgetConstants.agentJSONHistoryChars, totalChars / 5),
            maxUserChars: min(PromptBudgetConstants.agentJSONUserChars, totalChars / 3),
            maxSystemPromptChars: min(PromptBudgetConstants.agentJSONSystemChars, (totalChars * 2) / 3)
        )
    }
}


/// Per-attachment outcome after the budget is applied. Surfaced to the UI so
/// the user can see when a file was trimmed.
nonisolated struct AttachmentRenderState: Sendable, Hashable {
    let id: UUID
    let name: String
    let includedChars: Int
    let totalChars: Int
    let mode: String
    let diagnostic: String?

    init(
        id: UUID,
        name: String,
        includedChars: Int,
        totalChars: Int,
        mode: String = "loaded",
        diagnostic: String? = nil
    ) {
        self.id = id
        self.name = name
        self.includedChars = includedChars
        self.totalChars = totalChars
        self.mode = mode
        self.diagnostic = diagnostic
    }

    var truncated: Bool { includedChars < totalChars }
    var extractionFailed: Bool { mode == "failed" }
    var emptyExtractedText: Bool { diagnostic == "empty_attachment_text" }
}

/// Result of running the prompt assembler on a request.
nonisolated struct PromptAssembly: Sendable {
    let systemPrompt: String
    let history: [(role: MessageRole, content: String)]
    let userMessage: String
    let attachmentStates: [AttachmentRenderState]
    let usedChars: Int
    let budgetChars: Int
    let latencyClass: PromptLatencyClass

    var historyTuples: [(String, String)] {
        history.map { ($0.role.rawValue, $0.content) }
    }
}

nonisolated enum AttachmentNormalizationMode: Sendable {
    case preserveRaw
    case agentRouting
}

/// Deterministic, priority-based prompt assembly.
///
/// Truncation priority (first to shrink, in order):
/// 1. Attachments — each file is head-truncated to its per-file cap and annotated
///    with a visible "[... truncated ...]" marker.
/// 2. Conversation history — oldest turns are dropped until the share fits.
///    The most recent turns are preserved because they're most relevant.
/// 3. Memories — the list is prefix-truncated to fit its share.
///
/// Preserved but bounded:
/// - The system prompt keeps original head/tail constraints when capped, with

///   fast-mode guidance appended only after preserved original instructions.
/// - The current user message, except for a final safety cap at roughly
///   ¼ of the total budget (protects against multi-MB paste dumps).
nonisolated enum PromptAssembler {

    static func assemble(
        systemPrompt: String,
        history: [(role: MessageRole, content: String)],
        userMessage: String,
        memories: [MemoryContextItem],
        attachments: [ChatAttachment],
        budget: PromptBudget,
        attachmentNormalization: AttachmentNormalizationMode = .preserveRaw,
        latencyClass: PromptLatencyClass = .normalInteractive
    ) -> PromptAssembly {
        let userCap = budget.maxUserChars.map { min(userMessage.count, $0) }
            ?? min(userMessage.count, max(PromptBudgetConstants.minUserCharCap, budget.totalChars / 4))
        let boundedUser = truncateMiddle(userMessage, maxChars: userCap)

        let systemCap = budget.maxSystemPromptChars ?? systemPrompt.count
        let boundedSystemPrompt = truncateSystemPrompt(systemPrompt, maxChars: systemCap, latencyClass: latencyClass)

        let memoriesBlock = buildMemoriesBlock(memories: memories, share: budget.memoriesShare, latencyClass: latencyClass)
        let (attachmentsBlock, states) = buildAttachmentsBlock(
            attachments: attachments,
            share: budget.attachmentsShare,
            normalization: attachmentNormalization
        )
        let finalSystem = boundedSystemPrompt + memoriesBlock + attachmentsBlock

        let keptHistory = fitHistory(history: history, share: budget.historyShare, latencyClass: latencyClass)

        let historyChars = keptHistory.reduce(0) { $0 + $1.content.count + 16 }
        let totalUsed = finalSystem.count + boundedUser.count + historyChars

        return PromptAssembly(
            systemPrompt: finalSystem,
            history: keptHistory,
            userMessage: boundedUser,
            attachmentStates: states,
            usedChars: totalUsed,
            budgetChars: budget.totalChars,
            latencyClass: latencyClass
        )
    }

    /// Lightweight preview used by the chat UI to show whether attachments
    /// will be truncated at send time. Uses the same budget math as `assemble`.
    static func previewAttachmentStates(
        attachments: [ChatAttachment],
        contextSize: Int,

    maxTokens: Int,
    systemPromptChars: Int,
    userMessageChars: Int,
    hasMemories: Bool
) -> [AttachmentRenderState] {
    guard !attachments.isEmpty else { return [] }
    let budget = PromptBudget.make(
        contextSize: contextSize,
        maxTokens: maxTokens,
        systemPromptChars: systemPromptChars,
        userMessageChars: userMessageChars,
        hasAttachments: true,
        hasMemories: hasMemories
    )
    let (_, states) = buildAttachmentsBlock(
        attachments: attachments,
        share: budget.attachmentsShare,
        normalization: .preserveRaw
    )
    return states
}

// MARK: - Sections

private static func buildMemoriesBlock(memories: [MemoryContextItem], share: Int, latencyClass: PromptLatencyClass) -> String {
    guard !memories.isEmpty, share > 0 else { return "" }
    var used = 0
    var items: [MemoryContextItem] = []
    let isFastInteractive = latencyClass == .fastInteractive
    let maxItems = isFastInteractive ? 2 : 10
    for m in memories.prefix(maxItems) {
        let cleaned = m.content.trimmingCharacters(in: .whitespacesAndNewlines)
        if cleaned.isEmpty { continue }
        let contentCap = isFastInteractive ? 96 : cleaned.count
        let bounded = truncateMiddle(cleaned, maxChars: contentCap)
        let line = "• [\(m.scope.rawValue) | \(m.authority.rawValue)] " + bounded
        let cost = line.count + 1
        if used + cost > share { break }
        items.append(MemoryContextItem(content: bounded, scope: m.scope, authority: m.authority, createdAt: m.createdAt, expiresAt: m.expiresAt, source: m.source, topic: m.topic))
        used += cost
    }
    return PromptContextBuilder.renderMemoryBlock(items)
}

private static func buildAttachmentsBlock(
    attachments: [ChatAttachment],
    share: Int,
    normalization: AttachmentNormalizationMode
) -> (String, [AttachmentRenderState]) {
    guard !attachments.isEmpty else { return ("", []) }

    struct Loaded {
        let attachment: ChatAttachment
        let text: String
        let mode: String
        let diagnostic: String?
    }
    let loaded: [Loaded] = attachments.map {

    let extraction = AttachmentResolver.extractTextWithDiagnostics($0)
    let prepared: String
    switch normalization {
    case .preserveRaw:
        prepared = extraction.text ?? ""
    case .agentRouting:
        prepared = normalizeForAgentRouting(extraction.text ?? "")
    }
    return Loaded(attachment: $0, text: prepared, mode: extraction.mode, diagnostic: extraction.diagnostic)
}

if share <= 0 {
    // No room at all — still report states so UI can show "truncated".
    let states = loaded.map {
        AttachmentRenderState(
            id: $0.attachment.id,
            name: $0.attachment.name,
            includedChars: 0,
            totalChars: $0.text.count,
            mode: $0.mode,
            diagnostic: $0.diagnostic
        )
    }
    return ("", states)
}

let perFileCap = max(PromptBudgetConstants.minPerAttachmentChars, share / max(1, loaded.count))
var out = "\nThe user attached the following file(s) to this message. Treat them as authoritative context. Do NOT call files.read for them — their content is provided below.\n"
var states: [AttachmentRenderState] = []
states.reserveCapacity(loaded.count)

for (i, item) in loaded.enumerated() {
    let totalCount = item.text.count
    let included = truncateHead(item.text, maxChars: perFileCap)
    let trimmed = included.trimmingCharacters(in: .whitespacesAndNewlines)

    out += "\n--- Attachment \(i + 1): \(item.attachment.name) (\(item.attachment.kind.rawValue)) ---\n"
    if item.mode == "failed" {
        out += "[Could not extract text from this file. Diagnostic: \(item.diagnostic ?? "attachment_extract_failed").]\n"
    } else if item.diagnostic == "empty_attachment_text" {
        out += "[Attachment contains no extractable text.]\n"
    } else if trimmed.isEmpty {
        out += "[Attachment content was empty after normalization.]\n"
    } else {
        out += trimmed
        if included.count < totalCount {
            let omitted = totalCount - included.count

                out += "\n[... truncated: \(omitted) more characters omitted ...]\n"
            } else {
                out += "\n"
            }
        }

        states.append(AttachmentRenderState(
            id: item.attachment.id,
            name: item.attachment.name,
            includedChars: min(included.count, totalCount),
            totalChars: totalCount,
            mode: item.mode,
            diagnostic: item.diagnostic
        ))
    }
    out += "--- End attachments ---\n"
    return (out, states)
}

private static func fitHistory(
    history: [(role: MessageRole, content: String)],
    share: Int,
    latencyClass: PromptLatencyClass
) -> [(role: MessageRole, content: String)] {
    guard share > 0, !history.isEmpty else { return [] }
    var kept: [(role: MessageRole, content: String)] = []
    var used = 0
    let maxTurns = latencyClass == .fastInteractive ? 2 : Int.max
    // Walk newest → oldest; prepend so original order is preserved.
    for h in history.reversed() {
        if kept.count >= maxTurns { break }
        let content = h.content.count > share
            ? truncateMiddle(h.content, maxChars: max(256, share / 2))
            : h.content
        let cost = content.count + 16
        if used + cost > share { break }
        kept.insert((role: h.role, content: content), at: 0)
        used += cost
    }
    return kept
}

// MARK: - Truncation primitives

private static func truncateSystemPrompt(_ systemPrompt: String, maxChars: Int, latencyClass: PromptLatencyClass) -> String {
    guard systemPrompt.count > maxChars else { return systemPrompt }
    guard latencyClass == .fastInteractive else { return truncateMiddle(systemPrompt, maxChars: maxChars) }
    let fastDirective = """

    Fast interactive mode: keep the answer concise for this simple turn, but continue to obey all preserved system, tool, privacy, and safety instructions above.
    """
    guard maxChars > fastDirective.count + 128 else {
        return truncateMiddle(systemPrompt, maxChars: maxChars)
    }
    let preservedOriginal = truncateMiddle(systemPrompt, maxChars: maxChars - fastDirective.count)
    return preservedOriginal + fastDirective
}

    static func truncateHead(_ s: String, maxChars: Int) -> String {
        if s.count <= maxChars { return s }
        if maxChars <= 0 { return "" }
        return String(s.prefix(maxChars))
    }

    static func truncateMiddle(_ s: String, maxChars: Int) -> String {
        if s.count <= maxChars { return s }
        if maxChars <= 64 { return String(s.prefix(maxChars)) }
        let half = (maxChars - 32) / 2
        return String(s.prefix(half)) + "\n[... truncated ...]\n" + String(s.suffix(half))
    }

    private static func normalizeForAgentRouting(_ text: String) -> String {
        var normalized = text.replacingOccurrences(of: "\r\n", with: "\n")
        normalized = stripCodeFenceWrapperIfPresent(normalized)
        normalized = collapseNoisyStructuralRuns(normalized)
        normalized = normalized.replacingOccurrences(of: #"[ \t]{2,}"#, with: " ", options: .regularExpression)
        normalized = normalized.replacingOccurrences(of: #"\n{3,}"#, with: "\n\n", options: .regularExpression)
        return normalized.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func stripCodeFenceWrapperIfPresent(_ text: String) -> String {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.hasPrefix("```"), trimmed.hasSuffix("```") else { return text }
        let lines = trimmed.split(separator: "\n", omittingEmptySubsequences: false)
        guard lines.count >= 2 else { return text }
        guard String(lines[0]).hasPrefix("```"), String(lines[lines.count - 1]) == "```" else { return text }
        return lines.dropFirst().dropLast().joined(separator: "\n")
    }

    private static func collapseNoisyStructuralRuns(_ text: String) -> String {
        var out = text
        out = out.replacingOccurrences(of: #"`{4,}"#, with: "```", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[=_\-\*#]{8,}"#, with: "-----", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[|]{4,}"#, with: "|||", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[<>]{4,}"#, with: "<<<>>>", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[\\/\[\]\(\)\{\}:;,+]{12,}"#, with: " [structural-run-collapsed] ", options: .regularExpression)
        return out
    }
}

