struct PhotoLibrarySnapshot {
    let authorizationStatus: PHAuthorizationStatus
    let assets: [PHAsset]
}

static func indexPhotosWithDiagnostics(
    monthsBack: Int = 6,
    context: ModelContext,
    photoLibrarySnapshot: PhotoLibrarySnapshot? = nil
) async -> IndexResult {
    let snapshot: PhotoLibrarySnapshot
    if let photoLibrarySnapshot {

    snapshot = photoLibrarySnapshot
} else {
    let status = await withCheckedContinuation { (cont: CheckedContinuation<PHAuthorizationStatus, Never>) in
        PHPhotoLibrary.requestAuthorization(for: .readWrite) { cont.resume(returning: $0) }
    }
    guard status == .authorized || status == .limited else {
        return IndexResult(indexedCount: 0, mode: .failed, diagnostic: "photos_permission_denied:\(photoAuthorizationDiagnostic(status))")
    }
    let start = Calendar.current.date(byAdding: .month, value: -monthsBack, to: Date()) ?? Date()
    let options = PHFetchOptions()
    options.predicate = NSPredicate(format: "creationDate >= %@", start as NSDate)
    options.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
    options.fetchLimit = 2000
    let fetch = PHAsset.fetchAssets(with: options)

    var assets: [PHAsset] = []
    fetch.enumerateObjects { asset, _, _ in assets.append(asset) }
    snapshot = PhotoLibrarySnapshot(authorizationStatus: status, assets: assets)
}
let status = snapshot.authorizationStatus
guard status == .authorized || status == .limited else {
    return IndexResult(indexedCount: 0, mode: .failed, diagnostic: "photos_permission_denied:\(photoAuthorizationDiagnostic(status))")
}
let assets = snapshot.assets
do {
    try wipe(.photo, context: context)
} catch PersistenceError.diskWriteBudgetDenied {
    return IndexResult(indexedCount: 0, mode: .skipped, diagnostic: "cleanup_deferred:disk_write_budget_denied")
} catch {
    let diagnostic = "cleanup_persist_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
    logger.error("persist_failed op=indexPhotos.cleanup scope=RAGChunk diagnostic=\(diagnostic, privacy: .public) error_code=\(RuntimeMetricErrorSanitizer.code(for: error), privacy: .public)")
    return IndexResult(indexedCount: 0, mode: .failed, diagnostic: diagnostic)
}
guard !assets.isEmpty else {
    return IndexResult(indexedCount: 0, mode: .skipped, diagnostic: "empty_photo_library")
}

var selfieIDs: Set<String> = []

let selfieAlbums = PHAssetCollection.fetchAssetCollections(with: .smartAlbum, subtype: .smartAlbumSelfPortraits, options: nil)
selfieAlbums.enumerateObjects { coll, _, _ in
    let a = PHAsset.fetchAssets(in: coll, options: nil)
    a.enumerateObjects { asset, _, _ in selfieIDs.insert(asset.localIdentifier) }
}

var buckets: [String: [PHAsset]] = [:]
let df = DateFormatter(); df.dateFormat = "yyyy-MM"
for a in assets {
    let key = df.string(from: a.creationDate ?? Date())
    buckets[key, default: []].append(a)
}

var count = 0
var pendingVectors: [PendingVector] = []
var activeEmbeddingMetadata: RAGEmbeddingIndexMetadata?
let cpuToken = CPUWatchdogGuard.shared.begin(category: .rag)
defer { CPUWatchdogGuard.shared.end(token: cpuToken) }
let totalBuckets = buckets.count
for (month, items) in buckets {
    if Task.isCancelled || CPUWatchdogGuard.shared.shouldDegrade(category: .rag) || !ResourceBudgetGate.allowsMaintenance(reason: "rag.indexPhotos") { break }
    let favorites = items.filter(\.isFavorite).count
    let videos = items.filter { $0.mediaType == .video }.count
    let screenshots = items.filter { $0.mediaSubtypes.contains(.photoScreenshot) }.count
    let selfies = items.filter { selfieIDs.contains($0.localIdentifier) }.count
    let livePhotos = items.filter { $0.mediaSubtypes.contains(.photoLive) }.count
    let portraits = items.filter { $0.mediaSubtypes.contains(.photoDepthEffect) }.count
    var geo = 0
    for a in items where a.location != nil { geo += 1 }

    let df2 = DateFormatter(); df2.dateStyle = .medium
    let first = items.last?.creationDate.map { df2.string(from: $0) } ?? "?"
    let last = items.first?.creationDate.map { df2.string(from: $0) } ?? "?"

    let summary = """
    Photos (\(month)): \(items.count) items between \(first) and \(last).
    \(favorites) favorites, \(videos) videos, \(screenshots) screenshots, \(selfies) selfies, \(livePhotos) live photos, \(portraits) portraits, \(geo) with location.
    """

    let embeddingResult: EmbeddingRuntimeResult
    do {
        let embeddingText = SemanticEmbeddingText.document(

        content: summary,
        sourceName: "Photos \(month)",
        sourceType: RAGSourceType.photo.rawValue,
        chunkIndex: 0
    )
    embeddingResult = try await AssistantKernel.runEmbeddingWithIdentity(text: embeddingText)
} catch {
    let diagnostic = "embedding_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
    logger.error("rag_embedding_failed op=indexPhotos source=\(month, privacy: .public) diagnostic=\(diagnostic, privacy: .public) error_code=\(RuntimeMetricErrorSanitizer.code(for: error), privacy: .public)")
    return persistPendingVectorsForEarlyExit(
        context: context,
        operation: "indexPhotos.embeddingFailure",
        diagnostic: diagnostic,
        pending: &pendingVectors
    )
}
let emb = embeddingResult.vector
guard !emb.isEmpty else {
    logger.error("rag_embedding_empty op=indexPhotos source=\(month, privacy: .public)")
    return persistPendingVectorsForEarlyExit(
        context: context,
        operation: "indexPhotos.emptyEmbedding",
        diagnostic: "embedding_empty",
        pending: &pendingVectors
    )
}
let embeddingMetadata = embeddingMetadata(for: embeddingResult)
if let earlyExit = prepareEmbeddingMetadata(
    embeddingMetadata,
    active: &activeEmbeddingMetadata,
    pending: &pendingVectors,
    context: context,
    identityChangeOperation: "indexPhotos.embeddingIdentityChanged"
) {
    return earlyExit
}
let chunk = RAGChunk(
    content: summary,
    sourceType: .photo,
    sourceName: "Photos \(month)",
    sourceRef: month,
    chunkIndex: 0,
    embedding: emb,
    embeddingFormatVersion: embeddingMetadata.formatVersion,
    embeddingModelIdentifier: embeddingMetadata.modelIdentifier,
    embeddingDimension: embeddingMetadata.dimension
)

        pendingVectors.append(PendingVector(chunk: chunk, bucket: RAGSourceType.photo.rawValue, vector: emb, metadata: embeddingMetadata))
        count += 1
    }
    guard let persistResult = persistAndAppendVectors(context: context, operation: "indexPhotos.complete", pending: &pendingVectors) else {
        logger.error("rag_index_partial_failure op=indexPhotos persisted=0 attempted=\(count, privacy: .public)")
        return IndexResult(indexedCount: 0, mode: .failed, diagnostic: "persist_failed")
    }
    if persistResult.indexState == .unavailable {
        return IndexResult(indexedCount: persistResult.persistedCount, mode: .partial, diagnostic: "vector_index_reload_failed")
    }
    if persistResult.persistedCount < totalBuckets {
        return IndexResult(indexedCount: persistResult.persistedCount, mode: persistResult.persistedCount > 0 ? .partial : .failed, diagnostic: "maintenance_budget_or_cancellation")
    }
    return IndexResult(indexedCount: persistResult.persistedCount, mode: .indexed, diagnostic: nil)
}

// MARK: - Notes (plain text import via share)

static func indexNote(title: String, body: String, context: ModelContext) async -> Int {
    await indexNoteWithDiagnostics(title: title, body: body, context: context).indexedCount
}

static func indexNoteWithDiagnostics(title: String, body: String, context: ModelContext) async -> IndexResult {
    let pieces = chunkText(body)
    guard !pieces.isEmpty else {
        return IndexResult(indexedCount: 0, mode: .skipped, diagnostic: "empty_text")
    }
    var count = 0
    var pendingVectors: [PendingVector] = []
    var activeEmbeddingMetadata: RAGEmbeddingIndexMetadata?
    let cpuToken = CPUWatchdogGuard.shared.begin(category: .rag)
    defer { CPUWatchdogGuard.shared.end(token: cpuToken) }
    for (i, piece) in pieces.enumerated() {
        if Task.isCancelled || CPUWatchdogGuard.shared.shouldDegrade(category: .rag) || !ResourceBudgetGate.allowsMaintenance(reason: "rag.indexNote") { break }
        let embeddingResult: EmbeddingRuntimeResult
        do {
            let embeddingText = SemanticEmbeddingText.document(
                content: piece,
                sourceName: title,
                sourceType: RAGSourceType.note.rawValue,

            chunkIndex: i
        )
        embeddingResult = try await AssistantKernel.runEmbeddingWithIdentity(text: embeddingText)
    } catch {
        let diagnostic = "embedding_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
        logger.error("rag_embedding_failed op=indexNote source_hash=\(Self.sourceLogID(title), privacy: .public) diagnostic=\(diagnostic, privacy: .public) error_code=\(RuntimeMetricErrorSanitizer.code(for: error), privacy: .public)")
        return persistPendingVectorsForEarlyExit(
            context: context,
            operation: "indexNote.embeddingFailure",
            diagnostic: diagnostic,
            pending: &pendingVectors
        )
    }
    let emb = embeddingResult.vector
    guard !emb.isEmpty else {
        logger.error("rag_embedding_empty op=indexNote source_hash=\(Self.sourceLogID(title), privacy: .public)")
        return persistPendingVectorsForEarlyExit(
            context: context,
            operation: "indexNote.emptyEmbedding",
            diagnostic: "embedding_empty",
            pending: &pendingVectors
        )
    }
    let embeddingMetadata = embeddingMetadata(for: embeddingResult)
    if let earlyExit = prepareEmbeddingMetadata(
        embeddingMetadata,
        active: &activeEmbeddingMetadata,
        pending: &pendingVectors,
        context: context,
        identityChangeOperation: "indexNote.embeddingIdentityChanged"
    ) {
        return earlyExit
    }
    let chunk = RAGChunk(
        content: piece,
        sourceType: .note,
        sourceName: title,
        sourceRef: nil,
        chunkIndex: i,
        embedding: emb,
        embeddingFormatVersion: embeddingMetadata.formatVersion,
        embeddingModelIdentifier: embeddingMetadata.modelIdentifier,
        embeddingDimension: embeddingMetadata.dimension
    )
    pendingVectors.append(PendingVector(chunk: chunk, bucket: RAGSourceType.note.rawValue, vector: emb, metadata: embeddingMetadata))
    count += 1
}

    guard let persistResult = persistAndAppendVectors(context: context, operation: "indexNote.complete", pending: &pendingVectors) else {
        logger.error("rag_index_partial_failure op=indexNote source_hash=\(Self.sourceLogID(title), privacy: .public) persisted=0 attempted=\(count, privacy: .public)")
        return IndexResult(indexedCount: 0, mode: .failed, diagnostic: "persist_failed")
    }
    if persistResult.indexState == .unavailable {
        return IndexResult(indexedCount: persistResult.persistedCount, mode: .partial, diagnostic: "vector_index_reload_failed")
    }
    if persistResult.persistedCount < pieces.count {
        return IndexResult(indexedCount: persistResult.persistedCount, mode: persistResult.persistedCount > 0 ? .partial : .failed, diagnostic: "maintenance_budget_or_cancellation")
    }
    return IndexResult(indexedCount: persistResult.persistedCount, mode: .indexed, diagnostic: nil)
}

static func embeddingRuntimeAvailable() async -> Bool {
    do {
        let probe = try await AssistantKernel.runEmbedding(text: "embedding_readiness_probe")
        if probe.isEmpty {
            logger.error("rag_embedding_empty op=readiness")
            return false
        }
        return true
    } catch {
        logger.error("rag_embedding_failed op=readiness error_code=\(RuntimeMetricErrorSanitizer.code(for: error), privacy: .public)")
        return false
    }
}

private static func photoAuthorizationDiagnostic(_ status: PHAuthorizationStatus) -> String {
    switch status {
    case .authorized:
        return "authorized"
    case .limited:
        return "limited"
    case .denied:
        return "denied"
    case .restricted:
        return "restricted"
    case .notDetermined:
        return "not_determined"
    @unknown default:
        return "unknown"
    }
}

// MARK: - Helpers

static func chunkText(_ text: String) -> [String] {
    let normalized = text.replacingOccurrences(of: "\r\n", with: "\n")
    let paragraphs = normalized.components(separatedBy: "\n\n").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
    var chunks: [String] = []
    var current = ""
    for p in paragraphs {

            if current.count + p.count + 2 <= chunkSize {
                current += (current.isEmpty ? "" : "\n\n") + p
            } else {
                if !current.isEmpty { chunks.append(current) }
                if p.count > chunkSize {
                    var start = p.startIndex
                    while start < p.endIndex {
                        let end = p.index(start, offsetBy: chunkSize, limitedBy: p.endIndex) ?? p.endIndex
                        chunks.append(String(p[start..<end]))
                        if end == p.endIndex { break }
                        let step = chunkSize - chunkOverlap
                        start = p.index(start, offsetBy: step, limitedBy: p.endIndex) ?? p.endIndex
                    }
                    current = ""
                } else {
                    current = p
                }
            }
        }
        if !current.isEmpty { chunks.append(current) }
        return chunks
    }
}

import Foundation

nonisolated struct ReferenceResolution: Sendable {
    let originalPrompt: String
    let rewrittenPrompt: String
    let resolvedReferences: [String: String]
    let confidence: Double
    let diagnostics: [String]

    var hasRewrite: Bool { originalPrompt != rewrittenPrompt }
}

nonisolated enum ReferenceResolver {
    static func resolve(
        prompt: String,
        history: [(role: MessageRole, content: String)],
        relevantMemories: [MemoryContextItem],
        currentTurnLedger: [ToolLedgerEntry] = []
    ) -> ReferenceResolution {
        let normalizedPrompt = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalizedPrompt.isEmpty else {
            return ReferenceResolution(originalPrompt: prompt, rewrittenPrompt: prompt, resolvedReferences: [:], confidence: 0, diagnostics: ["empty_prompt"])
        }

        var rewritten = normalizedPrompt
        var mapping: [String: String] = [:]
        var diagnostics: [String] = []
        var score: Double = 0

        let candidates = recentPersonCandidates(history: history, relevantMemories: relevantMemories)
        if containsPronoun(normalizedPrompt) {
            if let candidate = candidates.first {
                rewritten = rewritePronouns(in: rewritten, with: candidate)
                mapping["pronoun"] = candidate
                score += 0.75
                diagnostics.append("resolved_pronoun_from_recent_context")
            } else {
                diagnostics.append("pronoun_detected_no_safe_referent")
            }
        }

        if looksLikeBarePersonReply(normalizedPrompt), recentAssistantAskedForCallTarget(history: history) {
            rewritten = "call \(normalizedPrompt)"
            mapping["bare_person_reply"] = normalizedPrompt
            score += 0.65
            diagnostics.append("resolved_bare_person_reply_from_call_clarification")
        }

        if containsPreviousReference(normalizedPrompt) {
            if let tool = currentTurnLedger.last?.toolID {
                rewritten = rewritePreviousReference(in: rewritten, replacement: "the previous \(tool) result")
                mapping["previous one"] = "previous \(tool) result"
                score += 0.2
                diagnostics.append("resolved_deictic_from_current_turn_toolledger")
            } else {

            diagnostics.append("deictic_detected_without_current_turn_toolledger")
        }
    }

    let bounded = min(1.0, max(0.0, score))
    return ReferenceResolution(
        originalPrompt: prompt,
        rewrittenPrompt: rewritten,
        resolvedReferences: mapping,
        confidence: bounded,
        diagnostics: diagnostics
    )
}

private static func containsPronoun(_ text: String) -> Bool {
    let lower = text.lowercased()
    return [" call her", " text her", " message her", "call him", "text him", "message him", "her ", " him "]
        .contains { lower.contains($0) } || lower.hasPrefix("call her") || lower.hasPrefix("call him") || lower.hasPrefix("text her") || lower.hasPrefix("text him") || lower == "call her" || lower == "call him"
}

private static func containsPreviousReference(_ text: String) -> Bool {
    let lower = text.lowercased()
    return ["previous one", "that one", "last one", "use previous"].contains { lower.contains($0) }
}

private static func looksLikeBarePersonReply(_ text: String) -> Bool {
    let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.rangeOfCharacter(from: .newlines) == nil else { return false }
    guard trimmed.split(separator: " ").count <= 4 else { return false }
    guard trimmed.range(of: #"^[A-Z][A-Za-z'’-]+(?:\s+[A-Z][A-Za-z'’-]+){0,3}$"#, options: .regularExpression) != nil else { return false }
    let lower = trimmed.lowercased()
    return !["yes", "no", "ok", "okay", "thanks", "hello", "hi"].contains(lower)
}

private static func recentAssistantAskedForCallTarget(history: [(role: MessageRole, content: String)]) -> Bool {
    history.suffix(4).reversed().contains { item in
        guard item.role == .assistant else { return false }
        let lower = item.content.lowercased()
        return lower.contains("which contact or phone number should i call")
            || lower.contains("which one should i call")
            || lower.contains("who should i call")
    }
}

private static func rewritePronouns(in text: String, with referent: String) -> String {
    var out = text
    let patterns = ["\\bher\\b", "\\bhim\\b"]
    for pattern in patterns {

        out = out.replacingOccurrences(of: pattern, with: referent, options: [.regularExpression, .caseInsensitive])
    }
    return out
}

private static func rewritePreviousReference(in text: String, replacement: String) -> String {
    var out = text
    ["previous one", "that one", "last one"].forEach { token in
        out = out.replacingOccurrences(of: token, with: replacement, options: [.caseInsensitive])
    }
    return out
}

private static func recentPersonCandidates(history: [(role: MessageRole, content: String)], relevantMemories: [MemoryContextItem]) -> [String] {
    var candidates: [String] = []
    var seen: Set<String> = []

    for content in history.suffix(8).reversed().map(\.content) {
        if let name = extractPersonName(content), seen.insert(name.lowercased()).inserted {
            candidates.append(name)
        }
    }

    let memories = relevantMemories
        .filter { $0.scope == .person || ($0.topic?.lowercased().contains("contact") ?? false) || ($0.topic?.lowercased().contains("people") ?? false) }
        .sorted { lhs, rhs in
            (lhs.createdAt ?? .distantPast) > (rhs.createdAt ?? .distantPast)
        }
        .prefix(8)
        .map(\.content)

    for content in memories {
        if let name = extractPersonName(content), seen.insert(name.lowercased()).inserted {
            candidates.append(name)
        }
    }

    return candidates
}

private static func extractPersonName(_ text: String) -> String? {
    let bulletPattern = #"•\s*([A-Z][A-Za-z'’-]+(?:\s+[A-Z][A-Za-z'’-]+){0,3})\s*[—-]"#
    if let match = firstMatch(text, pattern: bulletPattern) { return match }

    let contactPattern = #"\b([A-Z][A-Za-z'’-]+(?:\s+[A-Z][A-Za-z'’-]+){1,3})\s*[—-]\s*\+?[0-9]"#
    if let match = firstMatch(text, pattern: contactPattern) { return match }

    let pattern = #"\b([A-Z][A-Za-z'’-]+(?:\s+[A-Z][A-Za-z'’-]+){0,2})\b"#
    guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
    let ns = text as NSString
    let matches = regex.matches(in: text, range: NSRange(location: 0, length: ns.length))

        let blocked: Set<String> = ["Call", "Text", "Message", "Use", "Previous", "Search Contacts", "No", "Contacts", "Assistant", "User"]
        for match in matches.reversed() {
            let candidate = ns.substring(with: match.range(at: 1)).trimmingCharacters(in: .whitespacesAndNewlines)
            if candidate.count >= 3, !blocked.contains(candidate) {
                return candidate
            }
        }
        return nil
    }

    private static func firstMatch(_ text: String, pattern: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
        let ns = text as NSString
        guard let match = regex.firstMatch(in: text, range: NSRange(location: 0, length: ns.length)), match.numberOfRanges > 1 else { return nil }
        return ns.substring(with: match.range(at: 1)).trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

import Foundation
import SwiftData

@MainActor
enum RemCycleService {
    private static let minimumInterval: TimeInterval = 6 * 60 * 60
    private static var lastRunDate: Date?

    static func runIfDue(context: ModelContext, appState: AppState, reason: String) async {
        let now = Date()
        if let lastRunDate, now.timeIntervalSince(lastRunDate) < minimumInterval {
            return
        }
        lastRunDate = now
        await run(context: context, appState: appState, reason: reason, createdAt: now)
    }

    static func run(context: ModelContext, appState: AppState, reason: String, createdAt: Date = Date()) async {
        let catalog = storedModelCatalogSnapshot {
            try context.fetch(FetchDescriptor<StoredModel>())
        }
        let fleet = LumenModelFleetResolver.resolveV1(appState: appState, storedModels: catalog.stored)
        // Detached tasks are intentional here so parse-summary file IO does not inherit
        // the @MainActor isolation of this service. The loaders read immutable snapshots
        // and return Sendable Strings without touching SwiftData/AppState/UI state.
        let parseSummary = await Task.detached(priority: .utility) {
            AgentParseFailureSummaryLoader.developerText(topN: 5)
        }.value
        let noiseSummary = await Task.detached(priority: .utility) {
            AgentParseNoiseSummaryLoader.developerText(topN: 5)
        }.value

        let report = RemCycleReport(
            id: UUID(),
            createdAt: createdAt,
            reason: reason,
            runnableV1: fleet.isRunnableV1,
            missingSlots: fleet.missingSlots.map(\.rawValue),
            assignedSlots: fleet.assignments.keys.map(\.rawValue).sorted(),
            storedModelCount: catalog.stored.count,
            modelCatalogDiagnostic: catalog.diagnostic,
            activeChatModelID: appState.activeChatModelID,
            activeEmbeddingModelID: appState.activeEmbeddingModelID,
            parseFailureSummary: parseSummary,
            parseNoiseSummary: noiseSummary
        )

        write(report)

        do {
            try await MemoryCascade.condenseIfNeeded(context: context)
        } catch {
            // REM diagnostics are opportunistic and must never block runtime.
        }
    }

    private static func write(_ report: RemCycleReport) {
        do {

            let directory = try reportsDirectory()
            let url = directory.appendingPathComponent("rem-cycles.jsonl", isDirectory: false)
            let encoder = JSONEncoder()
            encoder.dateEncodingStrategy = .iso8601
            let data = try encoder.encode(report)
            var line = data
            line.append(0x0A)

            if FileManager.default.fileExists(atPath: url.path(percentEncoded: false)) {
                let handle = try FileHandle(forWritingTo: url)
                defer { try? handle.close() }
                try handle.seekToEnd()
                try handle.write(contentsOf: line)
            } else {
                try line.write(to: url, options: [.atomic])
            }
        } catch {
            // REM diagnostics are opportunistic and must never block runtime.
        }
    }

    static func reportsDirectory() throws -> URL {
        let base = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first
            ?? FileManager.default.temporaryDirectory
        let directory = base
            .appendingPathComponent("Diagnostics", isDirectory: true)
            .appendingPathComponent("REM", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        return directory
    }

    static func modelCatalogFetchFailureMessage(error: Error) -> String {
        ModelLaunchBootstrap.modelCatalogFetchFailureMessage(error: error)
    }

    static func storedModelCatalogSnapshotForTests(fetch: () throws -> [StoredModel]) -> RemStoredModelCatalogSnapshot {
        storedModelCatalogSnapshot(fetch: fetch)
    }

    private static func storedModelCatalogSnapshot(fetch: () throws -> [StoredModel]) -> RemStoredModelCatalogSnapshot {
        do {
            return RemStoredModelCatalogSnapshot(stored: try fetch(), diagnostic: nil)
        } catch {
            return RemStoredModelCatalogSnapshot(
                stored: [],
                diagnostic: modelCatalogFetchFailureMessage(error: error)
            )
        }
    }
}

struct RemStoredModelCatalogSnapshot {
    let stored: [StoredModel]
    let diagnostic: String?
}

