@MainActor
struct VoiceInterruptionHandler {
    nonisolated static func shouldInterruptOnBackground() -> Bool { true }
}

        let step = AgentStep(
            id: invocation.id,
            kind: .action,
            content: toolInvocationContent(invocation),
            toolID: invocation.toolID,
            toolArgs: toolArguments(invocation)
        )
        upsert(step, in: &state.steps)
        return VoiceKernelEventMutation(stepsChanged: true, shouldEmitStepFeedback: true)

    case .toolResult(let result):
        let step = AgentStep(
            kind: .observation,
            content: toolResultContent(result),
            toolID: nil,
            toolArgs: toolResultArguments(result)
        )
        state.steps.append(step)
        return VoiceKernelEventMutation(stepsChanged: true)

    case .diagnostic(let diagnostic):
        state.diagnostics.append(diagnostic)
        var mutation = VoiceKernelEventMutation(diagnosticsChanged: true)
        if isDegradedDiagnostic(diagnostic) {
            state.degraded = true
            upsertDegradedStep(from: diagnostic, in: &state.steps)
            mutation.stepsChanged = true
        }
        return mutation

    case .error(let message):
        state.errorMessage = message
        replaceVisibleTextIfPresent(message, state: &state, lastUserMessage: lastUserMessage, routing: routing)
        return VoiceKernelEventMutation(
            textChanged: true,
            shouldEmitUIUpdateDiagnostic: true,
            shouldStartSpeaking: true,
            shouldSpeakPending: true,
            shouldUseFinalResponseText: true
        )

    case .done(let finalText, let steps):
        replaceVisibleTextIfPresent(finalText, state: &state, lastUserMessage: lastUserMessage, routing: routing)
        if !steps.isEmpty {
            state.steps = steps
        }
        state.isDone = true
        return VoiceKernelEventMutation(
            textChanged: !finalText.isEmpty,
            stepsChanged: !steps.isEmpty,
            shouldStartSpeaking: !finalText.isEmpty,
            shouldSpeakPending: !finalText.isEmpty,
            shouldUseFinalResponseText: !finalText.isEmpty
        )
    }
}

static func cancel(state: inout VoiceKernelEventState, reason: String) -> VoiceKernelEventMutation {

    state.isCancelled = true
    state.cancellationReason = reason
    return VoiceKernelEventMutation()
}

static func streamingResponseText(
    from text: String,
    lastUserMessage: String
) -> String {
    let sanitized = AssistantOutputSanitizer.sanitize(text, lastUserMessage: lastUserMessage)
    return SchemaPlaceholderDetector.isPlaceholderPrefix(sanitized) ? "" : sanitized
}

static func finalResponseText(
    from text: String,
    lastUserMessage: String,
    routing: IntentRoutingDecision
) -> String {
    let sanitized = streamingResponseText(from: text, lastUserMessage: lastUserMessage)
    return FinalIntentValidator.validate(sanitized, routing: routing, fallback: nil)
}

private static func appendVisibleText(
    _ chunk: String,
    state: inout VoiceKernelEventState
) {
    state.finalText += chunk
    state.responseText = state.finalText
}

private static func replaceVisibleTextIfPresent(
    _ text: String,
    state: inout VoiceKernelEventState,
    lastUserMessage: String,
    routing: IntentRoutingDecision
) {
    guard !text.isEmpty else { return }
    state.finalText = text
    state.responseText = finalResponseText(from: text, lastUserMessage: lastUserMessage, routing: routing)
}

private static func upsert(_ step: AgentStep, in steps: inout [AgentStep]) {
    if let idx = steps.firstIndex(where: { $0.id == step.id }) {
        steps[idx] = step
    } else {
        steps.append(step)
    }
}

private static func toolInvocationContent(_ invocation: ToolInvocation) -> String {
    guard !invocation.arguments.isEmpty else {
        return "Invoking \(invocation.toolID)"
    }
    let arguments = invocation.arguments.keys.sorted()
        .map { key in "\(key)=\(invocation.arguments[key] ?? "")" }
        .joined(separator: ", ")
    return "Invoking \(invocation.toolID) with \(arguments)"
}

private static func toolArguments(_ invocation: ToolInvocation) -> [String: String] {
    var args = invocation.arguments
    args["invocationID"] = invocation.id.uuidString
    args["source"] = invocation.source.rawValue
    return args
}

private static func toolResultContent(_ result: ToolResult) -> String {

        let visible = result.displayText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !visible.isEmpty { return visible }

        let modelText = result.modelText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !modelText.isEmpty { return modelText }

        return "Tool result: \(result.status.rawValue)"
    }

    private static func toolResultArguments(_ result: ToolResult) -> [String: String] {
        var args: [String: String] = [
            "invocationID": result.invocationID.uuidString,
            "status": result.status.rawValue,
            "privacyLevel": result.privacyLevel.rawValue
        ]
        if !result.metricsSummary.isEmpty {
            args["metricsSummary"] = result.metricsSummary
        }
        if let errorCode = result.errorCode, !errorCode.isEmpty {
            args["errorCode"] = errorCode
        }
        return args
    }

    private static func isDegradedDiagnostic(_ diagnostic: AgentKernelDiagnosticEvent) -> Bool {
        if diagnostic.metadata["runtime"] == AssistantRuntimeKind.deterministicFallback.rawValue {
            return true
        }
        if diagnostic.metadata.values.contains(where: { value in
            let normalized = value.lowercased()
            return normalized.contains("fallback") || normalized.contains("degraded")
        }) {
            return true
        }
        let stage = diagnostic.stage.lowercased()
        let message = diagnostic.message.lowercased()
        return stage.contains("fallback")
            || stage.contains("degraded")
            || message.contains("fallback")
            || message.contains("degraded")
    }

    private static func upsertDegradedStep(
        from diagnostic: AgentKernelDiagnosticEvent,
        in steps: inout [AgentStep]
    ) {
        let content = diagnostic.message.isEmpty ? "Agent Kernel is running in degraded mode." : diagnostic.message
        if let idx = steps.firstIndex(where: { step in
            step.kind == .reflection && step.toolArgs?["diagnosticStage"] == diagnostic.stage
        }) {
            steps[idx].content = content
            return
        }

        steps.append(AgentStep(
            kind: .reflection,
            content: content,
            toolID: nil,
            toolArgs: ["diagnosticStage": diagnostic.stage]
        ))
    }
}

import Foundation
import Observation

@MainActor
@Observable
final class VoiceSessionController {
    var state: VoiceSessionState = .idle
    var partialTranscript: String = ""
    var finalTranscript: String = ""
    var lastErrorReason: String?

    private let recognition: SpeechRecognitionService
    private let synthesis: SpeechSynthesisService
    private let legacyVoice: VoiceService
    private var transcriptPollTask: Task<Void, Never>?
    private var transcriptPollCancellationID: UUID?

    init(
        recognition: SpeechRecognitionService? = nil,
        synthesis: SpeechSynthesisService? = nil,
        legacyVoice: VoiceService? = nil
    ) {
        self.recognition = recognition ?? SpeechRecognitionService()
        self.synthesis = synthesis ?? SpeechSynthesisService()
        self.legacyVoice = legacyVoice ?? .shared
    }

    func startPushToTalk(onFinal: @escaping (String) -> Void) async {
        state = .requestingPermissions
        let ok = await recognition.requestPermissions()
        guard ok else {
            lastErrorReason = "microphone_or_speech_denied"
            state = .denied("microphone_or_speech_denied")
            return
        }
        legacyVoice.stopSpeaking()
        let started = await legacyVoice.startListening(permissionsAlreadyGranted: true) { [weak self] text in
            Task { @MainActor in
                self?.stopTranscriptPolling()
                self?.finalTranscript = text
                self?.state = .processing
                onFinal(text)
            }
        }
        guard started else {
            let reason = legacyVoice.lastError ?? VoiceInputReadiness.unavailableMessage
            lastErrorReason = reason
            partialTranscript = ""
            state = .failed(reason)
            return
        }
        state = .listening
        partialTranscript = legacyVoice.liveTranscript
        startTranscriptPolling()
    }

    func finishListening() {
        stopTranscriptPolling()
        legacyVoice.finishListening()
        state = .processing
    }

    func pollTranscript() {
        partialTranscript = legacyVoice.liveTranscript
    }

    func startSpeaking() { state = .speaking }

    func speakChunk(_ text: String, voiceID: String?, rate: Double) {
        synthesis.stop()
        legacyVoice.speakChunk(text, voiceID: voiceID, rate: rate)
        state = .speaking
    }

    func stopSpeaking() {
        legacyVoice.stopSpeaking()
        synthesis.stop()
        if state == .speaking { state = .idle }
    }

    func handleAppDidEnterBackground() {
        if VoiceInterruptionHandler.shouldInterruptOnBackground() && (state == .listening || state == .speaking || state == .processing) {
            stopTranscriptPolling()
            legacyVoice.stopListening()
            legacyVoice.stopSpeaking()
            synthesis.stop()
            state = .interrupted
        }
    }

    func cancel() {
        stopTranscriptPolling()
        legacyVoice.stopListening()
        legacyVoice.stopSpeaking()
        synthesis.stop()
        partialTranscript = ""
        state = .idle
    }

    private func startTranscriptPolling() {
        stopTranscriptPolling()
        transcriptPollTask = Task { @MainActor in
            while !Task.isCancelled && state == .listening {
                partialTranscript = legacyVoice.liveTranscript
                try? await Task.sleep(for: .milliseconds(VoiceConversationPolicy.transcriptPollMilliseconds))
            }
        }
        if let transcriptPollTask {
            transcriptPollCancellationID = AppCancellationBus.shared.register(transcriptPollTask, category: .voiceRecognition)
        }
    }

    private func stopTranscriptPolling() {
        transcriptPollTask?.cancel()
        transcriptPollTask = nil
        if let transcriptPollCancellationID {
            AppCancellationBus.shared.unregister(transcriptPollCancellationID, category: .voiceRecognition)
            self.transcriptPollCancellationID = nil
        }
    }
}

nonisolated enum VoiceConversationPolicy {
    static let transcriptPollMilliseconds = 200
    static let streamingMinimumCharactersBeforeSoftBoundary = 48
}

nonisolated enum VoiceTurnCompletionPolicy {
    static func acceptsSpeechCompletion(turnID: UUID, activeSpeechTurnID: UUID?) -> Bool {
        activeSpeechTurnID == turnID
    }

    static func shouldResumeHandsFree(handsFree: Bool, turnID: UUID, activeSpeechTurnID: UUID?) -> Bool {
        handsFree && acceptsSpeechCompletion(turnID: turnID, activeSpeechTurnID: activeSpeechTurnID)
    }
}

nonisolated struct VoiceSpeechChunk: Equatable, Sendable {
    var text: String
    var nextOffset: Int
}

nonisolated enum VoiceStreamingChunker {

    private static let strongBoundaries: Set<Character> = [".", "!", "?", "\n"]
    private static let softBoundaries: Set<Character> = [",", ";", ":"]

    static func nextChunk(
        in text: String,
        startingAt offset: Int,
        finishedStreaming: Bool,
        minimumStreamingCharacters: Int = VoiceConversationPolicy.streamingMinimumCharactersBeforeSoftBoundary
    ) -> VoiceSpeechChunk? {
        let characters = Array(text)
        guard offset < characters.count else { return nil }
        let remaining = Array(characters[offset...])
        var end = remaining.count

        if !finishedStreaming {
            if let strongIndex = remaining.lastIndex(where: { strongBoundaries.contains($0) }) {
                end = strongIndex + 1
            } else if remaining.count >= minimumStreamingCharacters,
                      let softIndex = remaining.lastIndex(where: { softBoundaries.contains($0) }) {
                end = softIndex + 1
            } else {
                return nil
            }
        }

        let raw = String(remaining[..<end])
        return VoiceSpeechChunk(
            text: raw.trimmingCharacters(in: .whitespacesAndNewlines),
            nextOffset: offset + end
        )
    }
}

