            let finalPromptChars = request.systemPrompt.count + request.userMessage.count
            return LlamaStructuredPromptPreflightSnapshot(
                contextSize: 4_096,
                finalPromptChars: finalPromptChars,
                estimatedPromptTokens: max(1, finalPromptChars / 4)
