private func metricsStore() -> RuntimeMetricsStore {
    let url = URL(fileURLWithPath: NSTemporaryDirectory())
        .appendingPathComponent("self-improvement-\(UUID().uuidString).jsonl")
    return RuntimeMetricsStore(fileURL: url)
