    changed = False
    for gap in gaps:
        if not isinstance(gap, dict) or gap.get("category") != "testflight_runtime_pending":
            continue
        evidence = gap.get("evidence") if isinstance(gap.get("evidence"), dict) else {}
        evidence["expectedExport"] = CURRENT_EXPECTED_EXPORT
        evidence["source"] = CURRENT_EXPORT_SOURCE
        gap["evidence"] = evidence
        gap["recommendedAction"] = CURRENT_RECOMMENDED_ACTION
        changed = True
    if changed:
        write_json(path, payload)


def normalize_text_file(path: Path) -> None:
    if not path.exists():
        return
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return
    original = text
    for old, new in TEXT_REPLACEMENTS.items():
        text = text.replace(old, new)
    if text != original:
        path.write_text(text, encoding="utf-8")

    state = augment(args.loop_state, args.embedding_dir, visual_summary, args.reranker_dir)
    if args.print_summary:
        print(json.dumps({"embedding": state["embedding"], "reranker": state["reranker"]}, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


