    "baseModelTokenizerDigest",
    "baseModelTokenizerFiles",
    "baseModelTokenizerClosureSHA256",
    "baseModelGenerationConfigFile",
    "baseModelTokenizerSnapshotPath",
    "baseModelTokenizerSnapshotVerification",
