        if isinstance(value, list):
            return " ".join(
                str(message.get("content") or "")
                for message in value
                if isinstance(message, dict)
            )
        return str(value)

    return {
        "prompt": text(row["prompt"]),
        "chosen": text(row["chosen"]),
        "rejected": text(row["rejected"]),
    }


