def _private_tokenizer_snapshot(
    tmp_path: Path,
    payloads: dict[str, bytes],
) -> Path:
    snapshot = tmp_path / "private-tokenizer"
    snapshot.mkdir(mode=0o700)
    for filename, payload in payloads.items():
        path = snapshot / filename
        path.write_bytes(payload)
        path.chmod(0o400)
    return snapshot


