        or save_total_limit < PREFERENCE_CHECKPOINT_MINIMUM_RETENTION
    ):
        raise ValueError(
            "save_total_limit must retain at least two preference checkpoints"
        )
    return save_steps, save_total_limit


def _preference_training_code_sha256(
