def _fleet_sft_cycle_take(
    values: list[int],
    *,
    count: int,
    epoch_index: int,
    candidate_index: int,
) -> list[int]:
    if not values or count <= 0:
        return []
    offset = (epoch_index * count + candidate_index) % len(values)
    return [values[(offset + index) % len(values)] for index in range(count)]


