def validate_runtime_source(*, kind: Any, revision: Any) -> tuple[str, str]:
    if kind not in {"git", "huggingface_space"}:
        raise ValueError("runtimeSourceKind must be git or huggingface_space")
    if not isinstance(revision, str) or _REVISION_PATTERN.fullmatch(revision) is None:
        raise ValueError("runtimeSourceRevision must be a full lowercase commit SHA")
    return kind, revision


def validate_runtime_source_audit(
    value: Mapping[str, Any],
    *,
    observed_local_revision: str | None = None,
) -> dict[str, Any]:
    """Validate runtime-source audit semantics without overstating trust.

    A local Git source is accepted only when the caller independently observed
    the checkout's current HEAD and it agrees with every recorded revision.
    Hugging Face Space repository-head evidence remains supplemental: the Hub
    does not attest that the matching repository revision is the executing
    container revision, so that contract can never claim a verified binding.
    """

    if not isinstance(value, Mapping):
        raise ValueError("Runtime source audit must be an object")
    kind, expected_revision = validate_runtime_source(
        kind=value.get("runtimeSourceKind"),
        revision=value.get("expectedRuntimeSourceRevision"),
    )
    if value.get("runtimeSourceRevision") != expected_revision:
        raise ValueError("runtimeSourceRevision must equal the expected revision")

    observed_repository_revision = value.get("observedRepositoryRevision")
    observed_runtime_revision = value.get("observedRuntimeRevision")
    for label, revision in (
        ("observedRepositoryRevision", observed_repository_revision),
        ("observedRuntimeRevision", observed_runtime_revision),
    ):
        if revision is not None and (
            not isinstance(revision, str)
            or _REVISION_PATTERN.fullmatch(revision) is None
        ):
            raise ValueError(f"{label} must be null or a full lowercase commit SHA")

    status = value.get("runtimeSourceBindingStatus")

method = value.get("runtimeSourceBindingMethod")
if kind == "huggingface_space":
    if observed_runtime_revision is not None:
        raise ValueError(
            "Hugging Face Space runtime revision must remain unobserved without "
            "platform attestation"
        )
    if status != RUNTIME_SOURCE_BINDING_SPACE_UNVERIFIED:
        raise ValueError(
            "Hugging Face Space runtime source binding must remain "
            "operator_declared_unverified"
        )
    if method == RUNTIME_SOURCE_BINDING_SPACE_DECLARATION:
        if observed_repository_revision is not None:
            raise ValueError(
                "Operator-declared Space source cannot include repository-head "
                "evidence"
            )
    elif method == RUNTIME_SOURCE_BINDING_SPACE_REPOSITORY_HEAD:
        if observed_repository_revision != expected_revision:
            raise ValueError(
                "Supplemental Space repository head must equal the expected "
                "revision"
            )
    else:
        raise ValueError("Unsupported Hugging Face Space source binding method")
else:
    if (
        not isinstance(observed_local_revision, str)
        or _REVISION_PATTERN.fullmatch(observed_local_revision) is None
    ):
        raise ValueError(
            "Local Git runtime source requires an independently observed HEAD"
        )
    if observed_local_revision != expected_revision:
        raise ValueError(
            "Observed local Git HEAD does not match the expected runtime source"
        )
    if (
        observed_repository_revision != observed_local_revision
        or observed_runtime_revision != observed_local_revision
    ):
        raise ValueError(
            "Local runtime-source observations must equal the current Git HEAD"
        )
    if (status, method) not in {
        (
            RUNTIME_SOURCE_BINDING_LOCAL,
            RUNTIME_SOURCE_BINDING_LOCAL_METHOD,
        ),
        (
            RUNTIME_SOURCE_BINDING_ATTESTED,
            RUNTIME_SOURCE_BINDING_ATTESTED_METHOD,
        ),
    }:
        raise ValueError("Unsupported local Git runtime-source binding evidence")

return {

    field: value.get(field)
    for field in RUNTIME_SOURCE_AUDIT_FIELDS
}

def mount_identity_sha256(self) -> str | None:
    if self.mount_identity is None:
        return None
    return canonical_sha256(_mount_identity_payload(self.mount_identity))

def close(self) -> None:
    if self._closed:
        return
    self._closed = True
    for item in reversed((*self.files, *self.directories)):
        try:
            os.close(item.descriptor)
        except OSError:
            pass

def _verify_retained_descriptors(self) -> None:
    if self._closed:
        raise RuntimeError("Prepare-only input closure is already closed")
    for item in self.directories:
        try:
            observed = _file_stability_signature(os.fstat(item.descriptor))
        except OSError as exc:
            raise RuntimeError(
                "Prepare-only input directory descriptor became unavailable: "
                f"{item.relative_path}"
            ) from exc
        if observed != item.signature:
            raise RuntimeError(
                "Prepare-only input directory changed during verification: "
                f"{item.relative_path}"
            )
    for item in self.files:
        try:
            observed = _file_stability_signature(os.fstat(item.descriptor))
            observed_sha256 = _descriptor_sha256(item.descriptor)
            stable = _file_stability_signature(os.fstat(item.descriptor))
        except OSError as exc:
            raise RuntimeError(
                "Prepare-only input file descriptor became unavailable: "
                f"{item.relative_path}"
            ) from exc
        if (
            observed != item.signature
            or stable != item.signature
            or observed_sha256 != item.sha256
        ):
            raise RuntimeError(
                "Prepare-only input file changed during verification: "
                f"{item.relative_path}"
            )

def verify_unchanged(self) -> None:
    """Fail if any retained input or its current path binding changed."""

    self._verify_mount_boundary()
    _require_prepared_input_fd_headroom(
        len(self.directories) + len(self.files) + PREPARED_INPUT_FD_RESERVE
    )
    self._verify_retained_descriptors()

        observed = _acquire_prepared_input_closure_impl(
            self.run_root,
            require_exact_readonly_mount=self.require_exact_readonly_mount,
        )
        try:
            observed._verify_retained_descriptors()
            if (
                observed.inventory_sha256 != self.inventory_sha256
                or observed.inventory != self.inventory
            ):
                raise RuntimeError(
                    "Prepare-only input inventory or path binding changed during "
                    "verification"
                )
            # Recheck both descriptor sets after the path walk so a mutation
            # during the comparison cannot be accepted as a stable closure.
            observed._verify_retained_descriptors()
            self._verify_retained_descriptors()
            observed._verify_mount_boundary()
            self._verify_mount_boundary()
        finally:
            observed.close()


def _reject_nonfinite_json_constant(value: str) -> None:
    raise ValueError(f"Non-finite JSON number is not allowed: {value}")


def _reject_duplicate_json_keys(
    pairs: list[tuple[str, Any]],
) -> dict[str, Any]:
    value: dict[str, Any] = {}
    for key, item in pairs:
        if key in value:
            raise ValueError(f"Duplicate JSON key is not allowed: {key}")
        value[key] = item
    return value


def _parse_finite_json_float(value: str) -> float:
    parsed = float(value)
    if not math.isfinite(parsed):
        _reject_nonfinite_json_constant(value)
    return parsed


def _file_stability_signature(file_stat: os.stat_result) -> tuple[int, ...]:
    return (
        file_stat.st_dev,
        file_stat.st_ino,
        file_stat.st_mode,
        file_stat.st_size,
        file_stat.st_mtime_ns,
        file_stat.st_ctime_ns,
    )


def _read_descriptor_bytes(handle: BinaryIO) -> bytes:
    chunks: list[bytes] = []
    offset = 0
    while True:
        chunk = os.pread(handle.fileno(), 1 << 20, offset)
        if not chunk:
            return b"".join(chunks)
        chunks.append(chunk)
        offset += len(chunk)


def _descriptor_sha256(descriptor: int) -> str:
    digest = hashlib.sha256()
    offset = 0
    while True:
        chunk = os.pread(descriptor, 1 << 20, offset)
        if not chunk:
            return digest.hexdigest()
        digest.update(chunk)
        offset += len(chunk)

def _git_blob_sha1(payload: bytes) -> str:
    header = f"blob {len(payload)}\0".encode("ascii")
    return hashlib.sha1(header + payload, usedforsecurity=False).hexdigest()


def _open_regular_readonly(path: Path, *, label: str) -> tuple[BinaryIO, os.stat_result]:
    if path.is_symlink():
        raise RuntimeError(f"{label} must not be a symlink: {path}")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    if nofollow == 0:
        raise RuntimeError(f"{label} verification requires O_NOFOLLOW support")
    try:
        descriptor = os.open(path, flags | nofollow)
    except OSError as exc:
        raise RuntimeError(f"{label} is unavailable: {path}") from exc
    try:
        file_stat = os.fstat(descriptor)
        if not stat.S_ISREG(file_stat.st_mode):
            raise RuntimeError(f"{label} must be a regular file: {path}")
        return os.fdopen(descriptor, "rb", closefd=True), file_stat
    except BaseException:
        os.close(descriptor)
        raise


def _require_stable_descriptor(
    handle: BinaryIO,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    if _file_stability_signature(os.fstat(handle.fileno())) != _file_stability_signature(
        expected
    ):
        raise RuntimeError(f"{label} changed while it was being verified")


def _require_path_matches_descriptor(
    path: Path,
    expected: os.stat_result,
    *,
    label: str,
) -> None:
    try:
        current = os.stat(path, follow_symlinks=False)
    except OSError as exc:
        raise RuntimeError(f"{label} changed while it was being verified") from exc
    if (
        not stat.S_ISREG(current.st_mode)
        or current.st_dev != expected.st_dev
        or current.st_ino != expected.st_ino
    ):
        raise RuntimeError(f"{label} changed while it was being verified")


