def epoch_order(epoch_index: int, candidate_index: int) -> list[int]:
    def rotated(values: list[int]) -> list[int]:
        offset = (
            epoch_index * len(values) + candidate_index
        ) % len(values)
        return [
            values[(offset + index) % len(values)]
            for index in range(len(values))
        ]

