                {
                    "algorithm": (
                        _FLEET_SFT_OPTIMIZER_WINDOW_SCHEDULE_ALGORITHM
                    ),
                    "seed": seed,
                    "epochIndex": epoch_index,
                    "candidateIndex": candidate_index,
                    "role": "optimizer_window",
                    "windowIndex": window_index,
