            window_index,
        ),
    )
    windows: list[list[int]] = [[] for _ in window_sizes]
    cursor = 0
    for row_index in native_samples:
        for _ in window_order:
            window_index = window_order[cursor % len(window_order)]
            cursor += 1
            if len(windows[window_index]) < window_sizes[window_index]:
