    lowered = name.lower()
    type_l = arg_type.lower()
    if type_l in {"null", "none", "nil"}:
        return None
    if type_l in {"bool", "boolean"}:
        return True
    if type_l in {"int", "integer"}:
        if "limit" in lowered or "count" in lowered:
            return 5
