        return "item-train-042"
    if "folder" in lowered:
        return "Projects"
    if "alarm" in lowered:
        return "work-shift"

    if "title" in lowered:
        return "Supplier call"
    if "subject" in lowered:
        return "Project update"
    if "body" in lowered or "content" in lowered or "message" in lowered:
        return "I will arrive in 10 minutes."
    if "query" in lowered:
