def _clean_text(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    normalized = value.replace("\r\n", "\n").replace("\r", "\n").strip()
    if not (MIN_TEXT_CHARS <= len(normalized) <= MAX_TEXT_CHARS):
        return None
    if _CONTROL_RE.search(normalized):
