        if any(entry.is_symlink() or not entry.is_file() for entry in entries):
            return False
    if not all(
        (primary / filename).read_bytes()
        == (mirror / filename).read_bytes()
        for filename in CROSS_MODEL_ARTIFACT_FILENAMES
    ):
