    def canonical_output(content: str) -> str:
        try:
            return json.dumps(json.loads(content), ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        except json.JSONDecodeError:
            return " ".join(content.split())

    for agent in AGENTS:
